namespace {

// Complete all in-flight GPU work before a control-flow primitive touches
// its inputs (jax-mps#195). WhileLoopPrimitive / CasePrimitive run on the
// CPU stream *inside* an enclosing eval pass; their inputs typically have
// status == evaluated, which only means the producing kernels were ENCODED —
// the GPU command buffer may not have been committed, let alone completed.
// MLX's eval fences only inputs that were unscheduled within the same pass,
// so nothing orders the primitive's re-entrant evals and scalar readbacks
// (case index, while cond, trip count) after the producing GPU work. The
// race was caught red-handed on the jax-mps#195 MRE: the case branch index
// read garbage (e.g. 73, or a float bit-pattern) before a GPU sync and the
// true 0/1 after, silently selecting the wrong branch.
void SyncGpuStream() {
    mlx::core::synchronize(mlx::core::default_stream(mlx::core::Device::gpu));
}

// Shared unary op table used by both the mhlo.* custom_call path (HandleCustomCall)
// and the chlo.* composite path (HandleComposite). Keyed by the bare op name as a
// string_view pointing into the static string literals below, so callers can
// probe with a string_view into the original op name without allocating.
const std::unordered_map<std::string_view, UnaryMlxFn>& UnaryMlxOps() {
    static const std::unordered_map<std::string_view, UnaryMlxFn> kOps = {
        {"sinh", mlx::core::sinh},      {"cosh", mlx::core::cosh},
        {"tan", mlx::core::tan},        {"asin", mlx::core::arcsin},
        {"acos", mlx::core::arccos},    {"atan", mlx::core::arctan},
        {"asinh", mlx::core::arcsinh},  {"acosh", mlx::core::arccosh},
        {"atanh", mlx::core::arctanh},  {"erf", mlx::core::erf},
        {"erf_inv", mlx::core::erfinv},
    };
    return kOps;
}

// Parse the custom_call's backend_config (a JSON string, emitted by our Python
// lowerings in src/jax_plugins/mps/ops.py) into a JSON object. Returns an empty
// object on any failure, so callers can freely probe for keys with defaults.
//
// Note: unregistered MLIR attributes (e.g. `mhlo.backend_config = {...}`) do
// not round-trip through StableHLO portable artifacts, so we can't pass a
// typed DictAttr here — JSON-in-a-string is the stable wire format.
llvm::json::Object ParseBackendConfig(mlir::stablehlo::CustomCallOp op) {
    auto bcAttr = op.getBackendConfig();
    if (!bcAttr)
        return {};
    auto strAttr = mlir::dyn_cast<mlir::StringAttr>(*bcAttr);
    if (!strAttr || strAttr.getValue().empty())
        return {};
    auto parsed = llvm::json::parse(strAttr.getValue());
    if (!parsed) {
        llvm::consumeError(parsed.takeError());
        return {};
    }
    if (auto* obj = parsed->getAsObject())
        return std::move(*obj);
    return {};
}

// Convert a boolean mask to an additive attention mask (true -> 0, false -> -1e9)
// cast to the given dtype so MLX's SDPA type check passes with float16.
mlx::core::array BoolMaskToAdditive(const mlx::core::array& mask, mlx::core::Dtype dtype) {
    return mlx::core::astype(
        mlx::core::where(mask, mlx::core::array(0.0F), mlx::core::array(-1e9F)), dtype);
}

// Normalize an SDPA mask to an additive bias. A boolean mask is converted
// (True -> 0, False -> -1e9); a float mask is already an additive bias (used by
// e.g. relative-position / ALiBi attention) and is just cast to the compute dtype.
mlx::core::array MaskToAdditive(const mlx::core::array& mask, mlx::core::Dtype dtype) {
    if (mask.dtype() == mlx::core::bool_)
        return BoolMaskToAdditive(mask, dtype);
    return mlx::core::astype(mask, dtype);
}

// A valid SDPA mask is either a boolean gating mask or a floating additive bias.
// Anything else (integer, complex) would silently change semantics via
// MaskToAdditive, so handlers reject it instead.
bool IsValidSdpaMaskDtype(const mlx::core::array& mask) {
    return mask.dtype() == mlx::core::bool_ ||
           mlx::core::issubdtype(mask.dtype(), mlx::core::floating);
}

// Common helper for return-like operations (func.return, stablehlo.return)
bool CollectReturnValues(mlir::Operation* op, ValueMap& values,
                         std::vector<mlx::core::array>& outputs, const char* opName) {
    for (auto operand : op->getOperands()) {
        auto* val = RequireValue(values, operand, opName);
        if (!val)
            return false;
        outputs.push_back(*val);
    }
    return true;
}

// Handler for func.return
bool HandleReturn(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                  ExecContext& ctx) {
    return CollectReturnValues(op, values, outputs, "func.return");
}

// Handler for stablehlo.return (region terminator)
bool HandleStablehloReturn(mlir::Operation* op, ValueMap& values,
                           std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    return CollectReturnValues(op, values, outputs, "stablehlo.return");
}

// Collect arrays referenced inside a region but defined outside it.
// These must be passed as explicit inputs to mx::compile to avoid
// the "uncaptured inputs" error. An optional `seen` set enables
// deduplication across multiple regions (e.g., body + cond).
//
// Uses region.walk() to recursively traverse nested sub-regions (e.g.
// reduce bodies, case branches) so external values used at any nesting
// depth are captured. The isAncestor guard filters out block arguments
// and SSA values defined inside the region at any level.
void CollectExternalValues(mlir::Region& region, const ValueMap& values, std::vector<void*>& keys,
                           std::vector<mlx::core::array>& arrays,
                           std::unordered_set<void*>* seen = nullptr) {
    std::unordered_set<void*> localSeen;
    auto& seenRef = seen ? *seen : localSeen;

    region.walk([&](mlir::Operation* op) {
        for (auto operand : op->getOperands()) {
            auto* key = ToKey(operand);
            if (seenRef.count(key))
                continue;

            // Skip values defined inside this region (at any nesting level).
            // For block arguments, check their parent region.
            // For SSA values, check their defining op's parent region.
            if (auto* defOp = operand.getDefiningOp()) {
                if (region.isAncestor(defOp->getParentRegion()))
                    continue;
            } else {
                // Block argument — skip if it belongs to this region or a
                // nested sub-region (e.g. reduce body accumulators).
                if (region.isAncestor(operand.getParentRegion()))
                    continue;
            }

            auto it = values.find(key);
            if (it != values.end()) {
                seenRef.insert(key);
                keys.push_back(key);
                arrays.push_back(it->second);
            }
        }
    });
}

// ---------------------------------------------------------------------------
// Counted-loop detection (jax-mps#193)
//
// lax.fori_loop / lax.scan lower to a canonical counted while loop:
//
//   cond { %c = stablehlo.compare LT, %counterArg, %limit; return %c }
//   do   { ...; %next = stablehlo.add %counterArg, <const step>; return %next, ... }
//
// with a loop-invariant %limit. For this shape the trip count is computable
// before the loop runs, so WhileLoopPrimitive can skip the per-iteration
// cond eval + host readback that otherwise costs ~500us per iteration.
// ---------------------------------------------------------------------------

// Result of DetectCountedLoop. The limit is exactly one of:
//   staticLimit     — an IR constant (typical for scan/fori with static bounds)
//   limitLoopVarIdx — a pass-through loop variable
//   limitExternal   — a non-constant value defined outside the while op
struct CountedLoopInfo {
    size_t counterIdx = 0;
    int64_t step = 1;
    bool isUnsigned = false;
    std::optional<int64_t> staticLimit;
    std::optional<size_t> limitLoopVarIdx;
    mlir::Value limitExternal;
};

// Extract a splat integer constant as int64, honoring compare signedness.
// Returns nullopt for non-constants, non-splat values, or unsigned values
// that do not fit in int64.
std::optional<int64_t> MatchIntSplatConstant(mlir::Value v, bool isUnsigned) {
    mlir::DenseIntElementsAttr attr;
    if (!mlir::matchPattern(v, mlir::m_Constant(&attr)) || !attr.isSplat())
        return std::nullopt;
    llvm::APInt val = attr.getSplatValue<llvm::APInt>();
    if (isUnsigned) {
        if (val.ugt(std::numeric_limits<int64_t>::max()))
            return std::nullopt;
        return static_cast<int64_t>(val.getZExtValue());
    }
    return val.getSExtValue();
}

std::optional<CountedLoopInfo> DetectCountedLoop(mlir::stablehlo::WhileOp whileOp) {
    auto& condRegion = whileOp.getCond();
    auto& bodyRegion = whileOp.getBody();
    if (!condRegion.hasOneBlock() || !bodyRegion.hasOneBlock())
        return std::nullopt;
    auto& condBlock = condRegion.front();
    auto& bodyBlock = bodyRegion.front();

    // cond must be: return(compare(LT, blockArg[k], limit))
    auto retOp = mlir::dyn_cast<mlir::stablehlo::ReturnOp>(condBlock.getTerminator());
    if (!retOp || retOp.getNumOperands() != 1)
        return std::nullopt;
    auto cmp = retOp.getOperand(0).getDefiningOp<mlir::stablehlo::CompareOp>();
    if (!cmp || cmp.getComparisonDirection() != mlir::stablehlo::ComparisonDirection::LT)
        return std::nullopt;

    auto counterArg = mlir::dyn_cast<mlir::BlockArgument>(cmp.getLhs());
    if (!counterArg || counterArg.getOwner() != &condBlock)
        return std::nullopt;

    // Counter must be a rank-0 integer tensor (not bool).
    auto counterTy = mlir::dyn_cast<mlir::RankedTensorType>(counterArg.getType());
    if (!counterTy || counterTy.getRank() != 0)
        return std::nullopt;
    auto intTy = mlir::dyn_cast<mlir::IntegerType>(counterTy.getElementType());
    if (!intTy || intTy.getWidth() == 1)
        return std::nullopt;

    CountedLoopInfo info;
    info.counterIdx = counterArg.getArgNumber();

    // Comparison signedness: explicit SIGNED/UNSIGNED, or inferred from the
    // element type when absent/NOTYPE. FLOAT/TOTALORDER cannot apply to ints.
    auto cmpType = cmp.getCompareType();
    if (!cmpType || *cmpType == mlir::stablehlo::ComparisonType::NOTYPE) {
        info.isUnsigned = intTy.isUnsigned();
    } else if (*cmpType == mlir::stablehlo::ComparisonType::SIGNED) {
        info.isUnsigned = false;
    } else if (*cmpType == mlir::stablehlo::ComparisonType::UNSIGNED) {
        info.isUnsigned = true;
    } else {
        return std::nullopt;
    }

    // Body must advance the counter by a constant positive step:
    // result[k] = add(blockArg[k], <const>) (either operand order).
    auto* bodyRet = bodyBlock.getTerminator();
    if (bodyRet->getNumOperands() <= info.counterIdx)
        return std::nullopt;
    auto add = bodyRet->getOperand(info.counterIdx).getDefiningOp<mlir::stablehlo::AddOp>();
    if (!add)
        return std::nullopt;
    auto matchCounterPlusConst = [&](mlir::Value argSide,
                                     mlir::Value constSide) -> std::optional<int64_t> {
        auto arg = mlir::dyn_cast<mlir::BlockArgument>(argSide);
        if (!arg || arg.getOwner() != &bodyBlock || arg.getArgNumber() != info.counterIdx)
            return std::nullopt;
        return MatchIntSplatConstant(constSide, info.isUnsigned);
    };
    auto step = matchCounterPlusConst(add.getLhs(), add.getRhs());
    if (!step)
        step = matchCounterPlusConst(add.getRhs(), add.getLhs());
    if (!step || *step <= 0)
        return std::nullopt;
    info.step = *step;

    // Classify the limit: constant, pass-through loop var, or external value.
    mlir::Value limit = cmp.getRhs();
    if (auto staticLimit = MatchIntSplatConstant(limit, info.isUnsigned)) {
        info.staticLimit = staticLimit;
        return info;
    }
    if (auto limitArg = mlir::dyn_cast<mlir::BlockArgument>(limit)) {
        if (limitArg.getOwner() != &condBlock)
            return std::nullopt;
        // The body must pass this loop var through unchanged.
        size_t m = limitArg.getArgNumber();
        auto passthrough = mlir::dyn_cast<mlir::BlockArgument>(bodyRet->getOperand(m));
        if (!passthrough || passthrough.getOwner() != &bodyBlock || passthrough.getArgNumber() != m)
            return std::nullopt;
        info.limitLoopVarIdx = m;
        return info;
    }
    // Non-constant SSA value: loop-invariant iff defined outside the while.
    auto* defOp = limit.getDefiningOp();
    if (!defOp || condRegion.isAncestor(defOp->getParentRegion()))
        return std::nullopt;
    info.limitExternal = limit;
    return info;
}

// Read a concrete rank-0 integer array as int64, interpreting the raw bits
// per the loop's compare signedness (StableHLO integers are signless; the
// compare op carries the signedness). Returns nullopt for non-integer dtypes
// or unsigned values that do not fit in int64.
std::optional<int64_t> ReadIntScalar(const mlx::core::array& a, bool isUnsigned) {
    auto arr = a;  // item() is non-const
    auto d = arr.dtype();
    if (d == mlx::core::int8)
        return isUnsigned ? static_cast<int64_t>(static_cast<uint8_t>(arr.item<int8_t>()))
                          : static_cast<int64_t>(arr.item<int8_t>());
    if (d == mlx::core::int16)
        return isUnsigned ? static_cast<int64_t>(static_cast<uint16_t>(arr.item<int16_t>()))
                          : static_cast<int64_t>(arr.item<int16_t>());
    if (d == mlx::core::int32)
        return isUnsigned ? static_cast<int64_t>(static_cast<uint32_t>(arr.item<int32_t>()))
                          : static_cast<int64_t>(arr.item<int32_t>());
    if (d == mlx::core::int64) {
        int64_t v = arr.item<int64_t>();
        if (isUnsigned && v < 0)
            return std::nullopt;  // unsigned value beyond int64 range
        return v;
    }
    if (d == mlx::core::uint8)
        return static_cast<int64_t>(arr.item<uint8_t>());
    if (d == mlx::core::uint16)
        return static_cast<int64_t>(arr.item<uint16_t>());
    if (d == mlx::core::uint32)
        return static_cast<int64_t>(arr.item<uint32_t>());
    if (d == mlx::core::uint64) {
        uint64_t v = arr.item<uint64_t>();
        if (v > static_cast<uint64_t>(std::numeric_limits<int64_t>::max()))
            return std::nullopt;
        return static_cast<int64_t>(v);
    }
    return std::nullopt;
}

// Runtime parameters for the counted fast path, resolved against the
// primitive's input layout (loop vars first, then external captures).
struct CountedExec {
    size_t counterInputIdx = 0;
    int64_t step = 1;
    bool isUnsigned = false;
    std::optional<int64_t> staticLimit;   // set iff the limit is an IR constant
    std::optional<size_t> limitInputIdx;  // otherwise: index into inputs
};

// Custom MLX primitive that encapsulates a while-loop with compiled body
// and per-step eval. This is opaque to mx::compile (won't be fused) but
// doesn't prevent outer compilation. When eval is called on the compiled
// graph, this primitive runs the loop with per-step eval internally.
//
// Stream placement: This primitive MUST run on the CPU stream, but this does
// NOT move computation to CPU. The compiled body+cond function
// (compiledBodyCond_) internally dispatches GPU kernels via MLX's default GPU
// stream — the CPU side only orchestrates the loop: call body+cond →
// mlx::core::eval() to flush + sync GPU work → read scalar cond → update loop
// vars → repeat.
//
// Why not the GPU stream: eval() synchronizes the GPU command queue. Calling
// it from within a GPU stream eval callback would re-enter the GPU scheduler,
// causing a deadlock. The CPU stream avoids this.

class WhileLoopPrimitive : public mlx::core::Primitive {
public:
    using BodyFn =
        std::function<std::vector<mlx::core::array>(const std::vector<mlx::core::array>&)>;
    using CondFn =
        std::function<std::vector<mlx::core::array>(const std::vector<mlx::core::array>&)>;
    using CompiledFn =
        std::function<std::vector<mlx::core::array>(const std::vector<mlx::core::array>&)>;

    // condFn: evaluates the loop condition (for the initial check).
    // bodyCondFn: evaluates body THEN cond, returns [condScalar, bodyResult0, ...].
    //   This combined function lets us eval() the full body+cond graph
    //   synchronously each iteration, bounding graph depth to one iteration
    //   and avoiding async_eval deadlocks with nested WhileLoopPrimitives.
    // counted: when set, the loop's trip count is computed up front and the
    //   per-iteration cond eval + host readback is skipped (jax-mps#193).
    // bodyHasControlFlow: set by the body/cond trace when the regions contain
    //   nested control-flow primitives (while/case). The counted path uses it
    //   to decide whether the periodic flush may be async (see eval_impl).
    // hasEffects: the body or cond contains side-effecting host callbacks.
    //   cond/bodyCond functions then return their effect markers after the
    //   cond/body results, every iteration is evaluated synchronously (no
    //   counted fast path, which would skip cond effects), and the primitive
    //   gets a trailing scalar effect-marker output.
    WhileLoopPrimitive(mlx::core::Stream stream, CondFn condFn, BodyFn bodyCondFn, size_t nLoopVars,
                       size_t nExt, std::optional<CountedExec> counted = std::nullopt,
                       std::shared_ptr<std::atomic<bool>> bodyHasControlFlow = nullptr,
                       bool hasEffects = false)
        : Primitive(stream),
          compiledBodyCond_(mlx::core::compile(std::move(bodyCondFn))),
          compiledCond_(mlx::core::compile(std::move(condFn))),
          nLoopVars_(nLoopVars),
          nExt_(nExt),
          counted_(hasEffects ? std::nullopt : counted),
          bodyHasControlFlow_(std::move(bodyHasControlFlow)),
          hasEffects_(hasEffects) {
        if (stream.device.type != mlx::core::Device::cpu) {
            throw std::runtime_error(
                "WhileLoopPrimitive must be on the CPU stream \u2014 GPU stream "
                "placement would deadlock on internal eval() calls");
        }
    }

    void eval_cpu(const std::vector<mlx::core::array>& inputs,
                  std::vector<mlx::core::array>& outputs) override {
        eval_impl(inputs, outputs);
    }

    void eval_gpu(const std::vector<mlx::core::array>& inputs,
                  std::vector<mlx::core::array>& outputs) override {
        eval_impl(inputs, outputs);
    }

    const char* name() const override {
        return "WhileLoop";
    }

    bool is_equivalent(const mlx::core::Primitive& other) const override {
        return false;
    }

    std::vector<mlx::core::Shape> output_shapes(
        const std::vector<mlx::core::array>& inputs) override {
        std::vector<mlx::core::Shape> shapes;
        shapes.reserve(nLoopVars_ + 1);
        for (size_t i = 0; i < nLoopVars_; ++i)
            shapes.push_back(inputs[i].shape());
        if (hasEffects_)
            shapes.push_back({});
        return shapes;
    }

private:
    void eval_impl(const std::vector<mlx::core::array>& inputs,
                   std::vector<mlx::core::array>& outputs) {
        // Order this loop's readbacks and body evals after all in-flight GPU
        // work (see SyncGpuStream): the trip-count scalars and the first
        // iteration's body read the primitive's inputs, which the enclosing
        // eval pass may still be producing.
        SyncGpuStream();
        // inputs = loopVars (nLoopVars_) + external values (nExt_)
        std::vector<mlx::core::array> current(inputs.begin(), inputs.end());

        // Validate input arity: loop vars + external captures.
        if (current.size() != nLoopVars_ + nExt_)
            throw std::runtime_error("WhileLoopPrimitive: expected " +
                                     std::to_string(nLoopVars_ + nExt_) + " inputs, got " +
                                     std::to_string(current.size()));

        if (auto tripCount = ComputeTripCount(inputs)) {
            // Counted fast path (jax-mps#193): the trip count is known before
            // the loop runs, so no per-iteration cond eval / host readback is
            // needed. Chain the compiled body lazily and flush every
            // kEvalInterval iterations — this bounds lazy-graph growth and
            // lets GPU work start while later iterations are still being
            // recorded. Primitive inputs are concrete when eval runs, so the
            // counter/limit scalar reads in ComputeTripCount are free.
            //
            // The periodic flush is async_eval when the body traced no nested
            // control-flow primitives: async_eval encodes + commits the GPU
            // work and returns without waiting, so recording the next batch
            // overlaps GPU execution. With nested while/case in the body it
            // must be a synchronous eval: the nested primitive's re-entrant
            // eval() would wait on input events that an enclosing async_eval
            // pass attaches but only signals at its end (the same deadlock
            // documented for JAX_MPS_ASYNC_DISPATCH in mlx_executable.cc).
            // The trace runs on the first compiledBodyCond_ call (i == 0),
            // so the flag is always set before the first flush.
            constexpr int64_t kEvalInterval = 64;
            for (int64_t i = 0; i < *tripCount; ++i) {
                auto combined = compiledBodyCond_(current);
                if (combined.size() != 1 + nLoopVars_)
                    throw std::runtime_error("WhileLoopPrimitive: bodyCondFn returned " +
                                             std::to_string(combined.size()) +
                                             " results, expected " +
                                             std::to_string(1 + nLoopVars_));
                // combined[0] (the cond scalar) is ignored — the trip count
                // already determines loop exit.
                for (size_t j = 0; j < nLoopVars_; ++j)
                    current[j] = std::move(combined[1 + j]);
                if ((i + 1) % kEvalInterval == 0) {
                    using Diff = std::vector<mlx::core::array>::difference_type;
                    std::vector<mlx::core::array> vars(
                        current.begin(), current.begin() + static_cast<Diff>(nLoopVars_));
                    const bool nestedControlFlow =
                        bodyHasControlFlow_ && bodyHasControlFlow_->load(std::memory_order_relaxed);
                    if (nestedControlFlow)
                        mlx::core::eval(vars);
                    else
                        mlx::core::async_eval(vars);
                    // Surface exceptions parked by stream worker threads (MLX
                    // patch 10): a failed body kernel otherwise feeds garbage
                    // into subsequent iterations while the error stays hidden.
                    mlx::core::scheduler::rethrow_pending_exception();
                }
            }
        } else {
            // Dynamic path: per-iteration cond eval + host readback.
            //
            // Initial condition check (before first body execution).
            auto initCond = compiledCond_(current);
            if (initCond.empty() || initCond[0].size() != 1)
                throw std::runtime_error("WhileLoopPrimitive: cond must return a single scalar");
            mlx::core::eval(initCond);
            mlx::core::scheduler::rethrow_pending_exception();
            bool condTrue = initCond[0].item<bool>();

            // Loop: body+cond combined per iteration.
            while (condTrue) {
                auto combined = compiledBodyCond_(current);
                if (combined.size() < 1 + nLoopVars_)
                    throw std::runtime_error("WhileLoopPrimitive: bodyCondFn returned " +
                                             std::to_string(combined.size()) +
                                             " results, expected " +
                                             std::to_string(1 + nLoopVars_));
                // Synchronous eval — bounded graph, no accumulation, safe
                // re-entry for nested WhileLoopPrimitives.
                mlx::core::eval(combined);
                // Surface parked stream-thread exceptions before reading the
                // cond scalar: a failed body kernel would otherwise yield a
                // garbage condition and can spin the loop indefinitely.
                mlx::core::scheduler::rethrow_pending_exception();

                // Update loop vars from combined[1..nLoopVars]
                for (size_t j = 0; j < nLoopVars_; ++j)
                    current[j] = std::move(combined[1 + j]);
                // Check condition from combined[0]
                condTrue = combined[0].item<bool>();
            }
        }

        // Synchronize final results
        using Diff = std::vector<mlx::core::array>::difference_type;
        std::vector<mlx::core::array> finalVars(current.begin(),
                                                current.begin() + static_cast<Diff>(nLoopVars_));
        mlx::core::eval(finalVars);
        mlx::core::scheduler::rethrow_pending_exception();

        for (size_t i = 0; i < nLoopVars_; ++i)
            outputs[i].copy_shared_buffer(current[i]);
        if (hasEffects_) {
            auto& marker = outputs[nLoopVars_];
            marker.set_data(mlx::core::allocator::malloc(marker.nbytes()));
            std::memset(marker.data<char>(), 0, marker.nbytes());
        }
    }

    // Trip count for the counted fast path, or nullopt to use the dynamic
    // per-iteration cond loop (not a counted loop, or a scalar read failed).
    std::optional<int64_t> ComputeTripCount(const std::vector<mlx::core::array>& inputs) const {
        if (!counted_)
            return std::nullopt;
        auto init = ReadIntScalar(inputs[counted_->counterInputIdx], counted_->isUnsigned);
        if (!init)
            return std::nullopt;
        std::optional<int64_t> limit = counted_->staticLimit;
        if (!limit && counted_->limitInputIdx)
            limit = ReadIntScalar(inputs[*counted_->limitInputIdx], counted_->isUnsigned);
        if (!limit)
            return std::nullopt;
        if (*limit <= *init)
            return 0;
        // Unsigned arithmetic: limit - init in signed int64 could overflow for
        // extreme int64 counters, but the wrapped difference is exact in uint64.
        uint64_t diff = static_cast<uint64_t>(*limit) - static_cast<uint64_t>(*init);
        auto step = static_cast<uint64_t>(counted_->step);
        uint64_t count = diff / step + (diff % step != 0 ? 1 : 0);
        // A trip count beyond int64 (possible only for extreme int64 bounds)
        // would wrap negative and silently skip the loop — fall back to the
        // dynamic path instead.
        if (count > static_cast<uint64_t>(std::numeric_limits<int64_t>::max()))
            return std::nullopt;
        return static_cast<int64_t>(count);
    }

    // Public mlx::core::compile() returns a std::function whose internal
    // shared_ptr deleter calls compile_erase when the last copy dies. Cache
    // eviction is tied to this primitive's lifetime — no manual erase needed.
    CompiledFn compiledBodyCond_;  // returns [cond, body...]
    CompiledFn compiledCond_;      // initial check only
    size_t nLoopVars_;
    size_t nExt_;
    std::optional<CountedExec> counted_;
    // Set during the body/cond trace; gates the async periodic flush.
    std::shared_ptr<std::atomic<bool>> bodyHasControlFlow_;
    bool hasEffects_;
};

// Custom MLX primitive that encapsulates a multi-branch case/switch with
// compiled branches and CPU-orchestrated branch selection. This is opaque to
// mx::compile (won't be fused) but doesn't prevent outer compilation.
//
// Stream placement: Same rationale as WhileLoopPrimitive — MUST run on the
// CPU stream. The CPU side reads the branch index scalar, selects the
// appropriate compiled branch function, and calls it. The compiled branch
// internally dispatches GPU kernels via MLX's default GPU stream.
//
// All branches are pre-compiled at construction time. Only the selected
// branch executes at eval time.
class CasePrimitive : public mlx::core::Primitive {
public:
    using CompiledFn =
        std::function<std::vector<mlx::core::array>(const std::vector<mlx::core::array>&)>;

    // indexFn: compiled function that takes external values and returns [index_scalar].
    //   This is evaluated at runtime to determine which branch to take, ensuring
    //   that mx::compile correctly re-evaluates the index from function arguments.
    // branches: one compiled function per branch region.
    //   Each takes external values as inputs and returns branch results.
    // nOutputs: number of outputs (same for all branches, from MLIR types).
    // nExt: number of external captures threaded as inputs.
    // outShapes: output shapes from MLIR result types, plus one trailing scalar
    //   effect marker when a branch contains side-effecting host callbacks.
    //   Branch functions return their results followed by their effect markers;
    //   all of them are evaluated, only the results are copied out.
    CasePrimitive(mlx::core::Stream stream, CompiledFn indexFn, std::vector<CompiledFn> branches,
                  size_t nOutputs, size_t nExt, std::vector<mlx::core::Shape> outShapes)
        : Primitive(stream),
          indexFn_(std::move(indexFn)),
          branches_(std::move(branches)),
          nOutputs_(nOutputs),
          nExt_(nExt),
          outShapes_(std::move(outShapes)) {
        if (stream.device.type != mlx::core::Device::cpu) {
            throw std::runtime_error(
                "CasePrimitive must be on the CPU stream — GPU stream "
                "placement would deadlock on internal eval() calls");
        }
    }

    void eval_cpu(const std::vector<mlx::core::array>& inputs,
                  std::vector<mlx::core::array>& outputs) override {
        eval_impl(inputs, outputs);
    }

    void eval_gpu(const std::vector<mlx::core::array>& inputs,
                  std::vector<mlx::core::array>& outputs) override {
        eval_impl(inputs, outputs);
    }

    const char* name() const override {
        return "Case";
    }

    bool is_equivalent(const mlx::core::Primitive& other) const override {
        return false;
    }

    std::vector<mlx::core::Shape> output_shapes(
        const std::vector<mlx::core::array>& inputs) override {
        return outShapes_;
    }

private:
    void eval_impl(const std::vector<mlx::core::array>& inputs,
                   std::vector<mlx::core::array>& outputs) {
        // inputs = external values (nExt_)
        if (inputs.size() != nExt_)
            throw std::runtime_error("CasePrimitive: expected " + std::to_string(nExt_) +
                                     " inputs, got " + std::to_string(inputs.size()));

        // Order the index readback and branch eval after all in-flight GPU
        // work (see SyncGpuStream): both read this primitive's inputs, which
        // the enclosing eval pass may still be producing (jax-mps#195).
        SyncGpuStream();
        // Evaluate the index via the compiled index function.
        // This correctly re-computes the index from function arguments at
        // runtime, avoiding stale values from mx::compile's graph caching.
        auto indexResult = indexFn_(inputs);
        if (indexResult.size() != 1 || indexResult[0].size() != 1)
            throw std::runtime_error("CasePrimitive: indexFn must return a single scalar");
        mlx::core::eval(indexResult[0]);
        int branchIdx = indexResult[0].item<int>();

        // Out-of-range index selects the last branch per StableHLO spec.
        int numBranches = static_cast<int>(branches_.size());
        if (branchIdx < 0 || branchIdx >= numBranches)
            branchIdx = numBranches - 1;

        // Execute the selected compiled branch.
        auto branchResults = branches_[branchIdx](inputs);
        if (branchResults.size() < nOutputs_)
            throw std::runtime_error("CasePrimitive: branch " + std::to_string(branchIdx) +
                                     " returned " + std::to_string(branchResults.size()) +
                                     " results, expected " + std::to_string(nOutputs_));

        // Synchronous eval — single branch execution, bounded graph.
        mlx::core::eval(branchResults);
        // Surface parked stream-thread exceptions (MLX patch 10) instead of
        // copying never-written buffers into the case outputs.
        mlx::core::scheduler::rethrow_pending_exception();

        for (size_t i = 0; i < nOutputs_; ++i)
            outputs[i].copy_shared_buffer(branchResults[i]);
        for (size_t i = nOutputs_; i < outputs.size(); ++i) {
            outputs[i].set_data(mlx::core::allocator::malloc(outputs[i].nbytes()));
            std::memset(outputs[i].data<char>(), 0, outputs[i].nbytes());
        }
    }

    CompiledFn indexFn_;
    std::vector<CompiledFn> branches_;
    size_t nOutputs_;
    size_t nExt_;
    std::vector<mlx::core::Shape> outShapes_;
};

// Handler for stablehlo.while
bool HandleWhile(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                 ExecContext& ctx) {
    auto whileOp = CastOp<mlir::stablehlo::WhileOp>(op, "stablehlo.while");
    if (!whileOp)
        return false;

    if (ctx.inside_compile) {
        // --- Custom primitive approach ---
        // Create a WhileLoopPrimitive that is opaque to mx::compile but runs
        // the loop with compiled body + per-step eval when eval'd.
        ctx.produced_control_flow = true;
        //
        // This path is safe for BOTH the PJRT compile path and the eager
        // compile-probe path (below). In both cases, the primitive's inputs
        // are explicit graph edges created via make_arrays(), so mx::compile
        // correctly recomputes them on replay — they are never frozen as
        // compile-time constants. The former `allow_while_primitive` guard
        // was unnecessary given this graph-edge-based design.

        std::vector<mlx::core::array> loopVars;
        for (auto operand : op->getOperands()) {
            auto* val = RequireValue(values, operand, "stablehlo.while");
            if (!val)
                return false;
            loopVars.push_back(*val);
        }

        auto& condRegion = whileOp.getCond();
        auto& bodyRegion = whileOp.getBody();
        const size_t nLoopVars = loopVars.size();

        // Collect external values referenced by body and cond regions.
        std::vector<void*> extKeys;
        std::vector<mlx::core::array> extArrays;
        std::unordered_set<void*> seen;
        CollectExternalValues(bodyRegion, values, extKeys, extArrays, &seen);
        CollectExternalValues(condRegion, values, extKeys, extArrays, &seen);

        const size_t nExt = extKeys.size();
        auto module = ctx.module;

        // Counted-loop fast path (jax-mps#193): if the loop has a computable
        // trip count, resolve where the limit lives in the primitive's input
        // layout so eval can skip the per-iteration cond readback.
        std::optional<CountedExec> counted;
        if (auto detected = DetectCountedLoop(whileOp)) {
            CountedExec ce;
            ce.counterInputIdx = detected->counterIdx;
            ce.step = detected->step;
            ce.isUnsigned = detected->isUnsigned;
            bool resolved = true;
            if (detected->staticLimit) {
                ce.staticLimit = detected->staticLimit;
            } else if (detected->limitLoopVarIdx) {
                ce.limitInputIdx = detected->limitLoopVarIdx;
            } else {
                // Non-constant external limit: find it among the collected
                // external captures (cond references it, so it must be there).
                auto it = std::find(extKeys.begin(), extKeys.end(), ToKey(detected->limitExternal));
                if (it != extKeys.end())
                    ce.limitInputIdx = nLoopVars + static_cast<size_t>(it - extKeys.begin());
                else
                    resolved = false;
            }
            if (resolved)
                counted = ce;
        }

        // Build primitive inputs: loopVars + external values
        std::vector<mlx::core::array> primInputs = loopVars;
        primInputs.insert(primInputs.end(), extArrays.begin(), extArrays.end());

        // Build output shapes/dtypes (same as loopVars)
        std::vector<mlx::core::Shape> outShapes;
        outShapes.reserve(nLoopVars);
        std::vector<mlx::core::Dtype> outDtypes;
        outDtypes.reserve(nLoopVars);
        for (size_t i = 0; i < nLoopVars; ++i) {
            outShapes.push_back(loopVars[i].shape());
            outDtypes.push_back(loopVars[i].dtype());
        }
        const bool hasEffects =
            RegionHasHostEffects(bodyRegion) || RegionHasHostEffects(condRegion);
        if (hasEffects) {
            outShapes.push_back({});
            outDtypes.push_back(mlx::core::bool_);
        }

        // Build condFn for initial condition check
        auto condFn =
            [&condRegion, module, extKeys, nLoopVars,
             nExt](const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
            using Diff = std::vector<mlx::core::array>::difference_type;
            auto args = std::vector<mlx::core::array>(
                inputs.begin(), inputs.begin() + static_cast<Diff>(nLoopVars));
            ValueMap parentVals;
            for (size_t i = 0; i < nExt; ++i)
                parentVals.emplace(extKeys[i], inputs[nLoopVars + i]);
            std::vector<mlx::core::array> results;
            ExecContext compileCtx;
            compileCtx.module = module;
            compileCtx.inside_compile = true;

            if (!ExecuteRegion(condRegion, args, results, compileCtx, &parentVals))
                throw std::runtime_error("WhileLoopPrimitive: cond region execution failed: " +
                                         compileCtx.error_message);
            results.insert(results.end(), compileCtx.side_effects.begin(),
                           compileCtx.side_effects.end());
            return results;
        };

        // Whether the body/cond regions contain nested control-flow primitives
        // (while/case). Set during the trace, i.e. the first compiledBodyCond_
        // call; gates the async periodic flush in the counted fast path.
        auto bodyHasControlFlow = std::make_shared<std::atomic<bool>>(false);

        // Build combined body+cond function.
        // Executes body region, then cond region on the body outputs.
        // Returns [condScalar, bodyResult0, bodyResult1, ...].
        // This lets eval_impl call eval() synchronously each iteration,
        // bounding graph depth and avoiding async_eval deadlocks.
        auto bodyCondFn =
            [&bodyRegion, &condRegion, module, extKeys, nLoopVars, nExt, bodyHasControlFlow](
                const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
            using Diff = std::vector<mlx::core::array>::difference_type;
            auto args = std::vector<mlx::core::array>(
                inputs.begin(), inputs.begin() + static_cast<Diff>(nLoopVars));
            ValueMap parentVals;
            for (size_t i = 0; i < nExt; ++i)
                parentVals.emplace(extKeys[i], inputs[nLoopVars + i]);

            // Execute body
            std::vector<mlx::core::array> bodyResults;
            ExecContext bodyCtx;
            bodyCtx.module = module;
            bodyCtx.inside_compile = true;

            if (!ExecuteRegion(bodyRegion, args, bodyResults, bodyCtx, &parentVals))
                throw std::runtime_error("WhileLoopPrimitive: body region failed: " +
                                         bodyCtx.error_message);

            // Execute cond on body results (new loop vars)
            ValueMap condParentVals;
            for (size_t i = 0; i < nExt; ++i)
                condParentVals.emplace(extKeys[i], inputs[nLoopVars + i]);
            std::vector<mlx::core::array> condResults;
            ExecContext condCtx;
            condCtx.module = module;
            condCtx.inside_compile = true;

            if (!ExecuteRegion(condRegion, bodyResults, condResults, condCtx, &condParentVals))
                throw std::runtime_error("WhileLoopPrimitive: cond region failed: " +
                                         condCtx.error_message);

            if (bodyCtx.produced_control_flow || condCtx.produced_control_flow)
                bodyHasControlFlow->store(true, std::memory_order_relaxed);
            if (condResults.size() != 1 || condResults[0].size() != 1)
                throw std::runtime_error("WhileLoopPrimitive: cond must return a single scalar");

            // Return [condScalar, bodyResult0, ..., body effects..., cond effects...]
            std::vector<mlx::core::array> combined;
            combined.reserve(1 + bodyResults.size() + bodyCtx.side_effects.size() +
                             condCtx.side_effects.size());
            combined.push_back(condResults[0]);
            combined.insert(combined.end(), bodyResults.begin(), bodyResults.end());
            combined.insert(combined.end(), bodyCtx.side_effects.begin(),
                            bodyCtx.side_effects.end());
            combined.insert(combined.end(), condCtx.side_effects.begin(),
                            condCtx.side_effects.end());
            return combined;
        };

        // CPU stream for orchestration only — the compiled body dispatches GPU
        // kernels internally. eval()/async_eval() calls inside the loop would
        // deadlock on a GPU stream (see WhileLoopPrimitive class comment).
        auto cpuStream = mlx::core::default_stream(mlx::core::Device::cpu);
        auto prim = std::make_shared<WhileLoopPrimitive>(cpuStream, std::move(condFn),
                                                         std::move(bodyCondFn), nLoopVars, nExt,
                                                         counted, bodyHasControlFlow, hasEffects);

        auto outputArrays =
            mlx::core::array::make_arrays(std::move(outShapes), outDtypes, prim, primInputs);
        for (size_t i = 0; i < nLoopVars; ++i)
            values.emplace(ToKey(op->getResult(i)), std::move(outputArrays[i]));
        if (hasEffects)
            ctx.side_effects.push_back(std::move(outputArrays[nLoopVars]));
        return true;
    }

    std::vector<mlx::core::array> loopVars;
    for (auto operand : op->getOperands()) {
        auto* val = RequireValue(values, operand, "stablehlo.while");
        if (!val)
            return false;
        loopVars.push_back(*val);
    }

    auto& condRegion = whileOp.getCond();
    auto& bodyRegion = whileOp.getBody();

    using CompiledFn =
        std::function<std::vector<mlx::core::array>(const std::vector<mlx::core::array>&)>;
    CompiledFn compiledCond;
    CompiledFn compiledBody;
    bool useCompiled = false;
    try {
        compiledCond = mlx::core::compile(
            [&condRegion, &ctx, &values](
                const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
                auto args = inputs;
                std::vector<mlx::core::array> results;
                ExecContext compileCtx;
                compileCtx.module = ctx.module;
                compileCtx.inside_compile = true;
                if (!ExecuteRegion(condRegion, args, results, compileCtx, &values)) {
                    return {};
                }
                return results;
            });

        compiledBody = mlx::core::compile(
            [&bodyRegion, &ctx, &values](
                const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
                auto args = inputs;
                std::vector<mlx::core::array> results;
                ExecContext compileCtx;
                compileCtx.module = ctx.module;
                compileCtx.inside_compile = true;
                if (!ExecuteRegion(bodyRegion, args, results, compileCtx, &values)) {
                    return {};
                }
                return results;
            });

        // Probe: run compiled cond+body once to verify they work
        auto testCond = compiledCond(loopVars);
        if (testCond.size() == 1) {
            auto testBody = compiledBody(loopVars);
            if (testBody.size() == loopVars.size()) {
                std::vector<mlx::core::array> toEval;
                toEval.insert(toEval.end(), testCond.begin(), testCond.end());
                toEval.insert(toEval.end(), testBody.begin(), testBody.end());
                mlx::core::eval(toEval);
                useCompiled = true;
            }
        }
    } catch (...) {
        useCompiled = false;
    }

    while (true) {
        std::vector<mlx::core::array> condResults;
        if (useCompiled) {
            condResults = compiledCond(loopVars);
        } else {
            if (!ExecuteRegion(condRegion, loopVars, condResults, ctx, &values)) {
                MPS_LOG_ERROR("stablehlo.while: failed to execute cond region\n");
                return false;
            }
        }

        if (condResults.size() != 1) {
            MPS_LOG_ERROR("stablehlo.while: cond region should return 1 value, got %zu\n",
                          condResults.size());
            return false;
        }

        // Only eval the condition — keep loop vars lazy until needed.
        mlx::core::eval(condResults[0]);
        auto condVal = condResults[0];

        if (condVal.size() != 1) {
            MPS_LOG_ERROR("stablehlo.while: condition must be a scalar, got size %zu\n",
                          condVal.size());
            return false;
        }

        if (!condVal.item<bool>()) {
            break;
        }

        std::vector<mlx::core::array> bodyResults;
        if (useCompiled) {
            bodyResults = compiledBody(loopVars);
        } else {
            if (!ExecuteRegion(bodyRegion, loopVars, bodyResults, ctx, &values)) {
                MPS_LOG_ERROR("stablehlo.while: failed to execute body region\n");
                return false;
            }
        }

        if (bodyResults.size() != loopVars.size()) {
            MPS_LOG_ERROR("stablehlo.while: body returned %zu values, expected %zu\n",
                          bodyResults.size(), loopVars.size());
            return false;
        }

        loopVars = std::move(bodyResults);
    }

    for (size_t i = 0; i < loopVars.size(); ++i) {
        values.emplace(ToKey(op->getResult(i)), std::move(loopVars[i]));
    }

    return true;
}

// Handler for stablehlo.case (implements lax.cond and lax.switch)
bool HandleCase(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                ExecContext& ctx) {
    auto caseOp = CastOp<mlir::stablehlo::CaseOp>(op, "stablehlo.case");
    if (!caseOp)
        return false;

    auto* index = RequireValue(values, caseOp.getIndex(), "stablehlo.case");
    if (!index)
        return false;

    if (ctx.inside_compile) {
        // --- Custom primitive approach ---
        // Create a CasePrimitive that is opaque to mx::compile but executes
        // the selected branch with compiled body + eval when eval'd.
        ctx.produced_control_flow = true;

        auto branches = caseOp.getBranches();
        const size_t numBranches = branches.size();
        const size_t nOutputs = op->getNumResults();

        // Collect external values referenced by ALL branch regions.
        std::vector<void*> extKeys;
        std::vector<mlx::core::array> extArrays;
        std::unordered_set<void*> seen;
        for (size_t b = 0; b < numBranches; ++b)
            CollectExternalValues(branches[b], values, extKeys, extArrays, &seen);

        // NOTE: We do NOT add all parent block arguments here. Only the
        // external values referenced by branches (collected above) and the
        // root argument for index reconstruction (added below during index
        // decomposition) are needed. Adding all block args would scale the
        // CasePrimitive's input signature with the enclosing function's
        // arity, increasing compile time and per-eval marshalling cost.

        // Determine how to compute the index from the external values.
        // The case op's index operand is typically an intermediate (e.g.,
        // clamp(const, argN, const)). Since mx::compile freezes intermediates,
        // we build an indexFn that re-computes the index from raw function
        // arguments at runtime.
        //
        // Strategy: inspect the immediate defining op of caseOp.getIndex()
        // to identify the function argument it depends on. For the common
        // pattern:
        //   %c = constant 0
        //   %c_0 = constant N-1
        //   %idx = clamp(%c, %argK, %c_0)
        // we reconstruct the clamp inside indexFn. For convert(bool→int32)
        // (lax.cond), we look through one level. For other patterns, we
        // fall back to including the index directly (which only works for
        // trivial cases where the index IS a function argument).

        // Find the position of each function argument in extArrays for lookup.
        std::unordered_map<void*, size_t> keyToPos;
        for (size_t i = 0; i < extKeys.size(); ++i)
            keyToPos[extKeys[i]] = i;

        // Try to decompose the index operand.
        mlir::Value indexVal = caseOp.getIndex();
        auto* indexDefOp = indexVal.getDefiningOp();

        size_t indexArgPos = SIZE_MAX;
        bool needsClamp = false;
        int clampMin = 0;
        int clampMax = static_cast<int>(numBranches) - 1;

        if (indexDefOp) {
            // Check if the index is defined by a clamp op.
            if (auto clampOp = mlir::dyn_cast<mlir::stablehlo::ClampOp>(indexDefOp)) {
                // clamp(min_const, operand, max_const)
                // The clamp operand may itself be a convert (e.g., i64→i32
                // when the selector dtype differs). Look through one level
                // of ConvertOp to find the root block argument, so we don't
                // freeze an intermediate under mx::compile.
                mlir::Value operand = clampOp.getOperand();
                if (auto innerConvert = operand.getDefiningOp<mlir::stablehlo::ConvertOp>()) {
                    operand = innerConvert.getOperand();
                }
                void* operandKey = ToKey(operand);
                auto posIt = keyToPos.find(operandKey);
                if (posIt != keyToPos.end()) {
                    indexArgPos = posIt->second;
                } else {
                    // The operand isn't in extKeys yet (e.g., nested case where
                    // %arg1 is only used by the clamp, not the branches). Add it.
                    auto valIt = values.find(operandKey);
                    if (valIt != values.end()) {
                        indexArgPos = extKeys.size();
                        extKeys.push_back(operandKey);
                        extArrays.push_back(valIt->second);
                        keyToPos[operandKey] = indexArgPos;
                    }
                }
                if (indexArgPos != SIZE_MAX) {
                    // Extract clamp bounds from the MLIR constants.
                    // Only enable clamp reconstruction when both bounds are
                    // proven constant — otherwise reject with an error to
                    // avoid silently using default bounds.
                    bool parsedMin = false;
                    bool parsedMax = false;
                    if (auto minOp =
                            clampOp.getMin().getDefiningOp<mlir::stablehlo::ConstantOp>()) {
                        if (auto attr =
                                mlir::dyn_cast<mlir::DenseIntElementsAttr>(minOp.getValue())) {
                            clampMin = static_cast<int>((*attr.begin()).getSExtValue());
                            parsedMin = true;
                        }
                    }
                    if (auto maxOp =
                            clampOp.getMax().getDefiningOp<mlir::stablehlo::ConstantOp>()) {
                        if (auto attr =
                                mlir::dyn_cast<mlir::DenseIntElementsAttr>(maxOp.getValue())) {
                            clampMax = static_cast<int>((*attr.begin()).getSExtValue());
                            parsedMax = true;
                        }
                    }
                    needsClamp = parsedMin && parsedMax;
                    if (!needsClamp) {
                        // Clamp operand resolved but bounds are not
                        // proven-constant — cannot safely drop the clamp.
                        MPS_LOG_ERROR(
                            "HandleCase: clamp bounds are not constant, "
                            "cannot safely compile\n");
                        return false;
                    }
                }
            }

            // Check if the index is a convert (e.g., bool -> int32 for lax.cond).
            if (indexArgPos == SIZE_MAX) {
                if (auto convertOp = mlir::dyn_cast<mlir::stablehlo::ConvertOp>(indexDefOp)) {
                    void* srcKey = ToKey(convertOp.getOperand());
                    auto posIt = keyToPos.find(srcKey);
                    if (posIt != keyToPos.end()) {
                        indexArgPos = posIt->second;
                    } else {
                        auto valIt = values.find(srcKey);
                        if (valIt != values.end()) {
                            indexArgPos = extKeys.size();
                            extKeys.push_back(srcKey);
                            extArrays.push_back(valIt->second);
                            keyToPos[srcKey] = indexArgPos;
                        }
                    }
                }
            }
        }

        // If the index IS already a function argument or external value:
        if (indexArgPos == SIZE_MAX) {
            void* idxKey = ToKey(indexVal);
            auto posIt = keyToPos.find(idxKey);
            if (posIt != keyToPos.end()) {
                indexArgPos = posIt->second;
            }
        }

        // Fallback: pass the index through directly as a primitive input. Like
        // every other CasePrimitive input, it is wired via make_arrays() as an
        // explicit graph edge, so mx::compile recomputes it on each replay — it
        // is never frozen as a compile-time constant. This is the same property
        // that makes WhileLoopPrimitive's external captures safe (see the note
        // in HandleWhile), and it holds for an arbitrary index-defining op,
        // including a nested stablehlo.case whose result selects this case (the
        // pattern NUTS generates). The clamp/convert decomposition above is a
        // cheaper optimization that taps the raw function argument; this
        // fallback covers every other shape. CasePrimitive::eval_impl
        // bounds-checks the index (out-of-range selects the last branch per the
        // StableHLO spec), so passing it unclamped here is safe.
        if (indexArgPos == SIZE_MAX) {
            indexArgPos = extArrays.size();
            extKeys.push_back(ToKey(indexVal));
            extArrays.push_back(*index);
        }

        const size_t nExt = extKeys.size();
        auto module = ctx.module;

        // Build compiled index function that re-computes the index at runtime.
        CasePrimitive::CompiledFn compiledIndexFn;
        if (needsClamp) {
            compiledIndexFn = mlx::core::compile(
                [indexArgPos, clampMin, clampMax](
                    const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
                    auto val = mlx::core::astype(inputs[indexArgPos], mlx::core::int32);
                    auto result = mlx::core::clip(val, mlx::core::array(clampMin, mlx::core::int32),
                                                  mlx::core::array(clampMax, mlx::core::int32));
                    return {result};
                });
        } else {
            compiledIndexFn = mlx::core::compile(
                [indexArgPos](
                    const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
                    return {mlx::core::astype(inputs[indexArgPos], mlx::core::int32)};
                });
        }

        // Build one compiled function per branch.
        // NOTE: We capture a raw pointer to the CaseOp (owned by the MLIR module,
        // kept alive via ctx.module). We must NOT capture `branches` by reference —
        // it's a local MutableArrayRef that goes out of scope after HandleCase returns.
        auto* caseOpPtr = caseOp.getOperation();
        std::vector<CasePrimitive::CompiledFn> compiledBranches;
        compiledBranches.reserve(numBranches);
        for (size_t b = 0; b < numBranches; ++b) {
            auto branchFn =
                [caseOpPtr, b, module, extKeys, nExt](
                    const std::vector<mlx::core::array>& inputs) -> std::vector<mlx::core::array> {
                // inputs = external values
                ValueMap parentVals;
                for (size_t i = 0; i < nExt; ++i)
                    parentVals.emplace(extKeys[i], inputs[i]);
                // Access the branch region through the op (owned by the module).
                auto regionCaseOp = mlir::cast<mlir::stablehlo::CaseOp>(caseOpPtr);
                auto& branchRegion = regionCaseOp.getBranches()[b];
                // Branch regions have no block arguments.
                std::vector<mlx::core::array> branchArgs;
                std::vector<mlx::core::array> results;
                ExecContext branchCtx;
                branchCtx.module = module;
                branchCtx.inside_compile = true;

                if (!ExecuteRegion(branchRegion, branchArgs, results, branchCtx, &parentVals))
                    throw std::runtime_error("CasePrimitive: branch " + std::to_string(b) +
                                             " execution failed");
                // Effect markers follow the branch results (see CasePrimitive).
                results.insert(results.end(), branchCtx.side_effects.begin(),
                               branchCtx.side_effects.end());
                return results;
            };
            compiledBranches.push_back(mlx::core::compile(std::move(branchFn)));
        }

        // Derive output shapes/dtypes from MLIR result types.
        std::vector<mlx::core::Shape> outShapes;
        outShapes.reserve(nOutputs);
        std::vector<mlx::core::Dtype> outDtypes;
        outDtypes.reserve(nOutputs);
        for (size_t i = 0; i < nOutputs; ++i) {
            auto resultType = mlir::dyn_cast<mlir::RankedTensorType>(op->getResult(i).getType());
            if (resultType) {
                outShapes.push_back(GetShape(resultType));
                outDtypes.push_back(MlirTypeToMlxDtype(resultType.getElementType()));
            } else {
                MPS_LOG_ERROR("HandleCase: result %zu is not a RankedTensorType\n", i);
                return false;
            }
        }
        bool hasEffects = false;
        for (size_t b = 0; b < numBranches; ++b)
            hasEffects = hasEffects || RegionHasHostEffects(branches[b]);
        if (hasEffects) {
            outShapes.push_back({});
            outDtypes.push_back(mlx::core::bool_);
        }

        // Build primitive inputs: external values only (index is in extArrays).
        std::vector<mlx::core::array> primInputs = extArrays;

        // CPU stream for orchestration — same rationale as WhileLoopPrimitive.
        auto cpuStream = mlx::core::default_stream(mlx::core::Device::cpu);
        // Copy outShapes for the primitive; move original into make_arrays.
        auto primShapes = outShapes;
        auto prim = std::make_shared<CasePrimitive>(cpuStream, std::move(compiledIndexFn),
                                                    std::move(compiledBranches), nOutputs, nExt,
                                                    std::move(primShapes));

        auto outputArrays =
            mlx::core::array::make_arrays(std::move(outShapes), outDtypes, prim, primInputs);
        for (size_t i = 0; i < nOutputs; ++i)
            values.emplace(ToKey(op->getResult(i)), std::move(outputArrays[i]));
        if (hasEffects)
            ctx.side_effects.push_back(std::move(outputArrays[nOutputs]));
        return true;
    }

    // --- Eager (non-compile) path ---
    mlx::core::eval(*index);
    int branchIdx = index->item<int>();

    int numBranches = static_cast<int>(caseOp.getBranches().size());
    if (branchIdx < 0 || branchIdx >= numBranches) {
        branchIdx = numBranches - 1;
    }

    auto& branch = caseOp.getBranches()[branchIdx];
    std::vector<mlx::core::array> branchArgs;
    std::vector<mlx::core::array> branchResults;
    if (!ExecuteRegion(branch, branchArgs, branchResults, ctx, &values)) {
        MPS_LOG_ERROR("stablehlo.case: failed to execute branch %d\n", branchIdx);
        return false;
    }

    for (size_t i = 0; i < branchResults.size(); ++i) {
        values.emplace(ToKey(op->getResult(i)), std::move(branchResults[i]));
    }

    return true;
}

// Handler for func.call
bool HandleCall(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                ExecContext& ctx) {
    auto callOp = CastOp<mlir::func::CallOp>(op, "func.call");
    if (!callOp)
        return false;

    auto calleeName = callOp.getCallee();
    auto calleeFunc = ctx.module.lookupSymbol<mlir::func::FuncOp>(calleeName);
    if (!calleeFunc) {
        MPS_LOG_ERROR("func.call: callee function '%s' not found\n", calleeName.str().c_str());
        return false;
    }

    std::vector<mlx::core::array> callInputs;
    for (auto operand : op->getOperands()) {
        auto* val = RequireValue(values, operand, "func.call");
        if (!val)
            return false;
        callInputs.push_back(*val);
    }

    std::vector<mlx::core::array> callOutputs;
    if (!ExecuteFunction(calleeFunc, callInputs, callOutputs, ctx)) {
        MPS_LOG_ERROR("func.call: failed to execute callee '%s'\n", calleeName.str().c_str());
        return false;
    }

    if (callOutputs.size() != op->getNumResults()) {
        MPS_LOG_ERROR("func.call: result count mismatch\n");
        return false;
    }

    for (size_t i = 0; i < callOutputs.size(); ++i) {
        values.emplace(ToKey(op->getResult(i)), std::move(callOutputs[i]));
    }

    return true;
}

// Evaluate JAX's threefry2x32 PRNG primitive as a single fused Metal kernel.
//
// threefry2x32-20 is pure integer arithmetic (add / rotate / xor) with the
// standard Threefish rotation schedule {13,15,26,6}/{17,29,16,24}, parity
// constant 0x1BD11BDA, and a key injection after every four rounds. This is
// byte-for-byte the same schedule JAX's CPU lowering runs (see
// jax/_src/prng.py `_threefry2x32_lowering`), so the outputs are bit-exact with
// the CPU backend by construction — which the test harness relies on (it
// compares MPS vs CPU integer outputs exactly). Do NOT swap in MLX's own RNG:
// it uses a modified splittable variant that would not reproduce user seeds.
//
// Without this kernel, jax.random inlines threefry as ~140 tiny elementwise
// StableHLO ops per key op; inside a compiled loop body every surviving MLX
// node costs ~1.5us of dispatch, so a single random.split in a fori_loop body
// ran ~30x slower than the arithmetic-only body (jax-mps#196). One kernel call
// removes that per-node cost.
//
// Inputs (all uint32, broadcast to the output shape here): key0, key1, count0,
// count1. Outputs: out0, out1 (uint32, output shape).
std::vector<mlx::core::array> Threefry2x32Kernel(const mlx::core::array& k0,
                                                 const mlx::core::array& k1,
                                                 const mlx::core::array& x0,
                                                 const mlx::core::array& x1,
                                                 const mlx::core::Shape& outShape, int64_t total) {
    static const char* kHeader = R"(
inline uint32_t tfry_rotl(uint32_t x, uint32_t n) {
    return (x << n) | (x >> (32u - n));
}
)";
    // Body of the [[kernel]]; MLX declares key0/key1/count0/count1 as inputs,
    // out0/out1 as outputs, and provides thread_position_in_grid. Inputs are
    // row-contiguous (ensure_row_contiguous), so a flat 1-D index suffices.
    static const char* kSource = R"(
    uint idx = thread_position_in_grid.x;
    uint32_t ks0 = key0[idx];
    uint32_t ks1 = key1[idx];
    uint32_t ks2 = ks0 ^ ks1 ^ 0x1BD11BDAu;
    uint32_t X0 = count0[idx] + ks0;
    uint32_t X1 = count1[idx] + ks1;
    // block 0 — rotations {13,15,26,6}, inject (ks1, ks2 + 1)
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 13u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 15u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 26u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 6u);
    X0 += ks1; X1 += ks2 + 1u;
    // block 1 — rotations {17,29,16,24}, inject (ks2, ks0 + 2)
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 17u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 29u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 16u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 24u);
    X0 += ks2; X1 += ks0 + 2u;
    // block 2 — rotations {13,15,26,6}, inject (ks0, ks1 + 3)
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 13u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 15u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 26u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 6u);
    X0 += ks0; X1 += ks1 + 3u;
    // block 3 — rotations {17,29,16,24}, inject (ks1, ks2 + 4)
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 17u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 29u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 16u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 24u);
    X0 += ks1; X1 += ks2 + 4u;
    // block 4 — rotations {13,15,26,6}, inject (ks2, ks0 + 5)
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 13u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 15u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 26u);
    X0 += X1; X1 = X0 ^ tfry_rotl(X1, 6u);
    X0 += ks2; X1 += ks0 + 5u;
    out0[idx] = X0;
    out1[idx] = X1;
)";
    // Building the CustomKernelFunction only assembles a std::function; the
    // Metal library is compiled lazily and cached by MLX keyed on the kernel
    // name, so a function-local static is safe and avoids re-wrapping per call.
    static const mlx::core::fast::CustomKernelFunction kernel = mlx::core::fast::metal_kernel(
        "threefry2x32", /*input_names=*/{"key0", "key1", "count0", "count1"},
        /*output_names=*/{"out0", "out1"}, kSource, kHeader,
        /*ensure_row_contiguous=*/true);

    // Flatten to 1-D before dispatch: MLX declares rank-0 kernel inputs as
    // scalar references (not pointers), so `count0[idx]` would not compile for
    // a scalar output shape. A single flat axis also matches the 1-D grid.
    mlx::core::Shape flat{static_cast<int32_t>(total)};
    int threads = static_cast<int>(std::min<int64_t>(total, 256));
    auto outs = kernel({mlx::core::reshape(k0, flat), mlx::core::reshape(k1, flat),
                        mlx::core::reshape(x0, flat), mlx::core::reshape(x1, flat)},
                       /*output_shapes=*/{flat, flat},
                       /*output_dtypes=*/{mlx::core::uint32, mlx::core::uint32},
                       /*grid=*/{static_cast<int>(total), 1, 1},
                       /*threadgroup=*/{threads, 1, 1}, /*template_args=*/{},
                       /*init_value=*/std::nullopt, /*verbose=*/false, /*s=*/{});
    outs[0] = mlx::core::reshape(outs[0], outShape);
    outs[1] = mlx::core::reshape(outs[1], outShape);
    return outs;
}

// Handler for stablehlo.custom_call
bool HandleCustomCall(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                      ExecContext& ctx) {
    auto customCallOp = CastOp<mlir::stablehlo::CustomCallOp>(op, "stablehlo.custom_call");
    if (!customCallOp)
        return false;

    auto callTargetName = customCallOp.getCallTargetName().str();

    if (callTargetName == kHostCallbackTarget)
        return HandleHostCallback(op, values, ctx);

    // Handle Sharding annotation and SPMD shape ops - just pass input through
    if (callTargetName == "Sharding" || callTargetName == "SPMDFullToShardShape" ||
        callTargetName == "SPMDShardToFullShape") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("stablehlo.custom_call %s: expected 1 input and 1 output\n",
                          callTargetName.c_str());
            return false;
        }
        auto* input = RequireValue(values, op->getOperand(0), callTargetName.c_str());
        if (!input)
            return false;
        values.emplace(ToKey(op->getResult(0)), *input);
        return true;
    }

    // Handle unary mhlo.* custom calls via the shared unary op table.
    // Use string_view throughout so the lookup doesn't allocate.
    static constexpr std::string_view kMhloPrefix = "mhlo.";
    std::string_view callName{callTargetName};
    if (callName.substr(0, kMhloPrefix.size()) == kMhloPrefix) {
        const auto& unaryOps = UnaryMlxOps();
        auto unaryIt = unaryOps.find(callName.substr(kMhloPrefix.size()));
        if (unaryIt != unaryOps.end()) {
            if (op->getNumOperands() != 1 || op->getNumResults() != 1) {
                MPS_LOG_ERROR("stablehlo.custom_call %s: expected 1 input and 1 output\n",
                              callTargetName.c_str());
                return false;
            }
            auto* input = RequireValue(values, op->getOperand(0), callTargetName.c_str());
            if (!input)
                return false;
            values.emplace(ToKey(op->getResult(0)), unaryIt->second(*input, {}));
            return true;
        }
    }

    // Handle mhlo.topk
    if (callTargetName == "mhlo.topk") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 2) {
            MPS_LOG_ERROR("stablehlo.custom_call mhlo.topk: expected 1 input and 2 outputs\n");
            return false;
        }
        auto* input = RequireValue(values, op->getOperand(0), "mhlo.topk");
        if (!input)
            return false;

        auto resultType = mlir::cast<mlir::RankedTensorType>(op->getResult(0).getType());
        int k = static_cast<int>(resultType.getShape().back());
        auto [topValues, indices] = TopKImpl(*input, k);
        values.emplace(ToKey(op->getResult(0)), std::move(topValues));
        values.emplace(ToKey(op->getResult(1)), std::move(indices));
        return true;
    }

    // Handle mps.sdpa — fused scaled dot-product attention via mlx::core::fast.
    // Inputs: queries (B, N, T, H), keys (B, N_kv, S, H), values (B, N_kv, S, H),
    //         mask (boolean gating mask or float additive bias; see MaskToAdditive,
    //         broadcastable to (B, N, T, S))
    // backend_config: {"scale": <float>}
    if (callTargetName == "mps.sdpa") {
        if (op->getNumOperands() != 4 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.sdpa: expected 4 inputs and 1 output\n");
            return false;
        }
        auto* queries = RequireValue(values, op->getOperand(0), "mps.sdpa");
        auto* keys = RequireValue(values, op->getOperand(1), "mps.sdpa");
        auto* vals = RequireValue(values, op->getOperand(2), "mps.sdpa");
        auto* mask = RequireValue(values, op->getOperand(3), "mps.sdpa");
        if (!queries || !keys || !vals || !mask)
            return false;
        if (!IsValidSdpaMaskDtype(*mask)) {
            MPS_LOG_ERROR("mps.sdpa: mask must be boolean or floating\n");
            return false;
        }

        float scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("scale"))
            scale = static_cast<float>(*v);

        auto additive_mask = MaskToAdditive(*mask, queries->dtype());
        auto result = mlx::core::fast::scaled_dot_product_attention(*queries, *keys, *vals, scale,
                                                                    "", additive_mask);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.sdpa_causal — fused SDPA with causal masking.
    if (callTargetName == "mps.sdpa_causal") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.sdpa_causal: expected 3 inputs and 1 output\n");
            return false;
        }
        auto* queries = RequireValue(values, op->getOperand(0), "mps.sdpa_causal");
        auto* keys = RequireValue(values, op->getOperand(1), "mps.sdpa_causal");
        auto* vals = RequireValue(values, op->getOperand(2), "mps.sdpa_causal");
        if (!queries || !keys || !vals)
            return false;

        float scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("scale"))
            scale = static_cast<float>(*v);

        auto result =
            mlx::core::fast::scaled_dot_product_attention(*queries, *keys, *vals, scale, "causal");
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.quantize — affine group-wise weight quantization.
    // Input: w; outputs: packed (uint32), scales, biases.
    // backend_config: {"group_size": <int>, "bits": <int>}
    if (callTargetName == "mps.quantize") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 3) {
            MPS_LOG_ERROR("mps.quantize: expected 1 input and 3 outputs\n");
            return false;
        }
        auto* w = RequireValue(values, op->getOperand(0), "mps.quantize");
        if (!w)
            return false;
        auto bc = ParseBackendConfig(customCallOp);
        int group_size = 64;
        int bits = 4;
        if (auto v = bc.getNumber("group_size"))
            group_size = static_cast<int>(*v);
        if (auto v = bc.getNumber("bits"))
            bits = static_cast<int>(*v);
        auto outs = mlx::core::quantize(*w, group_size, bits, "affine");
        values.emplace(ToKey(op->getResult(0)), std::move(outs[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(outs[1]));
        values.emplace(ToKey(op->getResult(2)), std::move(outs[2]));
        return true;
    }

    // Handle mps.dequantize — reconstruct a float matrix from quantize().
    // Inputs: packed (uint32), scales, biases.
    // backend_config: {"group_size": <int>, "bits": <int>}
    if (callTargetName == "mps.dequantize") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.dequantize: expected 3 inputs and 1 output\n");
            return false;
        }
        auto* packed = RequireValue(values, op->getOperand(0), "mps.dequantize");
        auto* scales = RequireValue(values, op->getOperand(1), "mps.dequantize");
        auto* biases = RequireValue(values, op->getOperand(2), "mps.dequantize");
        if (!packed || !scales || !biases)
            return false;
        auto bc = ParseBackendConfig(customCallOp);
        int group_size = 64;
        int bits = 4;
        if (auto v = bc.getNumber("group_size"))
            group_size = static_cast<int>(*v);
        if (auto v = bc.getNumber("bits"))
            bits = static_cast<int>(*v);
        auto out = mlx::core::dequantize(*packed, *scales, *biases, group_size, bits, "affine");
        values.emplace(ToKey(op->getResult(0)), std::move(out));
        return true;
    }

    // Handle mps.quantized_matmul — x @ (quantized w) via MLX's fused kernel.
    // Inputs: x, packed (uint32), scales, biases.
    // backend_config: {"transpose": <0|1>, "group_size": <int>, "bits": <int>}
    if (callTargetName == "mps.quantized_matmul") {
        if (op->getNumOperands() != 4 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.quantized_matmul: expected 4 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.quantized_matmul");
        auto* packed = RequireValue(values, op->getOperand(1), "mps.quantized_matmul");
        auto* scales = RequireValue(values, op->getOperand(2), "mps.quantized_matmul");
        auto* biases = RequireValue(values, op->getOperand(3), "mps.quantized_matmul");
        if (!x || !packed || !scales || !biases)
            return false;
        auto bc = ParseBackendConfig(customCallOp);
        bool transpose = true;
        int group_size = 64;
        int bits = 4;
        if (auto v = bc.getNumber("transpose"))
            transpose = (*v != 0);
        if (auto v = bc.getNumber("group_size"))
            group_size = static_cast<int>(*v);
        if (auto v = bc.getNumber("bits"))
            bits = static_cast<int>(*v);
        auto out = mlx::core::quantized_matmul(*x, *packed, *scales, *biases, transpose, group_size,
                                               bits, "affine");
        values.emplace(ToKey(op->getResult(0)), std::move(out));
        return true;
    }

    // Handle mps.threefry2x32 — JAX's threefry2x32 PRNG primitive as one fused
    // Metal kernel (see Threefry2x32Kernel above and jax-mps#196). Inputs
    // key0, key1, count0, count1 are uint32 and broadcastable to the (shared)
    // output shape; outputs out0, out1 have that shape.
    if (callTargetName == "mps.threefry2x32") {
        if (op->getNumOperands() != 4 || op->getNumResults() != 2) {
            MPS_LOG_ERROR("mps.threefry2x32: expected 4 inputs and 2 outputs\n");
            return false;
        }
        auto* k0 = RequireValue(values, op->getOperand(0), "mps.threefry2x32");
        auto* k1 = RequireValue(values, op->getOperand(1), "mps.threefry2x32");
        auto* x0 = RequireValue(values, op->getOperand(2), "mps.threefry2x32");
        auto* x1 = RequireValue(values, op->getOperand(3), "mps.threefry2x32");
        if (!k0 || !k1 || !x0 || !x1)
            return false;

        auto shapeOpt = GetResultShape(op, "mps.threefry2x32");
        if (!shapeOpt)
            return false;
        const mlx::core::Shape& outShape = *shapeOpt;

        // Product of the output dims. The flat length and 1-D grid extent below
        // are int32, so reject anything larger than 2^31-1 (a >2^31-element RNG
        // draw is ~8+ GiB and not addressable by the Metal dispatch anyway).
        // Check inside the loop: each MLX dim is int32, so bailing the instant
        // the running product exceeds int32 max keeps `total` itself from
        // overflowing int64 and slipping past the bound (int32max*int32max fits
        // int64). A zero dim yields total 0 (handled below), never a spurious
        // reject, since a single dim can never exceed int32 max on its own.
        int64_t total = 1;
        for (auto d : outShape) {
            total *= d;
            if (total > std::numeric_limits<int32_t>::max()) {
                MPS_LOG_ERROR(
                    "mps.threefry2x32: output element count exceeds the "
                    "maximum addressable by the Metal dispatch (2^31-1)\n");
                return false;
            }
        }
        // Zero-sized output: nothing to hash, and a zero-thread dispatch is
        // meaningless. Emit correctly-shaped empty arrays.
        if (total == 0) {
            values.emplace(ToKey(op->getResult(0)), mlx::core::zeros(outShape, mlx::core::uint32));
            values.emplace(ToKey(op->getResult(1)), mlx::core::zeros(outShape, mlx::core::uint32));
            return true;
        }

        // Broadcast every operand to the output shape so the kernel is a flat
        // elementwise map (keys are typically scalars, counts the full shape).
        auto outs = Threefry2x32Kernel(mlx::core::broadcast_to(*k0, outShape),
                                       mlx::core::broadcast_to(*k1, outShape),
                                       mlx::core::broadcast_to(*x0, outShape),
                                       mlx::core::broadcast_to(*x1, outShape), outShape, total);
        values.emplace(ToKey(op->getResult(0)), std::move(outs[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(outs[1]));
        return true;
    }

    // Handle mps.rms_norm — fused RMS normalization via mlx::core::fast.
    // Inputs: x, weight
    // backend_config: {"eps": <float>}
    if (callTargetName == "mps.rms_norm") {
        if (op->getNumOperands() != 2 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.rms_norm: expected 2 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.rms_norm");
        auto* weight = RequireValue(values, op->getOperand(1), "mps.rms_norm");
        if (!x || !weight)
            return false;

        float eps = 1e-6F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("eps"))
            eps = static_cast<float>(*v);

        // MLX rms_norm applies: x / sqrt(mean(x^2) + eps) * weight
        // Gemma's RMSNorm uses (1 + weight), so we pass (1 + weight) here.
        // The Python side is responsible for passing the correct weight.
        auto result = mlx::core::fast::rms_norm(*x, *weight, eps);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.addmm — fused matmul + bias emitted by the fuse_bias_add
    // StableHLO rewrite pattern. Inputs: lhs, rhs, bias (1D, size = trailing
    // output dim). Computes bias + lhs @ rhs with the standard matmul layout
    // (contracting dims = last of lhs / first of rhs after any leading batch
    // dims).
    if (callTargetName == "mps.addmm") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.addmm: expected 3 inputs and 1 output\n");
            return false;
        }
        auto* lhs = RequireValue(values, op->getOperand(0), "mps.addmm");
        auto* rhs = RequireValue(values, op->getOperand(1), "mps.addmm");
        auto* bias = RequireValue(values, op->getOperand(2), "mps.addmm");
        if (!lhs || !rhs || !bias)
            return false;

        auto result = mlx::core::addmm(*bias, *lhs, *rhs);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.softmax — fused numerically-stable softmax emitted by
    // fuse_softmax. One input, one output; axis comes from backend_config.
    if (callTargetName == "mps.softmax") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.softmax: expected 1 input and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.softmax");
        if (!x)
            return false;
        const int ndim = static_cast<int>(x->ndim());
        int axis = ndim - 1;  // default = trailing
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("axis"))
            axis = static_cast<int>(*v);
        if (axis < 0)
            axis += ndim;
        if (axis < 0 || axis >= ndim) {
            MPS_LOG_ERROR("mps.softmax: axis %d out of range for rank %d\n", axis, ndim);
            return false;
        }
        auto result = mlx::core::softmax(*x, std::vector<int>{axis}, /*precise=*/false);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.layer_norm — fused layer normalization via mlx::core::fast.
    // Inputs: x, weight, bias
    // backend_config: {"eps": <float>}
    if (callTargetName == "mps.layer_norm") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.layer_norm: expected 3 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.layer_norm");
        auto* weight = RequireValue(values, op->getOperand(1), "mps.layer_norm");
        auto* bias = RequireValue(values, op->getOperand(2), "mps.layer_norm");
        if (!x || !weight || !bias)
            return false;

        float eps = 1e-5F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("eps"))
            eps = static_cast<float>(*v);

        auto result = mlx::core::fast::layer_norm(*x, *weight, *bias, eps);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.layer_norm_bwd — backward for layer norm via mlx::core::vjp.
    // Inputs: x, weight, bias, grad_out; Outputs: dx, dweight, dbias
    if (callTargetName == "mps.layer_norm_bwd") {
        if (op->getNumOperands() != 4 || op->getNumResults() != 3) {
            MPS_LOG_ERROR("mps.layer_norm_bwd: expected 4 inputs and 3 outputs\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.layer_norm_bwd");
        auto* w = RequireValue(values, op->getOperand(1), "mps.layer_norm_bwd");
        auto* b = RequireValue(values, op->getOperand(2), "mps.layer_norm_bwd");
        auto* g = RequireValue(values, op->getOperand(3), "mps.layer_norm_bwd");
        if (!x || !w || !b || !g)
            return false;

        float eps = 1e-5F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("eps"))
            eps = static_cast<float>(*v);

        auto vjp_fn = [eps](const std::vector<mlx::core::array>& primals) {
            return std::vector<mlx::core::array>{
                mlx::core::fast::layer_norm(primals[0], primals[1], primals[2], eps)};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*x, *w, *b}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(grads[1]));
        values.emplace(ToKey(op->getResult(2)), std::move(grads[2]));
        return true;
    }

    // Handle mps.rope — fused rotary position embeddings via mlx::core::fast.
    // Inputs: x (..., T, D), offset (int32 scalar)
    // backend_config: {"dims": <int>, "traditional": <bool>, "base": <float>,
    //                  "rope_scale": <float>}
    if (callTargetName == "mps.rope") {
        if (op->getNumOperands() != 2 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.rope: expected 2 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.rope");
        auto* offsetArr = RequireValue(values, op->getOperand(1), "mps.rope");
        if (!x || !offsetArr)
            return false;

        int dims = 0;
        bool traditional = false;
        float base = 10000.0F;
        float rope_scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getInteger("dims"))
            dims = static_cast<int>(*v);
        if (auto v = bc.getNumber("base"))
            base = static_cast<float>(*v);
        if (auto v = bc.getNumber("rope_scale"))
            rope_scale = static_cast<float>(*v);
        if (auto v = bc.getBoolean("traditional"))
            traditional = *v;

        auto result = mlx::core::fast::rope(*x, dims, traditional, base, rope_scale, *offsetArr);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.gelu — approximate GELU: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    // MLX's compiler will fuse these element-wise ops into a single Metal kernel.
    if (callTargetName == "mps.gelu") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.gelu: expected 1 input and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.gelu");
        if (!x)
            return false;

        // 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        // Cast constants to input dtype to avoid f16→f32 promotion.
        auto dt = x->dtype();
        auto c = [dt](float v) { return mlx::core::astype(mlx::core::array(v), dt); };
        auto x3 = mlx::core::multiply(mlx::core::multiply(*x, *x, {}), *x, {});
        auto inner = mlx::core::multiply(
            c(0.7978845608F), mlx::core::add(*x, mlx::core::multiply(c(0.044715F), x3, {}), {}),
            {});
        auto result = mlx::core::multiply(
            c(0.5F),
            mlx::core::multiply(*x, mlx::core::add(c(1.0F), mlx::core::tanh(inner, {}), {}), {}),
            {});
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Handle mps.sdpa_bwd — backward for SDPA via mlx::core::vjp.
    // Inputs: q, k, v, mask, grad_out; backend_config: {"scale": <float>}
    // Outputs: dq, dk, dv
    if (callTargetName == "mps.sdpa_bwd") {
        if (op->getNumOperands() != 5 || op->getNumResults() != 3) {
            MPS_LOG_ERROR("mps.sdpa_bwd: expected 5 inputs and 3 outputs\n");
            return false;
        }
        auto* q = RequireValue(values, op->getOperand(0), "mps.sdpa_bwd");
        auto* k = RequireValue(values, op->getOperand(1), "mps.sdpa_bwd");
        auto* v = RequireValue(values, op->getOperand(2), "mps.sdpa_bwd");
        auto* mask = RequireValue(values, op->getOperand(3), "mps.sdpa_bwd");
        auto* g = RequireValue(values, op->getOperand(4), "mps.sdpa_bwd");
        if (!q || !k || !v || !mask || !g)
            return false;
        if (!IsValidSdpaMaskDtype(*mask)) {
            MPS_LOG_ERROR("mps.sdpa_bwd: mask must be boolean or floating\n");
            return false;
        }

        float scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("scale"))
            scale = static_cast<float>(*v);

        auto additive_mask = MaskToAdditive(*mask, q->dtype());
        auto vjp_fn = [scale, &additive_mask](const std::vector<mlx::core::array>& primals) {
            return std::vector<mlx::core::array>{mlx::core::fast::scaled_dot_product_attention(
                primals[0], primals[1], primals[2], scale, "", additive_mask)};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*q, *k, *v}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(grads[1]));
        values.emplace(ToKey(op->getResult(2)), std::move(grads[2]));
        return true;
    }

    // Handle mps.sdpa_causal_bwd — backward for causal SDPA via mlx::core::vjp.
    if (callTargetName == "mps.sdpa_causal_bwd") {
        if (op->getNumOperands() != 4 || op->getNumResults() != 3) {
            MPS_LOG_ERROR("mps.sdpa_causal_bwd: expected 4 inputs and 3 outputs\n");
            return false;
        }
        auto* q = RequireValue(values, op->getOperand(0), "mps.sdpa_causal_bwd");
        auto* k = RequireValue(values, op->getOperand(1), "mps.sdpa_causal_bwd");
        auto* v = RequireValue(values, op->getOperand(2), "mps.sdpa_causal_bwd");
        auto* g = RequireValue(values, op->getOperand(3), "mps.sdpa_causal_bwd");
        if (!q || !k || !v || !g)
            return false;

        float scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("scale"))
            scale = static_cast<float>(*v);

        auto vjp_fn = [scale](const std::vector<mlx::core::array>& primals) {
            return std::vector<mlx::core::array>{mlx::core::fast::scaled_dot_product_attention(
                primals[0], primals[1], primals[2], scale, "causal")};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*q, *k, *v}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(grads[1]));
        values.emplace(ToKey(op->getResult(2)), std::move(grads[2]));
        return true;
    }

    // Handle mps.rms_norm_bwd — backward for RMS norm via mlx::core::vjp.
    // Inputs: x, weight, grad_out; backend_config: {"eps": <float>}
    // Outputs: dx, dweight
    if (callTargetName == "mps.rms_norm_bwd") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 2) {
            MPS_LOG_ERROR("mps.rms_norm_bwd: expected 3 inputs and 2 outputs\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.rms_norm_bwd");
        auto* w = RequireValue(values, op->getOperand(1), "mps.rms_norm_bwd");
        auto* g = RequireValue(values, op->getOperand(2), "mps.rms_norm_bwd");
        if (!x || !w || !g)
            return false;

        float eps = 1e-6F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getNumber("eps"))
            eps = static_cast<float>(*v);

        auto vjp_fn = [eps](const std::vector<mlx::core::array>& primals) {
            return std::vector<mlx::core::array>{
                mlx::core::fast::rms_norm(primals[0], primals[1], eps)};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*x, *w}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(grads[1]));
        return true;
    }

    // Handle mps.rope_bwd — backward for RoPE via mlx::core::vjp.
    // Inputs: x, offset (int32 scalar), grad_out; backend_config same as mps.rope
    // Outputs: dx
    if (callTargetName == "mps.rope_bwd") {
        if (op->getNumOperands() != 3 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.rope_bwd: expected 3 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.rope_bwd");
        auto* offsetArr = RequireValue(values, op->getOperand(1), "mps.rope_bwd");
        auto* g = RequireValue(values, op->getOperand(2), "mps.rope_bwd");
        if (!x || !offsetArr || !g)
            return false;

        int dims = 0;
        bool traditional = false;
        float base = 10000.0F;
        float rope_scale = 1.0F;
        auto bc = ParseBackendConfig(customCallOp);
        if (auto v = bc.getInteger("dims"))
            dims = static_cast<int>(*v);
        if (auto v = bc.getNumber("base"))
            base = static_cast<float>(*v);
        if (auto v = bc.getNumber("rope_scale"))
            rope_scale = static_cast<float>(*v);
        if (auto v = bc.getBoolean("traditional"))
            traditional = *v;

        auto vjp_fn = [dims, traditional, base, rope_scale,
                       &offsetArr](const std::vector<mlx::core::array>& primals) {
            return std::vector<mlx::core::array>{
                mlx::core::fast::rope(primals[0], dims, traditional, base, rope_scale, *offsetArr)};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*x}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        return true;
    }

    // Handle mps.gelu_bwd — backward for GELU via mlx::core::vjp.
    // Inputs: x, grad_out; Outputs: dx
    if (callTargetName == "mps.gelu_bwd") {
        if (op->getNumOperands() != 2 || op->getNumResults() != 1) {
            MPS_LOG_ERROR("mps.gelu_bwd: expected 2 inputs and 1 output\n");
            return false;
        }
        auto* x = RequireValue(values, op->getOperand(0), "mps.gelu_bwd");
        auto* g = RequireValue(values, op->getOperand(1), "mps.gelu_bwd");
        if (!x || !g)
            return false;

        auto vjp_fn = [](const std::vector<mlx::core::array>& primals) {
            const auto& x = primals[0];
            auto dt = x.dtype();
            auto c = [dt](float v) { return mlx::core::astype(mlx::core::array(v), dt); };
            auto x3 = mlx::core::multiply(mlx::core::multiply(x, x, {}), x, {});
            auto inner = mlx::core::multiply(
                c(0.7978845608F), mlx::core::add(x, mlx::core::multiply(c(0.044715F), x3, {}), {}),
                {});
            return std::vector<mlx::core::array>{mlx::core::multiply(
                c(0.5F),
                mlx::core::multiply(x, mlx::core::add(c(1.0F), mlx::core::tanh(inner, {}), {}), {}),
                {})};
        };
        auto [fwd_out, grads] = mlx::core::vjp(vjp_fn, {*x}, {*g});
        values.emplace(ToKey(op->getResult(0)), std::move(grads[0]));
        return true;
    }

    // Handle mps.eigh — symmetric eigendecomposition via MLX.
    // Inputs: a (symmetric matrix).  Outputs: eigenvectors, eigenvalues.
    if (callTargetName == "mps.eigh") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 2) {
            MPS_LOG_ERROR("mps.eigh: expected 1 input and 2 outputs\n");
            return false;
        }
        auto* a = RequireValue(values, op->getOperand(0), "mps.eigh");
        if (!a)
            return false;

        bool lower = true;
        if (auto v = ParseBackendConfig(customCallOp).getBoolean("lower"))
            lower = *v;

        auto a_contig = mlx::core::contiguous(*a);
        // Run eigh on the CPU (LAPACK). The vendored Metal Jacobi kernel
        // intermittently races under MLX's untracked-resource model AND is
        // 10-90x slower than CPU eigh across all sizes; upstream MLX has no GPU
        // eigh either. MLX handles the GPU<->CPU data movement and cross-stream
        // synchronization for the result.
        //
        // UPLO is inverted vs the GPU path: MLX arrays are row-major but LAPACK
        // is column-major, so reading the "upper" triangle of a row-major array
        // means passing "L" to MLX's CPU eigh (and vice versa). This only
        // matters when the unused triangle holds non-symmetric data; for
        // genuinely symmetric inputs both choices are equivalent.
        auto [eigenvalues, eigenvectors] =
            mlx::core::linalg::eigh(a_contig, lower ? "U" : "L", mlx::core::Device::cpu);
        values.emplace(ToKey(op->getResult(0)), std::move(eigenvectors));
        values.emplace(ToKey(op->getResult(1)), std::move(eigenvalues));
        return true;
    }

    // Handle mps.qr — QR decomposition via MLX.
    // Inputs: a.  Outputs: Q, R.
    if (callTargetName == "mps.qr") {
        if (op->getNumOperands() != 1 || op->getNumResults() != 2) {
            MPS_LOG_ERROR("mps.qr: expected 1 input and 2 outputs\n");
            return false;
        }
        auto* a = RequireValue(values, op->getOperand(0), "mps.qr");
        if (!a)
            return false;

        bool full_matrices = false;
        if (auto v = ParseBackendConfig(customCallOp).getBoolean("full_matrices"))
            full_matrices = *v;

        auto a_contig = mlx::core::contiguous(*a);
        // Run QR on the CPU (same rationale as eigh): the vendored Metal kernel
        // races under MLX's untracked-resource model and is slower than LAPACK;
        // upstream MLX has no GPU QR. MLX handles GPU<->CPU movement + sync.
        auto [Q, R] = mlx::core::linalg::qr(a_contig, mlx::core::Device::cpu);

        if (full_matrices) {
            // MLX QR returns thin: Q is M×K, R is K×N (K=min(M,N)).
            // For full_matrices: Q should be M×M, R should be M×N.
            // Pad with zeros (the extra Q columns are not a proper
            // orthogonal complement, but match JAX's convention for
            // reconstruction: Q @ R = A regardless).
            auto ndim = Q.ndim();
            auto M = a->shape(static_cast<int>(a->ndim()) - 2);
            auto N = a->shape(static_cast<int>(a->ndim()) - 1);
            auto K = std::min(M, N);

            if (Q.shape(static_cast<int>(ndim) - 1) != M) {
                // Pad Q columns: M×K → M×M
                auto pad_width = mlx::core::zeros({Q.shape(0), M - K}, Q.dtype());
                if (ndim == 2) {
                    Q = mlx::core::concatenate({Q, pad_width}, 1);
                } else {
                    // Batched: reshape pad to match batch dims
                    auto pw_shape = Q.shape();
                    pw_shape[static_cast<int>(ndim) - 1] = M - K;
                    pad_width = mlx::core::zeros(pw_shape, Q.dtype());
                    Q = mlx::core::concatenate({Q, pad_width}, static_cast<int>(ndim) - 1);
                }
            }
            if (R.shape(static_cast<int>(ndim) - 2) != M) {
                // Pad R rows: K×N → M×N
                auto pw_shape = R.shape();
                pw_shape[static_cast<int>(ndim) - 2] = M - K;
                auto pad_rows = mlx::core::zeros(pw_shape, R.dtype());
                R = mlx::core::concatenate({R, pad_rows}, static_cast<int>(ndim) - 2);
            }
        }

        values.emplace(ToKey(op->getResult(0)), std::move(Q));
        values.emplace(ToKey(op->getResult(1)), std::move(R));
        return true;
    }

    // Handle mps.svd — SVD via MLX.
    // Inputs: a.  Outputs: U, S, Vt (compute_uv=true) or S (compute_uv=false).
    if (callTargetName == "mps.svd") {
        if (op->getNumOperands() != 1) {
            MPS_LOG_ERROR("mps.svd: expected 1 input\n");
            return false;
        }
        auto* a = RequireValue(values, op->getOperand(0), "mps.svd");
        if (!a)
            return false;

        if (op->getNumResults() != 1 && op->getNumResults() != 3) {
            MPS_LOG_ERROR("mps.svd: expected 1 or 3 outputs, got %u\n", op->getNumResults());
            return false;
        }
        bool compute_uv = (op->getNumResults() == 3);

        bool full_matrices = true;
        if (auto v = ParseBackendConfig(customCallOp).getBoolean("full_matrices"))
            full_matrices = *v;

        auto a_contig = mlx::core::contiguous(*a);
        // Run SVD on the CPU (same rationale as eigh/qr).
        auto results = mlx::core::linalg::svd(a_contig, compute_uv, mlx::core::Device::cpu);

        if (compute_uv) {
            if (results.size() != 3) {
                MPS_LOG_ERROR("mps.svd: MLX returned %zu results, expected 3\n", results.size());
                return false;
            }
            auto U = results[0];   // M×M (full)
            auto S = results[1];   // K
            auto Vt = results[2];  // N×N (full)

            if (!full_matrices) {
                // Slice to thin: U → M×K, Vt → K×N
                auto ndim = static_cast<int>(U.ndim());
                auto K = static_cast<int>(S.shape(static_cast<int>(S.ndim()) - 1));

                // U[:, :K]
                mlx::core::Shape u_start(ndim, 0);
                auto u_stop = U.shape();
                u_stop[ndim - 1] = K;
                U = mlx::core::slice(U, u_start, u_stop);

                // Vt[:K, :]
                mlx::core::Shape vt_start(ndim, 0);
                auto vt_stop = Vt.shape();
                vt_stop[ndim - 2] = K;
                Vt = mlx::core::slice(Vt, vt_start, vt_stop);
            }

            // JAX svd_p returns (s, u, vt) – singular values first!
            values.emplace(ToKey(op->getResult(0)), std::move(S));
            values.emplace(ToKey(op->getResult(1)), std::move(U));
            values.emplace(ToKey(op->getResult(2)), std::move(Vt));
        } else {
            if (results.size() != 1) {
                MPS_LOG_ERROR("mps.svd: MLX returned %zu results, expected 1\n", results.size());
                return false;
            }
            values.emplace(ToKey(op->getResult(0)), std::move(results[0]));  // S
        }
        return true;
    }

    MPS_LOG_ERROR("stablehlo.custom_call: unsupported target '%s'\n", callTargetName.c_str());
    return false;
}

// Handler for stablehlo.composite
bool HandleComposite(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                     ExecContext& ctx) {
    auto compositeOp = CastOp<mlir::stablehlo::CompositeOp>(op, "stablehlo.composite");
    if (!compositeOp)
        return false;

    auto compositeName = compositeOp.getName().str();
    auto decompositionName = compositeOp.getDecomposition().str();

    MPS_LOG_DEBUG("stablehlo.composite: name=%s decomposition=%s\n", compositeName.c_str(),
                  decompositionName.c_str());

    // Gather inputs
    std::vector<mlx::core::array> inputs;
    for (auto operand : op->getOperands()) {
        auto* val = RequireValue(values, operand, compositeName.c_str());
        if (!val)
            return false;
        inputs.push_back(*val);
    }

    // Try native MLX dispatch for known single-input CHLO composite ops,
    // via the shared unary op table. Use string_view to avoid per-lookup allocation.
    static constexpr std::string_view kChloPrefix = "chlo.";
    std::string_view compName{compositeName};
    if (inputs.size() == 1 && op->getNumResults() == 1 &&
        compName.substr(0, kChloPrefix.size()) == kChloPrefix) {
        const auto& unaryOps = UnaryMlxOps();
        auto it = unaryOps.find(compName.substr(kChloPrefix.size()));
        if (it != unaryOps.end()) {
            values.emplace(ToKey(op->getResult(0)), it->second(inputs[0], {}));
            return true;
        }
    }

    // Try native MLX dispatch for known two-input CHLO composite ops
    if (inputs.size() == 2 && op->getNumResults() == 1 && compositeName == "chlo.atan2") {
        values.emplace(ToKey(op->getResult(0)), mlx::core::arctan2(inputs[0], inputs[1], {}));
        return true;
    }

    // Handle chlo.top_k natively using shared TopKImpl
    if (inputs.size() == 1 && op->getNumResults() == 2 && compositeName == "chlo.top_k") {
        auto resultType = mlir::cast<mlir::RankedTensorType>(op->getResult(0).getType());
        int k = static_cast<int>(resultType.getShape().back());
        auto [topValues, indices] = TopKImpl(inputs[0], k);
        values.emplace(ToKey(op->getResult(0)), std::move(topValues));
        values.emplace(ToKey(op->getResult(1)), std::move(indices));
        return true;
    }

    // Fallback: execute the decomposition function
    auto decompFunc = ctx.module.lookupSymbol<mlir::func::FuncOp>(decompositionName);
    if (!decompFunc) {
        MPS_LOG_ERROR("stablehlo.composite %s: decomposition function '%s' not found\n",
                      compositeName.c_str(), decompositionName.c_str());
        return false;
    }

    std::vector<mlx::core::array> decompOutputs;
    if (!ExecuteFunction(decompFunc, inputs, decompOutputs, ctx)) {
        MPS_LOG_ERROR("stablehlo.composite %s: decomposition execution failed\n",
                      compositeName.c_str());
        return false;
    }

    if (decompOutputs.size() != op->getNumResults()) {
        MPS_LOG_ERROR("stablehlo.composite %s: result count mismatch (got %zu, expected %u)\n",
                      compositeName.c_str(), decompOutputs.size(), op->getNumResults());
        return false;
    }

    for (size_t i = 0; i < decompOutputs.size(); ++i) {
        values.emplace(ToKey(op->getResult(i)), std::move(decompOutputs[i]));
    }

    return true;
}

// Tokens have no numerical payload. A scalar boolean carries their dependency
// edges through the MLX graph; public PJRT metadata retains the TOKEN type.
bool HandleCreateToken(mlir::Operation* op, ValueMap& values,
                       std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    values.emplace(ToKey(op->getResult(0)), mlx::core::array(false));
    return true;
}

// Read every predecessor marker so joined effects retain their dependencies.
bool HandleAfterAll(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                    ExecContext& ctx) {
    auto marker = mlx::core::array(false);
    for (auto operand : op->getOperands()) {
        auto* predecessor = RequireValue(values, operand, "stablehlo.after_all");
        if (!predecessor)
            return false;
        marker = mlx::core::logical_or(
            marker, mlx::core::astype(*predecessor, mlx::core::bool_));
    }
    values.emplace(ToKey(op->getResult(0)), std::move(marker));
    return true;
}

// Handler for stablehlo.optimization_barrier
bool HandleOptimizationBarrier(mlir::Operation* op, ValueMap& values,
                               std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    for (unsigned i = 0; i < op->getNumResults(); ++i) {
        auto* val = RequireValue(values, op->getOperand(i), "stablehlo.optimization_barrier");
        if (!val)
            return false;
        values.emplace(ToKey(op->getResult(i)), *val);
    }
    return true;
}

// Handler for sdy.sharding_constraint. The parser admits only single-device
// meshes (see checkSingleDevice), where a sharding constraint is the identity.
bool HandleShardingConstraint(mlir::Operation* op, ValueMap& values,
                              std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    auto* val = RequireValue(values, op->getOperand(0), "sdy.sharding_constraint");
    if (!val)
        return false;
    values.emplace(ToKey(op->getResult(0)), *val);
    return true;
}

// Handler for stablehlo.rng_bit_generator.
// Uses MLX's PRNG seeded from the state. Random values will differ from CPU/GPU backends
// but the state is correctly tracked (counter incremented by ceil(output_bytes / 16)).
bool HandleRngBitGenerator(mlir::Operation* op, ValueMap& values,
                           std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    auto rngOp = CastOp<mlir::stablehlo::RngBitGeneratorOp>(op, "stablehlo.rng_bit_generator");
    if (!rngOp)
        return false;

    auto* state = RequireValue(values, op->getOperand(0), "stablehlo.rng_bit_generator");
    if (!state)
        return false;

    // Get shapes/dtypes from MLIR types (available at graph construction time)
    auto outputType = mlir::dyn_cast<mlir::RankedTensorType>(op->getResult(1).getType());
    if (!outputType) {
        MPS_LOG_ERROR("stablehlo.rng_bit_generator: result type is not RankedTensorType\n");
        return false;
    }
    auto outputShape = GetShape(outputType);
    auto outputDtype = MlirTypeToMlxDtype(outputType.getElementType());

    // Derive MLX random key (uint32[2]) from the state.
    // State is uint64[2] (from JAX lowering). View as uint32 and take first 2 elements as key.
    auto state_u32 = mlx::core::view(mlx::core::flatten(*state), mlx::core::uint32);
    auto key = mlx::core::slice(state_u32, {0}, {2});

    // Generate random bits
    size_t target_bytes = GetDtypeSize(outputDtype);
    mlx::core::array random_output(0);
    if (target_bytes <= 4) {
        random_output = mlx::core::random::bits(outputShape, 4, key);
        random_output = mlx::core::astype(random_output, outputDtype);
    } else {
        // For uint64 output: generate 2x uint32 per element and reinterpret
        auto expandedShape = outputShape;
        expandedShape.push_back(2);
        auto bits32 = mlx::core::random::bits(expandedShape, 4, key);
        random_output = mlx::core::view(bits32, outputDtype);
        random_output = mlx::core::reshape(random_output, outputShape);
    }

    // Compute counter increment: 4 uint32 outputs per counter step (16 bytes).
    size_t total_elements = 1;
    for (auto d : outputShape)
        total_elements *= static_cast<size_t>(d);
    size_t total_bytes = total_elements * target_bytes;
    uint64_t counter_incr = (total_bytes + 15) / 16;

    // Update state: state is uint64[2] = [key, counter]. Increment counter (element 1).
    auto key_part = mlx::core::slice(*state, {0}, {1});
    auto counter = mlx::core::add(mlx::core::slice(*state, {1}, {2}),
                                  mlx::core::array(counter_incr, mlx::core::uint64));
    auto output_state = mlx::core::concatenate({key_part, counter}, 0);

    // Result 0: output_state, Result 1: random output
    values.emplace(ToKey(op->getResult(0)), std::move(output_state));
    values.emplace(ToKey(op->getResult(1)), std::move(random_output));
    return true;
}

}  // namespace

void RegisterControlFlowHandlers(std::unordered_map<std::string, OpHandler>& handlers) {
    handlers.insert({"func.return", HandleReturn});
    handlers.insert({"func.call", HandleCall});
    handlers.insert({"stablehlo.return", HandleStablehloReturn});
    handlers.insert({"stablehlo.custom_call", HandleCustomCall});
    handlers.insert({"stablehlo.composite", HandleComposite});
    handlers.insert({"stablehlo.optimization_barrier", HandleOptimizationBarrier});
    handlers.insert({"stablehlo.while", HandleWhile});
    handlers.insert({"stablehlo.case", HandleCase});
    handlers.insert({"stablehlo.rng_bit_generator", HandleRngBitGenerator});
    handlers.insert({"stablehlo.create_token", HandleCreateToken});
    handlers.insert({"stablehlo.after_all", HandleAfterAll});
    handlers.insert({"sdy.sharding_constraint", HandleShardingConstraint});
}

}  // namespace jax_mps

