// Gather and scatter op handlers.

#include <algorithm>
#include <limits>
#include <mlx/fast.h>
#include <set>
#include <stdexcept>

#include "pjrt_plugin/ops/handler_utils.h"
#include "stablehlo/dialect/StablehloOps.h"

namespace jax_mps {

// --- Shared scatter utilities (declared in handler_utils.h) ---

ScatterType DetectScatterType(mlir::Region& body) {
    if (body.empty() || body.front().getNumArguments() != 2)
        return ScatterType::Unknown;
    auto& block = body.front();
    auto& terminator = block.back();
    if (terminator.getNumOperands() != 1)
        return ScatterType::Unknown;
    auto returned = terminator.getOperand(0);
    auto lhs = block.getArgument(0);
    auto rhs = block.getArgument(1);
    if (returned == rhs)
        return ScatterType::Update;
    auto* combine = returned.getDefiningOp();
    if (!combine || combine->getNumOperands() != 2)
        return ScatterType::Unknown;
    bool direct = combine->getOperand(0) == lhs && combine->getOperand(1) == rhs;
    bool reversed = combine->getOperand(0) == rhs && combine->getOperand(1) == lhs;
    if (!direct && !reversed)
        return ScatterType::Unknown;
    auto name = combine->getName().getStringRef();
    if (name == "stablehlo.add")
        return ScatterType::Add;
    if (name == "stablehlo.subtract" && direct)
        return ScatterType::Sub;
    if (name == "stablehlo.multiply")
        return ScatterType::Mul;
    if (name == "stablehlo.minimum")
        return ScatterType::Min;
    if (name == "stablehlo.maximum")
        return ScatterType::Max;
    return ScatterType::Unknown;
}

namespace {

// Extract indices without narrowing. The gather caller clamps to the operand
// extent in this dtype before converting to MLX's int32 address representation.
struct IndexExtraction {
    std::vector<mlx::core::array> idxVec;
    std::vector<int> axes;
    mlx::core::Shape idxBatchShape;
    bool hasIdxVecDim;
};

std::optional<IndexExtraction> ExtractPerAxisIndices(const mlx::core::array& startIndices,
                                                     llvm::ArrayRef<int64_t> indexMap,
                                                     int indexVectorDim, const char* opName) {
    IndexExtraction result;
    result.hasIdxVecDim = indexVectorDim < startIndices.ndim();

    if (!result.hasIdxVecDim && indexMap.size() > 1) {
        MPS_LOG_ERROR("%s: indexMap.size=%zu > 1 but no index_vector_dim\n", opName,
                      indexMap.size());
        return std::nullopt;
    }

    for (int d = 0; d < startIndices.ndim(); ++d) {
        if (!result.hasIdxVecDim || d != indexVectorDim) {
            result.idxBatchShape.push_back(startIndices.shape(d));
        }
    }

    for (size_t i = 0; i < indexMap.size(); ++i) {
        int axis = static_cast<int>(indexMap[i]);
        result.axes.push_back(axis);

        mlx::core::array axisIdx = startIndices;
        if (result.hasIdxVecDim) {
            mlx::core::Shape starts(startIndices.ndim(), 0);
            mlx::core::Shape stops(startIndices.shape().begin(), startIndices.shape().end());
            starts[indexVectorDim] = static_cast<int>(i);
            stops[indexVectorDim] = static_cast<int>(i) + 1;
            axisIdx =
                mlx::core::squeeze(mlx::core::slice(startIndices, starts, stops), {indexVectorDim});
        }

        result.idxVec.push_back(axisIdx);
    }

    return result;
}

// Helper: add iota indices for batching dimensions.
void AddBatchingIotas(std::vector<mlx::core::array>& idxVec, std::vector<int>& axes,
                      const mlx::core::array& operand, const mlx::core::Shape& idxBatchShape,
                      llvm::ArrayRef<int64_t> operandBatchingDims,
                      llvm::ArrayRef<int64_t> indicesBatchingDims, bool hasIdxVecDim,
                      int indexVectorDim) {
    for (size_t i = 0; i < operandBatchingDims.size(); ++i) {
        int operandAxis = static_cast<int>(operandBatchingDims[i]);
        int idxBatchDim = static_cast<int>(indicesBatchingDims[i]);
        if (hasIdxVecDim && idxBatchDim > indexVectorDim) {
            --idxBatchDim;
        }

        axes.push_back(operandAxis);

        int batchSz = operand.shape(operandAxis);
        mlx::core::Shape iotaShape(idxBatchShape.size(), 1);
        iotaShape[idxBatchDim] = batchSz;
        auto iota = mlx::core::reshape(mlx::core::arange(batchSz, mlx::core::int32), iotaShape);
        iota = mlx::core::broadcast_to(iota, idxBatchShape);
        idxVec.push_back(iota);
    }
}

// Handler for stablehlo.gather
bool HandleGather(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                  ExecContext& ctx) {
    auto gatherOp = CastOp<mlir::stablehlo::GatherOp>(op, "stablehlo.gather");
    if (!gatherOp)
        return false;

    auto* operand = RequireValue(values, gatherOp.getOperand(), "stablehlo.gather");
    auto* startIndices = RequireValue(values, gatherOp.getStartIndices(), "stablehlo.gather");
    if (!operand || !startIndices)
        return false;

    auto dn = gatherOp.getDimensionNumbers();
    auto offsetDims = dn.getOffsetDims();
    auto collapsedSliceDims = dn.getCollapsedSliceDims();
    auto startIndexMap = dn.getStartIndexMap();
    int indexVectorDim = static_cast<int>(dn.getIndexVectorDim());
    auto operandBatchingDims = dn.getOperandBatchingDims();
    auto startIndicesBatchingDims = dn.getStartIndicesBatchingDims();

    mlx::core::Shape sliceSizes;
    for (auto s : gatherOp.getSliceSizes()) {
        sliceSizes.push_back(static_cast<int>(s));
    }

    // Step 1: Extract per-axis index arrays
    auto extraction_opt =
        ExtractPerAxisIndices(*startIndices, startIndexMap, indexVectorDim, "stablehlo.gather");
    if (!extraction_opt)
        return false;
    auto& idxVec = extraction_opt->idxVec;
    auto& axes = extraction_opt->axes;
    auto& idxBatchShape = extraction_opt->idxBatchShape;

    // Clamp gather indices to valid range
    for (size_t i = 0; i < idxVec.size(); ++i) {
        int axis = axes[i];
        int maxStart = operand->shape(axis) - sliceSizes[axis];
        auto dtype = mlx::core::issubdtype(idxVec[i].dtype(), mlx::core::unsignedinteger) ?
            mlx::core::uint64 : mlx::core::int64;
        auto wide = mlx::core::astype(idxVec[i], dtype);
        idxVec[i] = mlx::core::astype(
            mlx::core::clip(wide, mlx::core::array(0, dtype),
                            mlx::core::array(std::max(0, maxStart), dtype)),
            mlx::core::int32);
    }

    // Step 2: Add iota indices for operand_batching_dims
    AddBatchingIotas(idxVec, axes, *operand, idxBatchShape, operandBatchingDims,
                     startIndicesBatchingDims, extraction_opt->hasIdxVecDim, indexVectorDim);

    // Step 3: Call mlx::core::gather
    auto result = mlx::core::gather(*operand, idxVec, axes, sliceSizes);

    // Step 4: Squeeze collapsed_slice_dims and operand_batching_dims
    int idxNdim = static_cast<int>(idxBatchShape.size());
    std::vector<int> squeezeDims;
    for (auto d : collapsedSliceDims) {
        squeezeDims.push_back(idxNdim + static_cast<int>(d));
    }
    for (auto d : operandBatchingDims) {
        squeezeDims.push_back(idxNdim + static_cast<int>(d));
    }
    std::sort(squeezeDims.begin(), squeezeDims.end());
    if (!squeezeDims.empty()) {
        result = mlx::core::squeeze(result, squeezeDims);
    }

    // Step 5: Transpose to place offset_dims at their specified positions
    int resultRank = static_cast<int>(result.ndim());
    int numOffset = static_cast<int>(offsetDims.size());
    int numBatch = resultRank - numOffset;

    std::set<int> offsetDimSet(offsetDims.begin(), offsetDims.end());
    std::vector<int> perm;
    int batchIdx = 0;
    int offsetIdx = 0;
    for (int p = 0; p < resultRank; ++p) {
        if (offsetDimSet.count(p)) {
            perm.push_back(numBatch + offsetIdx++);
        } else {
            perm.push_back(batchIdx++);
        }
    }

    if (!IsIdentityPermutation(perm)) {
        result = mlx::core::transpose(result, perm);
    }

    // Step 6: Safety reshape to expected output shape
    auto resultType = mlir::dyn_cast<mlir::RankedTensorType>(op->getResult(0).getType());
    if (resultType) {
        auto expectedShape = GetShape(resultType);
        if (result.shape() != expectedShape) {
            result = mlx::core::reshape(result, expectedShape);
        }
    }

    values.emplace(ToKey(op->getResult(0)), std::move(result));
    return true;
}

// A single destination per update element, never an operand/update Cartesian
// tensor. Immutable metadata describes shapes and StableHLO dimension numbers.
mlx::core::array ScatterDestinations(const mlx::core::array& indices,
                                     const mlx::core::array& metadata, int count) {
    static const auto kernel = mlx::core::fast::metal_kernel(
        "phydrax_scatter_destinations", {"indices", "meta"}, {"destinations"}, R"(
        uint u = thread_position_in_grid.x;
        int rank = meta[0], urank = meta[1], irank = meta[2];
        int os = 4, us = os + rank, ust = us + urank;
        int ist = ust + urank, wm = ist + irank;
        int bm = wm + rank, cm = bm + rank, im = cm + rank;
        ulong index_offset = 0;
        for (int d = 0; d < irank; ++d) {
            int ud = meta[im + d];
            if (ud >= 0)
                index_offset += ulong((u / uint(meta[ust + ud])) %
                                      uint(meta[us + ud])) * ulong(meta[ist + d]);
        }
        ulong destination = 0;
        for (int d = 0; d < rank; ++d) {
            int wd = meta[wm + d], bd = meta[bm + d], component = meta[cm + d];
            long extent = long(meta[os + d]);
            long window_extent = wd < 0 ? 1 : long(meta[us + wd]);
            long max_start = extent - window_extent;
            // FILL_OR_DROP admits the complete window, not its individual
            // elements. Use its mapped update extent even when window and
            // batch dimensions are interleaved. Compare before any addition
            // or narrowing so INT64_MIN/MAX and UINT64_MAX cannot wrap.
            long start = 0;
            if (max_start < 0) {
                destinations[u] = 0xffffffffu;
                return;
            }
            if (component >= 0) {
                ulong pos = index_offset + ulong(component) * ulong(meta[3]);
                if constexpr (SIGNED_INDEX) {
                    start = long(indices[pos]);
                    if (start < 0 || start > max_start) {
                        destinations[u] = 0xffffffffu;
                        return;
                    }
                } else {
                    ulong unsigned_start = ulong(indices[pos]);
                    if (unsigned_start > ulong(max_start)) {
                        destinations[u] = 0xffffffffu;
                        return;
                    }
                    start = long(unsigned_start);
                }
            }
            long coordinate = wd < 0 ? 0 :
                long((u / uint(meta[ust + wd])) % uint(meta[us + wd]));
            if (bd >= 0)
                coordinate = long((u / uint(meta[ust + bd])) % uint(meta[us + bd]));
            coordinate += start;
            if (coordinate < 0 || coordinate >= extent) {
                destinations[u] = 0xffffffffu;
                return;
            }
            destination = destination * ulong(extent) + ulong(coordinate);
        }
        destinations[u] = uint(destination);
        )");
    // A zero-component index vector is valid (a window-only scatter). Bind a
    // nonempty buffer even though that shader specialization never reads it.
    auto flatIndices = indices.size() == 0 ?
        mlx::core::zeros({1}, indices.dtype(), mlx::core::Device::gpu) :
        mlx::core::reshape(indices, {static_cast<int>(indices.size())});
    return kernel(
        {flatIndices, metadata},
        {{count}}, {mlx::core::uint32}, {count, 1, 1}, {std::min(count, 256), 1, 1},
        {{"SIGNED_INDEX", mlx::core::issubdtype(indices.dtype(), mlx::core::signedinteger)}},
        std::nullopt, false, mlx::core::Device::gpu)[0];
}

// Stable destination sort retains original update order. Each output lane
// owns its complete fold: exact 64-bit/complex stores need no MLX atomics and
// duplicates cannot race or disappear. Storage O(O+U), work
// O(U log U + O log U + U). A heavily repeated destination is a serial GPU fold.
mlx::core::array FoldScatter(ScatterType type, const mlx::core::array& operand,
                             const mlx::core::array& updates,
                             const mlx::core::array& destinations) {
    static const auto kernel = mlx::core::fast::metal_kernel(
        "phydrax_scatter_fold", {"operand", "updates", "destinations", "order"}, {"result"},
        R"(
        uint destination = thread_position_in_grid.x;
        uint lo = 0, hi = UPDATE_COUNT;
        while (lo < hi) {
            uint mid = lo + (hi - lo) / 2;
            if (destinations[order[mid]] < destination) lo = mid + 1;
            else hi = mid;
        }
        T value = operand[destination];
        for (uint p = lo; p < UPDATE_COUNT; ++p) {
            uint update = order[p];
            if (destinations[update] != destination) break;
            T next = updates[update];
            if constexpr (MODE == 0) value = next;
            if constexpr (MODE == 1) {
                if constexpr (INTEGER) value = T(ulong(value) + ulong(next));
                else value = value + next;
            }
            if constexpr (MODE == 2) {
                if constexpr (INTEGER) value = T(ulong(value) - ulong(next));
                else value = value - next;
            }
            if constexpr (MODE == 3) {
                if constexpr (INTEGER) value = T(ulong(value) * ulong(next));
                else value = value * next;
            }
            if constexpr (MODE == 4 || MODE == 5) {
                if constexpr (FLOATING) {
                    // Propagate NaNs; min(-0,+0)=-0, max(-0,+0)=+0.
                    if (isnan(value)) {}
                    else if (isnan(next)) value = next;
                    else if (value == T(0) && next == T(0)) {
                        uint a = as_type<uint>(value), b = as_type<uint>(next);
                        value = as_type<float>(MODE == 4 ? (a | b) : (a & b));
                    } else if (MODE == 4 ? next < value : next > value) value = next;
                } else {
                    if (MODE == 4 ? next < value : next > value) value = next;
                }
            }
        }
        result[destination] = value;
        )");
    int mode;
    switch (type) {
        case ScatterType::Update: mode = 0; break;
        case ScatterType::Add: mode = 1; break;
        case ScatterType::Sub: mode = 2; break;
        case ScatterType::Mul: mode = 3; break;
        case ScatterType::Min: mode = 4; break;
        case ScatterType::Max: mode = 5; break;
        default: throw std::invalid_argument("phydrax-metal: unsupported scatter body");
    }
    const int count = static_cast<int>(operand.size());
    const int updateCount = static_cast<int>(updates.size());
    auto order = mlx::core::argsort(destinations, 0, mlx::core::Device::gpu);
    auto result = kernel(
        {mlx::core::reshape(operand, {count}), mlx::core::reshape(updates, {updateCount}),
         destinations, order},
        {{count}}, {operand.dtype()}, {count, 1, 1}, {std::min(count, 256), 1, 1},
        {{"T", operand.dtype()}, {"MODE", mode}, {"UPDATE_COUNT", updateCount},
         {"INTEGER", mlx::core::issubdtype(operand.dtype(), mlx::core::integer)},
         {"FLOATING", operand.dtype() == mlx::core::float32}},
        std::nullopt, false, mlx::core::Device::gpu)[0];
    return mlx::core::reshape(result, operand.shape());
}

bool HandleScatter(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                   ExecContext& ctx) {
    auto scatterOp = CastOp<mlir::stablehlo::ScatterOp>(op, "stablehlo.scatter");
    if (!scatterOp)
        return false;
    if (scatterOp.getInputs().size() != 1) {
        MPS_LOG_ERROR("stablehlo.scatter: multi-input scatter not supported\n");
        return false;
    }
    auto* operand = RequireValue(values, scatterOp.getInputs()[0], "stablehlo.scatter");
    auto* indices = RequireValue(values, scatterOp.getScatterIndices(), "stablehlo.scatter");
    auto* updates = RequireValue(values, scatterOp.getUpdates()[0], "stablehlo.scatter");
    if (!operand || !indices || !updates)
        return false;
    auto type = DetectScatterType(scatterOp.getUpdateComputation());
    if (type == ScatterType::Unknown) {
        // Gather/body/scatter is not valid for compounding duplicate updates.
        MPS_LOG_ERROR("stablehlo.scatter: unsupported update computation\n");
        return false;
    }
    if ((!mlx::core::issubdtype(operand->dtype(), mlx::core::integer) &&
         operand->dtype() != mlx::core::bool_ && operand->dtype() != mlx::core::float32 &&
         operand->dtype() != mlx::core::complex64) ||
        (operand->dtype() == mlx::core::complex64 &&
         (type == ScatterType::Min || type == ScatterType::Max))) {
        MPS_LOG_ERROR("stablehlo.scatter: unsupported value dtype/update combination\n");
        return false;
    }
    if (operand->size() == 0 || updates->size() == 0) {
        values.emplace(ToKey(op->getResult(0)), *operand);
        return true;
    }
    constexpr size_t limit = std::numeric_limits<int>::max();
    if (operand->size() > limit || updates->size() > limit || indices->size() > limit) {
        MPS_LOG_ERROR("stablehlo.scatter: array exceeds supported int32 dispatch capacity\n");
        return false;
    }
    auto dn = scatterOp.getScatterDimensionNumbers();
    int rank = static_cast<int>(operand->ndim());
    int urank = static_cast<int>(updates->ndim());
    int irank = static_cast<int>(indices->ndim());
    int iv = static_cast<int>(dn.getIndexVectorDim());
    std::vector<int> updateStrides(urank), indexStrides(irank);
    int stride = 1;
    for (int d = urank; d-- > 0;) {
        updateStrides[d] = stride;
        stride *= updates->shape(d);
    }
    stride = 1;
    for (int d = irank; d-- > 0;) {
        indexStrides[d] = stride;
        stride *= indices->shape(d);
    }
    std::set<int64_t> inserted(dn.getInsertedWindowDims().begin(),
                               dn.getInsertedWindowDims().end());
    std::set<int64_t> batching(dn.getInputBatchingDims().begin(),
                               dn.getInputBatchingDims().end());
    std::set<int64_t> window(dn.getUpdateWindowDims().begin(), dn.getUpdateWindowDims().end());
    std::vector<int> windowMap(rank, -1), batchMap(rank, -1), componentMap(rank, -1);
    std::vector<int> indexUpdateMap(irank, -1), updateScatterDims;
    for (int d = 0; d < urank; ++d)
        if (!window.count(d))
            updateScatterDims.push_back(d);
    size_t batch = 0;
    for (int d = 0; d < irank; ++d) {
        if (d == iv)
            continue;
        if (batch >= updateScatterDims.size()) {
            MPS_LOG_ERROR("stablehlo.scatter: inconsistent update/index batch ranks\n");
            return false;
        }
        indexUpdateMap[d] = updateScatterDims[batch++];
    }
    if (batch != updateScatterDims.size()) {
        MPS_LOG_ERROR("stablehlo.scatter: inconsistent update/index batch ranks\n");
        return false;
    }
    size_t w = 0;
    for (int d = 0; d < rank; ++d) {
        if (!inserted.count(d) && !batching.count(d)) {
            if (w >= dn.getUpdateWindowDims().size()) {
                MPS_LOG_ERROR("stablehlo.scatter: inconsistent window ranks\n");
                return false;
            }
            windowMap[d] = static_cast<int>(dn.getUpdateWindowDims()[w++]);
        }
    }
    for (size_t i = 0; i < dn.getInputBatchingDims().size(); ++i)
        batchMap[dn.getInputBatchingDims()[i]] =
            indexUpdateMap[dn.getScatterIndicesBatchingDims()[i]];
    for (size_t i = 0; i < dn.getScatterDimsToOperandDims().size(); ++i)
        componentMap[dn.getScatterDimsToOperandDims()[i]] = static_cast<int>(i);
    std::vector<int32_t> meta{rank, urank, irank, iv < irank ? indexStrides[iv] : 0};
    auto append = [&](const auto& items) { meta.insert(meta.end(), items.begin(), items.end()); };
    append(operand->shape());
    append(updates->shape());
    append(updateStrides);
    append(indexStrides);
    append(windowMap);
    append(batchMap);
    append(componentMap);
    append(indexUpdateMap);
    auto metadata = mlx::core::array(meta.begin(), {static_cast<int>(meta.size())});
    auto destinations = ScatterDestinations(*indices, metadata, static_cast<int>(updates->size()));
    values.emplace(ToKey(op->getResult(0)), FoldScatter(type, *operand, *updates, destinations));
    return true;
}

}  // namespace

void RegisterGatherScatterHandlers(std::unordered_map<std::string, OpHandler>& handlers) {
    handlers.insert({"stablehlo.gather", HandleGather});
    handlers.insert({"stablehlo.scatter", HandleScatter});
}

}  // namespace jax_mps

