// Linear algebra op handlers (dot_general, convolution, triangular_solve).
//
// Every handler runs on the Metal GPU. Integer contractions are computed
// exactly in the result integer type (two's-complement wraparound, as XLA);
// they never pass through floating point. Decompositions that would need a
// CPU LAPACK route (cholesky) have no handler and are refused at compile time.

#include <mlx/einsum.h>

#include <algorithm>
#include <limits>
#include <numeric>
#include <unordered_set>

#include "pjrt_plugin/ops/handler_utils.h"
#include "stablehlo/dialect/StablehloOps.h"

namespace jax_mps {

namespace {

// Elements of the broadcast product an exact integer contraction materializes.
// Larger integer contractions are refused rather than silently routed through
// floating point or the CPU.
constexpr int64_t kMaxIntegerDotElements = int64_t{1} << 27;

// Build einsum subscript string for dot_general
std::string BuildEinsumSubscript(int lhsRank, int rhsRank, llvm::ArrayRef<int64_t> lhsBatchDims,
                                 llvm::ArrayRef<int64_t> rhsBatchDims,
                                 llvm::ArrayRef<int64_t> lhsContractDims,
                                 llvm::ArrayRef<int64_t> rhsContractDims) {
    char nextChar = 'a';

    std::vector<char> lhsChars(lhsRank, 0);
    std::vector<char> rhsChars(rhsRank, 0);

    // Assign shared characters for batch dims
    for (size_t i = 0; i < lhsBatchDims.size(); ++i) {
        char c = nextChar++;
        lhsChars[lhsBatchDims[i]] = c;
        rhsChars[rhsBatchDims[i]] = c;
    }

    // Assign shared characters for contracting dims
    for (size_t i = 0; i < lhsContractDims.size(); ++i) {
        char c = nextChar++;
        lhsChars[lhsContractDims[i]] = c;
        rhsChars[rhsContractDims[i]] = c;
    }

    // Assign unique characters for free dims
    for (int i = 0; i < lhsRank; ++i) {
        if (lhsChars[i] == 0) {
            lhsChars[i] = nextChar++;
        }
    }
    for (int i = 0; i < rhsRank; ++i) {
        if (rhsChars[i] == 0) {
            rhsChars[i] = nextChar++;
        }
    }

    std::string lhsSub(lhsChars.begin(), lhsChars.end());
    std::string rhsSub(rhsChars.begin(), rhsChars.end());

    // Build output: batch dims first, then lhs free dims, then rhs free dims
    std::string outSub;
    for (int64_t d : lhsBatchDims) {
        outSub += lhsChars[d];
    }
    for (int i = 0; i < lhsRank; ++i) {
        bool isBatch = std::find(lhsBatchDims.begin(), lhsBatchDims.end(), i) != lhsBatchDims.end();
        bool isContract =
            std::find(lhsContractDims.begin(), lhsContractDims.end(), i) != lhsContractDims.end();
        if (!isBatch && !isContract) {
            outSub += lhsChars[i];
        }
    }
    for (int i = 0; i < rhsRank; ++i) {
        bool isBatch = std::find(rhsBatchDims.begin(), rhsBatchDims.end(), i) != rhsBatchDims.end();
        bool isContract =
            std::find(rhsContractDims.begin(), rhsContractDims.end(), i) != rhsContractDims.end();
        if (!isBatch && !isContract) {
            outSub += rhsChars[i];
        }
    }

    return lhsSub + "," + rhsSub + "->" + outSub;
}

// Handler for stablehlo.dot_general
bool HandleDotGeneral(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>& outputs,
                      ExecContext& ctx) {
    auto dotOp = CastOp<mlir::stablehlo::DotGeneralOp>(op, "stablehlo.dot_general");
    if (!dotOp)
        return false;

    auto* lhs = RequireValue(values, op->getOperand(0), "stablehlo.dot_general");
    auto* rhs = RequireValue(values, op->getOperand(1), "stablehlo.dot_general");
    if (!lhs || !rhs)
        return false;

    auto dimNumbers = dotOp.getDotDimensionNumbers();

    auto lhsContractDims = dimNumbers.getLhsContractingDimensions();
    auto rhsContractDims = dimNumbers.getRhsContractingDimensions();
    auto lhsBatchDims = dimNumbers.getLhsBatchingDimensions();
    auto rhsBatchDims = dimNumbers.getRhsBatchingDimensions();

    auto lhsRank = static_cast<int>(lhs->ndim());
    auto rhsRank = static_cast<int>(rhs->ndim());

    auto resultDtype = GetResultDtype(op, "stablehlo.dot_general");
    if (!resultDtype)
        return false;
    const bool exactInteger = !mlx::core::issubdtype(*resultDtype, mlx::core::inexact);
    if (exactInteger != !mlx::core::issubdtype(lhs->dtype(), mlx::core::inexact) ||
        exactInteger != !mlx::core::issubdtype(rhs->dtype(), mlx::core::inexact)) {
        ctx.error_message =
            "phydrax-metal: dot_general mixing integer and floating-point operands is not "
            "supported";
        return false;
    }

    // MLX TF32 is disabled in the locked dependency, so DEFAULT/HIGH/HIGHEST
    // all retain every float32 input bit. Half inputs use a float32 contraction
    // for a float32 result or HIGH/HIGHEST precision; never round the result
    // through the half storage type first. Explicit algorithms have already
    // been admitted by the parser.
    auto lhsValue = *lhs;
    auto rhsValue = *rhs;
    if (!exactInteger) {
        bool promoteHalf = *resultDtype == mlx::core::float32;
        if (auto precision = op->getAttrOfType<mlir::ArrayAttr>("precision_config")) {
            for (mlir::Attribute attribute : precision) {
                auto value = mlir::cast<mlir::stablehlo::PrecisionAttr>(attribute).getValue();
                promoteHalf |= value != mlir::stablehlo::Precision::DEFAULT;
            }
        }
        if (promoteHalf) {
            if (lhsValue.dtype() == mlx::core::float16 ||
                lhsValue.dtype() == mlx::core::bfloat16)
                lhsValue = mlx::core::astype(lhsValue, mlx::core::float32);
            if (rhsValue.dtype() == mlx::core::float16 ||
                rhsValue.dtype() == mlx::core::bfloat16)
                rhsValue = mlx::core::astype(rhsValue, mlx::core::float32);
        }
    }

    // Degenerate case: a rank-0 operand. A scalar has no dimensions to batch or
    // contract over, and StableHLO requires the batch/contract dim lists of the
    // two operands to have equal length -- so if either operand is rank-0 there
    // are no batch and no contracting dims at all, and the op reduces to a pure
    // outer product. With one scalar that is exactly a broadcasting multiply
    // (the non-scalar operand's free dims, in order, are the output dims). This
    // also avoids the einsum path, whose subscript would be e.g. ",->" for two
    // scalars -- a string MLX's einsum parser cannot handle.
    if (lhsRank == 0 || rhsRank == 0) {
        auto accumulate = *resultDtype == mlx::core::bool_ ? mlx::core::int32 :
                          (exactInteger ? *resultDtype :
                           mlx::core::promote_types(lhsValue.dtype(), rhsValue.dtype()));
        auto result = mlx::core::multiply(mlx::core::astype(lhsValue, accumulate),
                                         mlx::core::astype(rhsValue, accumulate));
        values.emplace(ToKey(op->getResult(0)), mlx::core::astype(result, *resultDtype));
        return true;
    }

    if (!exactInteger) {
        std::string subscript = BuildEinsumSubscript(lhsRank, rhsRank, lhsBatchDims, rhsBatchDims,
                                                     lhsContractDims, rhsContractDims);
        MPS_LOG_DEBUG("dot_general einsum: %s\n", subscript.c_str());
        auto result = mlx::core::einsum(subscript, {lhsValue, rhsValue});
        if (result.dtype() != *resultDtype)
            result = mlx::core::astype(result, *resultDtype);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Exact integer contraction: [batch, lhsFree, contract] x [batch, contract,
    // rhsFree] as a broadcast product summed over the contracting axis, in the
    // result integer type (or int32 for predicates, then compared to zero).
    auto lhsVal = std::move(lhsValue);
    auto rhsVal = std::move(rhsValue);

    // Standard path: transpose -> reshape -> matmul -> reshape
    std::unordered_set<int> lhsContractSet(lhsContractDims.begin(), lhsContractDims.end());
    std::unordered_set<int> rhsContractSet(rhsContractDims.begin(), rhsContractDims.end());
    std::unordered_set<int> lhsBatchSet(lhsBatchDims.begin(), lhsBatchDims.end());
    std::unordered_set<int> rhsBatchSet(rhsBatchDims.begin(), rhsBatchDims.end());

    std::vector<int> lhsFreeDims;
    std::vector<int> rhsFreeDims;
    for (int i = 0; i < lhsRank; ++i) {
        if (lhsBatchSet.count(i) == 0 && lhsContractSet.count(i) == 0) {
            lhsFreeDims.push_back(i);
        }
    }
    for (int i = 0; i < rhsRank; ++i) {
        if (rhsBatchSet.count(i) == 0 && rhsContractSet.count(i) == 0) {
            rhsFreeDims.push_back(i);
        }
    }

    std::vector<int> lhsPerm;
    for (int64_t d : lhsBatchDims)
        lhsPerm.push_back(static_cast<int>(d));
    for (int d : lhsFreeDims)
        lhsPerm.push_back(d);
    for (int64_t d : lhsContractDims)
        lhsPerm.push_back(static_cast<int>(d));

    std::vector<int> rhsPerm;
    for (int64_t d : rhsBatchDims)
        rhsPerm.push_back(static_cast<int>(d));
    for (int64_t d : rhsContractDims)
        rhsPerm.push_back(static_cast<int>(d));
    for (int d : rhsFreeDims)
        rhsPerm.push_back(d);

    auto accumulate = *resultDtype == mlx::core::bool_ ? mlx::core::int32 : *resultDtype;
    auto lhsT = mlx::core::transpose(mlx::core::astype(lhsVal, accumulate), lhsPerm);
    auto rhsT = mlx::core::transpose(mlx::core::astype(rhsVal, accumulate), rhsPerm);

    int numBatch = static_cast<int>(lhsBatchDims.size());
    int numLhsFree = static_cast<int>(lhsFreeDims.size());
    int numContract = static_cast<int>(lhsContractDims.size());

    int64_t batchSize = 1;
    for (int i = 0; i < numBatch; ++i) {
        batchSize *= lhsT.shape(i);
    }

    int64_t lhsFreeSize = 1;
    for (int i = numBatch; i < numBatch + numLhsFree; ++i) {
        lhsFreeSize *= lhsT.shape(i);
    }

    int64_t contractSize = 1;
    for (int i = numBatch + numLhsFree; i < static_cast<int>(lhsT.ndim()); ++i) {
        contractSize *= lhsT.shape(i);
    }

    int64_t rhsFreeSize = 1;
    for (int i = numBatch + numContract; i < static_cast<int>(rhsT.ndim()); ++i) {
        rhsFreeSize *= rhsT.shape(i);
    }

    std::vector<int> batchShape;
    batchShape.reserve(numBatch);
    for (int i = 0; i < numBatch; ++i) {
        batchShape.push_back(lhsT.shape(i));
    }
    std::vector<int> lhsFreeShape;
    lhsFreeShape.reserve(numLhsFree);
    for (int i = numBatch; i < numBatch + numLhsFree; ++i) {
        lhsFreeShape.push_back(lhsT.shape(i));
    }
    std::vector<int> rhsFreeShape;
    rhsFreeShape.reserve(static_cast<int>(rhsT.ndim()) - numBatch - numContract);
    for (int i = numBatch + numContract; i < static_cast<int>(rhsT.ndim()); ++i) {
        rhsFreeShape.push_back(rhsT.shape(i));
    }

    if (batchSize * lhsFreeSize * contractSize * rhsFreeSize > kMaxIntegerDotElements) {
        ctx.error_message =
            "phydrax-metal: integer dot_general with " +
            std::to_string(batchSize * lhsFreeSize * contractSize * rhsFreeSize) +
            " product elements is not supported (exact integer contraction limit " +
            std::to_string(kMaxIntegerDotElements) + ")";
        return false;
    }

    mlx::core::Shape lhsShape4d = {static_cast<int>(batchSize), static_cast<int>(lhsFreeSize),
                                   static_cast<int>(contractSize), 1};
    mlx::core::Shape rhsShape4d = {static_cast<int>(batchSize), 1,
                                   static_cast<int>(contractSize),
                                   static_cast<int>(rhsFreeSize)};

    auto lhs4d = mlx::core::reshape(lhsT, lhsShape4d);
    auto rhs4d = mlx::core::reshape(rhsT, rhsShape4d);

    auto result3d = mlx::core::sum(mlx::core::multiply(lhs4d, rhs4d), 2, /*keepdims=*/false);

    mlx::core::Shape finalShape;
    for (int s : batchShape)
        finalShape.push_back(s);
    for (int s : lhsFreeShape)
        finalShape.push_back(s);
    for (int s : rhsFreeShape)
        finalShape.push_back(s);

    auto result = mlx::core::reshape(result3d, finalShape);
    if (*resultDtype == mlx::core::bool_)
        result = mlx::core::not_equal(result, mlx::core::array(0, mlx::core::int32));
    else if (result.dtype() != *resultDtype)
        result = mlx::core::astype(result, *resultDtype);
    values.emplace(ToKey(op->getResult(0)), std::move(result));
    return true;
}

// Handler for stablehlo.convolution
bool HandleConvolution(mlir::Operation* op, ValueMap& values,
                       std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    auto convOp = CastOp<mlir::stablehlo::ConvolutionOp>(op, "stablehlo.convolution");
    if (!convOp)
        return false;

    auto* input = RequireValue(values, op->getOperand(0), "stablehlo.convolution");
    auto* kernel = RequireValue(values, op->getOperand(1), "stablehlo.convolution");
    if (!input || !kernel)
        return false;

    auto dimNumbers = convOp.getDimensionNumbers();

    int64_t inputBatchDim = dimNumbers.getInputBatchDimension();
    int64_t inputFeatureDim = dimNumbers.getInputFeatureDimension();
    auto inputSpatialDims = dimNumbers.getInputSpatialDimensions();

    int64_t kernelInputFeatureDim = dimNumbers.getKernelInputFeatureDimension();
    int64_t kernelOutputFeatureDim = dimNumbers.getKernelOutputFeatureDimension();
    auto kernelSpatialDims = dimNumbers.getKernelSpatialDimensions();

    int64_t outputBatchDim = dimNumbers.getOutputBatchDimension();
    int64_t outputFeatureDim = dimNumbers.getOutputFeatureDimension();
    auto outputSpatialDims = dimNumbers.getOutputSpatialDimensions();

    int numSpatialDims = static_cast<int>(inputSpatialDims.size());

    // Build input permutation to [N, spatial..., C_in] format
    std::vector<int> inputPerm(input->ndim());
    inputPerm[0] = static_cast<int>(inputBatchDim);
    for (int i = 0; i < numSpatialDims; ++i) {
        inputPerm[1 + i] = static_cast<int>(inputSpatialDims[i]);
    }
    inputPerm[1 + numSpatialDims] = static_cast<int>(inputFeatureDim);

    // Build kernel permutation to [C_out, spatial..., C_in] format
    std::vector<int> kernelPerm(kernel->ndim());
    kernelPerm[0] = static_cast<int>(kernelOutputFeatureDim);
    for (int i = 0; i < numSpatialDims; ++i) {
        kernelPerm[1 + i] = static_cast<int>(kernelSpatialDims[i]);
    }
    kernelPerm[1 + numSpatialDims] = static_cast<int>(kernelInputFeatureDim);

    auto inputT =
        IsIdentityPermutation(inputPerm) ? *input : mlx::core::transpose(*input, inputPerm);
    auto kernelT =
        IsIdentityPermutation(kernelPerm) ? *kernel : mlx::core::transpose(*kernel, kernelPerm);

    // Extract strides
    std::vector<int> strides;
    if (auto stridesAttr = convOp.getWindowStrides()) {
        strides = ToIntVec(*stridesAttr);
    } else {
        strides.resize(numSpatialDims, 1);
    }

    // Extract padding
    std::vector<int> paddingLow(numSpatialDims, 0);
    std::vector<int> paddingHigh(numSpatialDims, 0);
    if (auto paddingAttr = convOp.getPadding()) {
        auto paddingValues = paddingAttr->getValues<int64_t>();
        auto it = paddingValues.begin();
        for (int i = 0; i < numSpatialDims; ++i) {
            paddingLow[i] = static_cast<int>(*it++);
            paddingHigh[i] = static_cast<int>(*it++);
        }
    }

    // Extract dilation
    std::vector<int> kernelDilation;
    if (auto dilationAttr = convOp.getRhsDilation()) {
        kernelDilation = ToIntVec(*dilationAttr);
    } else {
        kernelDilation.resize(numSpatialDims, 1);
    }

    std::vector<int> inputDilation;
    if (auto dilationAttr = convOp.getLhsDilation()) {
        inputDilation = ToIntVec(*dilationAttr);
    } else {
        inputDilation.resize(numSpatialDims, 1);
    }

    auto featureGroupCount = static_cast<int>(convOp.getFeatureGroupCount());
    auto batchGroupCount = static_cast<int>(convOp.getBatchGroupCount());

    if (batchGroupCount > 1) {
        // batch_group_count > 1 arises in JAX's weight-gradient VJP for vmapped
        // convolutions. G groups each own Nper input samples and Oper output
        // filters. The naive loop (G iterations × one conv each) is O(G) MLX
        // dispatches; with G = batch_size this is prohibitively slow.
        //
        // Instead, fold the G axis into the channel axis of the input:
        //   input  (G*Nper, *spatial, C_in)  ->  (Nper, *spatial, G*C_in)
        //   kernel (G*Oper, *spatial_k, C_in) stays as-is
        // then call conv_general once with feature_group_count=G. Group g
        // sees input channels [g*C_in, (g+1)*C_in) and produces output
        // channels [g*Oper, (g+1)*Oper), which matches the concatenated
        // result of the original loop.
        // The fold below repurposes conv_general's feature_group_count to carry
        // the batch groups, so it cannot also express a real feature_group_count.
        // XLA forbids both being >1 in one convolution, so this is unreachable in
        // practice; guard anyway to fail loudly rather than silently miscompute.
        if (featureGroupCount > 1) {
            MPS_LOG_ERROR(
                "stablehlo.convolution: batch_group_count %d and feature_group_count %d "
                "cannot both be > 1\n",
                batchGroupCount, featureGroupCount);
            return false;
        }
        int N = inputT.shape(0);
        int O = kernelT.shape(0);
        int C_in = inputT.shape(static_cast<int>(inputT.ndim()) - 1);
        if (N % batchGroupCount != 0 || O % batchGroupCount != 0) {
            MPS_LOG_ERROR(
                "stablehlo.convolution: batch_group_count %d does not divide "
                "input batch %d or kernel output features %d\n",
                batchGroupCount, N, O);
            return false;
        }
        int G = batchGroupCount;
        int Nper = N / G;

        // Reshape (G*Nper, *spatial, C_in) -> (Nper, *spatial, G*C_in):
        //   step 1: reshape -> (G, Nper, *spatial, C_in)
        //   step 2: transpose -> (Nper, *spatial, G, C_in)
        //   step 3: reshape -> (Nper, *spatial, G*C_in)
        {
            mlx::core::Shape s1;
            s1.push_back(G);
            s1.push_back(Nper);
            for (int i = 1; i < static_cast<int>(inputT.ndim()); ++i)
                s1.push_back(inputT.shape(i));
            auto t1 = mlx::core::reshape(inputT, s1);

            int nd = static_cast<int>(t1.ndim());  // numSpatialDims + 3
            std::vector<int> perm;
            perm.push_back(1);  // Nper  -> axis 0
            for (int i = 2; i < nd - 1; ++i)
                perm.push_back(i);   // spatial
            perm.push_back(0);       // G     -> axis numSpatialDims+1
            perm.push_back(nd - 1);  // C_in  -> axis numSpatialDims+2
            auto t2 = mlx::core::transpose(t1, perm);

            mlx::core::Shape s3;
            for (int i = 0; i < static_cast<int>(t2.ndim()) - 2; ++i)
                s3.push_back(t2.shape(i));
            s3.push_back(G * C_in);
            inputT = mlx::core::reshape(t2, s3);
        }

        // Apply input-dilation materialization for negative-padded axes
        // (identical logic to the batchGroupCount==1 path below).
        for (int i = 0; i < numSpatialDims; ++i) {
            if (inputDilation[i] <= 1)
                continue;
            if (paddingLow[i] >= 0 && paddingHigh[i] >= 0)
                continue;
            int axis = 1 + i;
            int L = inputT.shape(axis);
            if (L <= 0)
                continue;
            auto dilatedShape = inputT.shape();
            dilatedShape[axis] = (L - 1) * inputDilation[i] + 1;
            mlx::core::Shape starts(inputT.ndim(), 0);
            mlx::core::Shape striding(inputT.ndim(), 1);
            striding[axis] = inputDilation[i];
            auto zeros = mlx::core::zeros(dilatedShape, inputT.dtype());
            inputT = mlx::core::slice_update(zeros, inputT, starts, dilatedShape, striding);
            inputDilation[i] = 1;
        }
        std::vector<int> perGroupDilation = inputDilation;
        for (int i = 0; i < numSpatialDims; ++i) {
            if (paddingLow[i] < 0 || paddingHigh[i] < 0)
                perGroupDilation[i] = 1;
        }

        // Single conv: (Nper, *spatial, G*C_in) x (G*Oper, *spatial_k, C_in)
        // with feature_group_count=G -> (Nper, *spatial_out, G*Oper)
        auto groupOut = mlx::core::conv_general(inputT, kernelT, strides, paddingLow, paddingHigh,
                                                kernelDilation, perGroupDilation, G, false);

        std::vector<int> outPerm(groupOut.ndim());
        outPerm[static_cast<int>(outputBatchDim)] = 0;
        for (int i = 0; i < numSpatialDims; ++i)
            outPerm[static_cast<int>(outputSpatialDims[i])] = 1 + i;
        outPerm[static_cast<int>(outputFeatureDim)] = 1 + numSpatialDims;
        auto result =
            IsIdentityPermutation(outPerm) ? groupOut : mlx::core::transpose(groupOut, outPerm);
        values.emplace(ToKey(op->getResult(0)), std::move(result));
        return true;
    }

    // Weight gradient VJP optimization
    bool useWeightGradVJP = false;
    mlx::core::array vjpResult = mlx::core::array(0);

    if (numSpatialDims == 2 && inputT.ndim() == 4 && kernelT.ndim() == 4) {
        int H_in = inputT.shape(1);
        int W_in = inputT.shape(2);
        int kH = kernelT.shape(1);
        int kW = kernelT.shape(2);
        int out_H = H_in + paddingLow[0] + paddingHigh[0] - (kH - 1) * kernelDilation[0];
        int out_W = W_in + paddingLow[1] + paddingHigh[1] - (kW - 1) * kernelDilation[1];

        if (out_H > 0 && out_W > 0 && kH >= 2 * out_H && kW >= 2 * out_W && strides[0] == 1 &&
            strides[1] == 1 && inputDilation[0] == 1 && inputDilation[1] == 1 &&
            featureGroupCount == 1) {
            useWeightGradVJP = true;

            auto& origAct = *input;
            auto& origGrad = *kernel;

            int Ci_true = origAct.shape(static_cast<int>(inputBatchDim));
            int Co_true = origGrad.shape(static_cast<int>(kernelOutputFeatureDim));

            std::vector<int> actPerm = {static_cast<int>(inputFeatureDim)};
            for (int i = 0; i < numSpatialDims; ++i)
                actPerm.push_back(static_cast<int>(inputSpatialDims[i]));
            actPerm.push_back(static_cast<int>(inputBatchDim));

            std::vector<int> gradPerm = {static_cast<int>(kernelInputFeatureDim)};
            for (int i = 0; i < numSpatialDims; ++i)
                gradPerm.push_back(static_cast<int>(kernelSpatialDims[i]));
            gradPerm.push_back(static_cast<int>(kernelOutputFeatureDim));

            auto actStd = mlx::core::transpose(origAct, actPerm);
            auto gradStd = mlx::core::transpose(origGrad, gradPerm);

            int origKH = out_H;
            int origKW = out_W;
            std::vector<int> fwdStride = {kernelDilation[0], kernelDilation[1]};
            std::vector<int> fwdPadLo = {paddingLow[0], paddingLow[1]};
            std::vector<int> fwdPadHi = {paddingHigh[0], paddingHigh[1]};

            auto dummyW = mlx::core::zeros({Co_true, origKH, origKW, Ci_true}, actStd.dtype());

            auto vjpFn =
                [actStd, fwdStride, fwdPadLo, fwdPadHi](
                    const std::vector<mlx::core::array>& primals) -> std::vector<mlx::core::array> {
                return {mlx::core::conv_general(actStd, primals[0], fwdStride, fwdPadLo, fwdPadHi,
                                                std::vector<int>{}, std::vector<int>{}, 1, false)};
            };

            auto [fwdOutputs, vjps] = mlx::core::vjp(vjpFn, {dummyW}, {gradStd});
            auto dW = vjps[0];

            vjpResult = mlx::core::transpose(dW, {3, 1, 2, 0});
        }
    }

    mlx::core::array convResult = mlx::core::array(0);
    if (useWeightGradVJP) {
        convResult = vjpResult;
    } else {
        // StableHLO conv semantics dilate the LHS first, then apply padding.
        // MLX's conv_general slices the input for negative padding before
        // applying input_dilation (mlx/ops.cpp:conv_general). The two orders
        // agree everywhere except on axes where input_dilation > 1 and the
        // padding is negative; on those axes, materialize the dilated input
        // here and pass input_dilation=1 so MLX applies the negative padding
        // to the already-dilated tensor.
        for (int i = 0; i < numSpatialDims; ++i) {
            if (inputDilation[i] <= 1)
                continue;
            if (paddingLow[i] >= 0 && paddingHigh[i] >= 0)
                continue;
            int axis = 1 + i;  // inputT layout is [N, spatial..., C_in].
            int L = inputT.shape(axis);
            if (L <= 0)
                continue;
            auto dilatedShape = inputT.shape();
            dilatedShape[axis] = (L - 1) * inputDilation[i] + 1;
            mlx::core::Shape starts(inputT.ndim(), 0);
            mlx::core::Shape striding(inputT.ndim(), 1);
            striding[axis] = inputDilation[i];
            auto zeros = mlx::core::zeros(dilatedShape, inputT.dtype());
            inputT = mlx::core::slice_update(zeros, inputT, starts, dilatedShape, striding);
            inputDilation[i] = 1;
        }
        convResult =
            mlx::core::conv_general(inputT, kernelT, strides, paddingLow, paddingHigh,
                                    kernelDilation, inputDilation, featureGroupCount, false);
    }

    // Build output permutation
    std::vector<int> outputPerm(convResult.ndim());
    outputPerm[outputBatchDim] = 0;
    for (int i = 0; i < numSpatialDims; ++i) {
        outputPerm[outputSpatialDims[i]] = 1 + i;
    }
    outputPerm[outputFeatureDim] = 1 + numSpatialDims;

    auto result = IsIdentityPermutation(outputPerm) ? convResult
                                                    : mlx::core::transpose(convResult, outputPerm);
    values.emplace(ToKey(op->getResult(0)), std::move(result));
    return true;
}

// Slice rows [r0, r1) and columns [c0, c1) of the trailing matrix dimensions.
mlx::core::array SliceMatrix(const mlx::core::array& a, int r0, int r1, int c0, int c1) {
    const int rank = static_cast<int>(a.ndim());
    mlx::core::Shape start(rank, 0);
    mlx::core::Shape stop = a.shape();
    start[rank - 2] = r0;
    stop[rank - 2] = r1;
    start[rank - 1] = c0;
    stop[rank - 1] = c1;
    return mlx::core::slice(a, start, stop);
}

mlx::core::array SwapLast2(const mlx::core::array& a) {
    std::vector<int> perm(a.ndim());
    std::iota(perm.begin(), perm.end(), 0);
    std::swap(perm[perm.size() - 2], perm[perm.size() - 1]);
    return mlx::core::transpose(a, perm);
}

// Solve M X = B on the GPU by forward (lower) or backward (upper) substitution,
// reading only the selected triangle of M. Row i is
//   x_i = (b_i - M[i, solved] @ X[solved]) / M[i, i]
// with IEEE division (a zero pivot yields inf/nan, which callers' nonfinite
// checks observe), and no division when the diagonal is implicitly one.
mlx::core::array SubstitutionSolve(const mlx::core::array& m, const mlx::core::array& b,
                                   bool lower, bool unitDiagonal) {
    const int n = m.shape(-1);
    const int k = b.shape(-1);
    std::vector<mlx::core::array> rows;
    rows.reserve(n);
    std::optional<mlx::core::array> solved;  // rows solved so far, in solve order
    for (int step = 0; step < n; ++step) {
        const int i = lower ? step : n - 1 - step;
        auto row = SliceMatrix(b, i, i + 1, 0, k);
        if (solved) {
            auto coefficients = lower ? SliceMatrix(m, i, i + 1, 0, i)
                                      : SliceMatrix(m, i, i + 1, i + 1, n);
            row = mlx::core::subtract(row, mlx::core::matmul(coefficients, *solved));
        }
        if (!unitDiagonal)
            row = mlx::core::divide(row, SliceMatrix(m, i, i + 1, i, i + 1));
        rows.push_back(row);
        if (!solved)
            solved = row;
        else
            solved = lower ? mlx::core::concatenate({*solved, row}, -2)
                           : mlx::core::concatenate({row, *solved}, -2);
    }
    if (!solved)
        return b;
    return *solved;
}

// Handler for stablehlo.triangular_solve (left/right side, lower/upper,
// no transpose/transpose/adjoint, unit diagonal), batched over leading dims.
bool HandleTriangularSolve(mlir::Operation* op, ValueMap& values,
                           std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    auto triSolveOp = CastOp<mlir::stablehlo::TriangularSolveOp>(op, "stablehlo.triangular_solve");
    if (!triSolveOp)
        return false;

    auto* a_ptr = RequireValue(values, triSolveOp.getA(), "stablehlo.triangular_solve");
    auto* b_ptr = RequireValue(values, triSolveOp.getB(), "stablehlo.triangular_solve");
    if (!a_ptr || !b_ptr)
        return false;

    // op(A) for the requested transpose; transposing swaps the triangle used.
    auto m = *a_ptr;
    bool lower = triSolveOp.getLower();
    switch (triSolveOp.getTransposeA()) {
        case mlir::stablehlo::Transpose::NO_TRANSPOSE:
        case mlir::stablehlo::Transpose::TRANSPOSE_INVALID:
            break;
        case mlir::stablehlo::Transpose::TRANSPOSE:
            m = SwapLast2(m);
            lower = !lower;
            break;
        case mlir::stablehlo::Transpose::ADJOINT:
            m = mlx::core::conjugate(SwapLast2(m));
            lower = !lower;
            break;
    }

    const bool unitDiagonal = triSolveOp.getUnitDiagonal();
    mlx::core::array result = *b_ptr;
    if (triSolveOp.getLeftSide()) {
        // op(A) X = B.
        result = SubstitutionSolve(m, *b_ptr, lower, unitDiagonal);
    } else {
        // X op(A) = B  <=>  op(A)^T X^T = B^T.
        result = SwapLast2(
            SubstitutionSolve(SwapLast2(m), SwapLast2(*b_ptr), !lower, unitDiagonal));
    }
    values.emplace(ToKey(op->getResult(0)), std::move(result));
    return true;
}

}  // namespace

void RegisterLinalgHandlers(std::unordered_map<std::string, OpHandler>& handlers) {
    handlers.insert({"stablehlo.dot_general", HandleDotGeneral});
    handlers.insert({"stablehlo.convolution", HandleConvolution});
    handlers.insert({"stablehlo.triangular_solve", HandleTriangularSolve});
}

}  // namespace jax_mps

