// Reduction op handlers (reduce, reduce_window, select_and_scatter).

#include <mlx/fast.h>

#include <algorithm>
#include <functional>
#include <limits>
#include <sstream>
#include <tuple>

#include "pjrt_plugin/ops/handler_utils.h"
#include "stablehlo/dialect/StablehloOps.h"

namespace jax_mps {

namespace {

// Only admit the actual binary reducer, including its operand/return wiring.
enum class ReduceType { Sum, Max, Min, Prod, And, Or, Unknown };

ReduceType DetectReduceType(mlir::Region& body) {
    if (!body.hasOneBlock())
        return ReduceType::Unknown;
    auto& block = body.front();
    if (block.getNumArguments() != 2 || block.getOperations().size() != 2)
        return ReduceType::Unknown;
    auto& binary = block.front();
    auto& ret = block.back();
    if (binary.getNumOperands() != 2 || binary.getNumResults() != 1 ||
        ret.getName().getStringRef() != "stablehlo.return" || ret.getNumOperands() != 1 ||
        ret.getOperand(0) != binary.getResult(0) ||
        !((binary.getOperand(0) == block.getArgument(0) &&
           binary.getOperand(1) == block.getArgument(1)) ||
          (binary.getOperand(1) == block.getArgument(0) &&
           binary.getOperand(0) == block.getArgument(1))))
        return ReduceType::Unknown;
    auto name = binary.getName().getStringRef();
    if (name == "stablehlo.add") return ReduceType::Sum;
    if (name == "stablehlo.maximum") return ReduceType::Max;
    if (name == "stablehlo.minimum") return ReduceType::Min;
    if (name == "stablehlo.multiply") return ReduceType::Prod;
    if (name == "stablehlo.and") return ReduceType::And;
    if (name == "stablehlo.or") return ReduceType::Or;
    return ReduceType::Unknown;
}

// Safe math preserves the declared fold order and NaN/zero rules. Explicit
// compensated scientific loops remain their own operations, not reducer policy.
// One thread owns one output; long axes are serial with O(output) workspace.
const char* kReductionHeader = R"(
template <typename T> T hlo_max(T a, T b) { return a > b ? a : b; }
template <typename T> T hlo_min(T a, T b) { return a < b ? a : b; }
template <> float hlo_max(float a, float b) {
    if (isnan(a)) return a;
    if (isnan(b)) return b;
    if (a == 0.0f && b == 0.0f)
        return as_type<float>(as_type<uint>(a) & as_type<uint>(b));
    return a > b ? a : b;
}
template <> float hlo_min(float a, float b) {
    if (isnan(a)) return a;
    if (isnan(b)) return b;
    if (a == 0.0f && b == 0.0f)
        return as_type<float>(as_type<uint>(a) | as_type<uint>(b));
    return a < b ? a : b;
}
template <> half hlo_max(half a, half b) { return half(hlo_max(float(a), float(b))); }
template <> half hlo_min(half a, half b) { return half(hlo_min(float(a), float(b))); }
)";

std::string Combine(ReduceType type, const std::string& a, const std::string& b) {
    switch (type) {
        case ReduceType::Sum: return "(" + a + " + " + b + ")";
        case ReduceType::Prod: return "(" + a + " * " + b + ")";
        case ReduceType::Max: return "hlo_max(" + a + ", " + b + ")";
        case ReduceType::Min: return "hlo_min(" + a + ", " + b + ")";
        case ReduceType::And: return "(" + a + " & " + b + ")";
        case ReduceType::Or: return "(" + a + " | " + b + ")";
        default: throw std::runtime_error("unsupported StableHLO reducer body");
    }
}

int64_t ShapeSize(const mlx::core::Shape& shape) {
    int64_t size = 1;
    for (int dim : shape) {
        if (dim < 0 || (dim && size > std::numeric_limits<int32_t>::max() / dim))
            throw std::runtime_error("reduction shape exceeds Metal dispatch capacity");
        size *= dim;
    }
    return size;
}

std::vector<mlx::core::array> ReductionKernel(
    const std::string& source, const std::vector<mlx::core::array>& inputs,
    const std::vector<std::string>& names, const std::vector<std::string>& outputNames,
    const mlx::core::Shape& shape, const std::vector<mlx::core::Dtype>& dtypes,
    std::vector<std::pair<std::string, mlx::core::fast::TemplateArg>> templates) {
    int count = static_cast<int>(ShapeSize(shape));
    std::vector<mlx::core::Shape> shapes(dtypes.size(), mlx::core::Shape{count});
    auto kernel = mlx::core::fast::metal_kernel(
        "phydrax_reduce_" + std::to_string(std::hash<std::string>{}(source)), names,
        outputNames, source, kReductionHeader, true, false, {});
    auto result = kernel(inputs, shapes, dtypes, {count, 1, 1}, {std::min(count, 256), 1, 1},
                         std::move(templates), std::nullopt, false, {});
    for (auto& output : result)
        output = mlx::core::reshape(output, shape);
    return result;
}

// Lower a two-input scalar body verbatim instead of guessing argmax from one
// comparison. This preserves its NaN policy, supplied index values, tie selects,
// initial pair, and declared signed/unsigned index width. Unknown bodies fail.
std::string PairReducer(mlir::Region& body) {
    if (!body.hasOneBlock() || body.front().getNumArguments() != 4)
        throw std::runtime_error("unsupported paired reduction body");
    auto& block = body.front();
    std::unordered_map<void*, std::string> expr;
    const char* args[] = {"a", "ai", "b", "bi"};
    for (int i = 0; i < 4; ++i)
        expr.emplace(ToKey(block.getArgument(i)), args[i]);
    std::ostringstream code;
    int number = 0;
    for (auto& operation : block) {
        auto operand = [&](unsigned i) { return expr.at(ToKey(operation.getOperand(i))); };
        auto name = operation.getName().getStringRef();
        if (name == "stablehlo.return") {
            if (operation.getNumOperands() != 2)
                throw std::runtime_error("paired reduction must return two scalars");
            code << "T next_a = " << operand(0) << "; I next_i = " << operand(1)
                 << "; a = next_a; ai = next_i;\n";
            return code.str();
        }
        if (operation.getNumResults() != 1)
            throw std::runtime_error("unsupported paired reduction operation");
        std::string value;
        if (auto cmp = mlir::dyn_cast<mlir::stablehlo::CompareOp>(operation)) {
            if (cmp.getCompareType() &&
                *cmp.getCompareType() == mlir::stablehlo::ComparisonType::TOTALORDER)
                throw std::runtime_error("TOTALORDER paired reduction is unsupported");
            using D = mlir::stablehlo::ComparisonDirection;
            std::string symbol;
            switch (cmp.getComparisonDirection()) {
                case D::EQ: symbol = "=="; break;
                case D::NE: symbol = "!="; break;
                case D::GE: symbol = ">="; break;
                case D::GT: symbol = ">"; break;
                case D::LE: symbol = "<="; break;
                case D::LT: symbol = "<"; break;
            }
            value = "(" + operand(0) + symbol + operand(1) + ")";
        } else if (name == "stablehlo.select") {
            value = "(" + operand(0) + " ? " + operand(1) + " : " + operand(2) + ")";
        } else if (name == "stablehlo.or" || name == "stablehlo.and" ||
                   name == "stablehlo.minimum" || name == "stablehlo.maximum") {
            auto type = name == "stablehlo.or" ? ReduceType::Or :
                        name == "stablehlo.and" ? ReduceType::And :
                        name == "stablehlo.minimum" ? ReduceType::Min : ReduceType::Max;
            value = Combine(type, operand(0), operand(1));
        } else if (name == "stablehlo.not") {
            auto resultType = mlir::cast<mlir::RankedTensorType>(operation.getResult(0).getType());
            value = std::string(resultType.getElementType().isInteger(1) ? "(!" : "(~") +
                    operand(0) + ")";
        } else {
            throw std::runtime_error("unsupported paired reduction operation: " + name.str());
        }
        auto var = "v" + std::to_string(number++);
        auto resultType = mlir::cast<mlir::RankedTensorType>(operation.getResult(0).getType());
        auto valueType = mlir::cast<mlir::RankedTensorType>(block.getArgument(0).getType());
        auto indexType = mlir::cast<mlir::RankedTensorType>(block.getArgument(1).getType());
        auto element = resultType.getElementType();
        std::string scalarType;
        if (element.isInteger(1)) scalarType = "bool";
        else if (element == valueType.getElementType()) scalarType = "T";
        else if (element == indexType.getElementType()) scalarType = "I";
        else throw std::runtime_error("unsupported paired reduction scalar type");
        code << scalarType << " " << var << " = " << value << ";\n";
        expr.emplace(ToKey(operation.getResult(0)), var);
    }
    throw std::runtime_error("paired reduction has no return");
}

// Decode output/reduction coordinates without allocating index tensors.
std::string ReductionOffsets(const mlx::core::Shape& shape, const std::vector<int>& axes,
                             int64_t& reducedSize, mlx::core::Shape& outputShape) {
    std::vector<int64_t> strides(shape.size(), 1);
    for (int i = static_cast<int>(shape.size()) - 2; i >= 0; --i)
        strides[i] = strides[i + 1] * shape[i + 1];
    reducedSize = 1;
    for (int axis : axes) reducedSize *= shape[axis];
    for (size_t i = 0; i < shape.size(); ++i)
        if (std::find(axes.begin(), axes.end(), i) == axes.end())
            outputShape.push_back(shape[i]);
    std::ostringstream code;
    code << "ulong base = 0, q = thread_position_in_grid.x;\n";
    for (int i = static_cast<int>(shape.size()) - 1; i >= 0; --i) {
        if (std::find(axes.begin(), axes.end(), i) != axes.end()) continue;
        code << "base += (q % " << std::max(shape[i], 1) << "ul) * " << strides[i]
             << "ul; q /= " << std::max(shape[i], 1) << "ul;\n";
    }
    code << "for (ulong r = 0; r < " << reducedSize << "ul; ++r) {\n"
         << "ulong offset = base, k = r;\n";
    for (auto it = axes.rbegin(); it != axes.rend(); ++it) {
        int i = *it;
        code << "offset += (k % " << std::max(shape[i], 1) << "ul) * " << strides[i]
             << "ul; k /= " << std::max(shape[i], 1) << "ul;\n";
    }
    return code.str();
}

bool HandleReduce(mlir::Operation* op, ValueMap& values, std::vector<mlx::core::array>&,
                  ExecContext&) {
    auto reduce = CastOp<mlir::stablehlo::ReduceOp>(op, "stablehlo.reduce");
    if (!reduce) return false;
    size_t count = reduce.getInputs().size();
    if (count != 1 && count != 2)
        throw std::runtime_error("stablehlo.reduce supports one binary or two paired inputs");
    auto axes = ToIntVec(reduce.getDimensions());
    std::sort(axes.begin(), axes.end());
    auto* input = RequireValue(values, reduce.getInputs()[0], "stablehlo.reduce");
    auto* init = RequireValue(values, reduce.getInitValues()[0], "stablehlo.reduce");
    if (!input || !init) return false;
    ShapeSize(input->shape());
    mlx::core::Shape outputShape;
    int64_t reducedSize;
    auto offsets = ReductionOffsets(input->shape(), axes, reducedSize, outputShape);
    if (count == 2) {
        auto body = PairReducer(reduce.getBody());
        auto* indices = RequireValue(values, reduce.getInputs()[1], "stablehlo.reduce");
        auto* initialIndex = RequireValue(values, reduce.getInitValues()[1], "stablehlo.reduce");
        if (!indices || !initialIndex) return false;
        auto type = mlir::cast<mlir::RankedTensorType>(op->getResult(1).getType());
        auto indexDtype = MlirTypeToMlxDtype(type.getElementType());
        if (input->dtype() == mlx::core::complex64)
            throw std::runtime_error("complex paired reduction is unsupported");
        if (!ShapeSize(outputShape) || !reducedSize) {
            values.emplace(ToKey(op->getResult(0)), mlx::core::full(outputShape, *init, input->dtype()));
            values.emplace(ToKey(op->getResult(1)), mlx::core::full(outputShape, *initialIndex, indexDtype));
            return true;
        }
        auto source = "T a = initial[0]; I ai = initial_index[0];\n" + offsets +
                      "T b = input[offset]; I bi = indices[offset];\n" + body +
                      "}\nvalue[thread_position_in_grid.x] = a;\n"
                      "index[thread_position_in_grid.x] = ai;\n";
        auto result = ReductionKernel(source,
            {mlx::core::reshape(*input, {-1}), mlx::core::reshape(*indices, {-1}),
             mlx::core::reshape(*init, {1}), mlx::core::reshape(*initialIndex, {1})},
            {"input", "indices", "initial", "initial_index"}, {"value", "index"},
            outputShape, {input->dtype(), indexDtype}, {{"T", input->dtype()}, {"I", indexDtype}});
        values.emplace(ToKey(op->getResult(0)), std::move(result[0]));
        values.emplace(ToKey(op->getResult(1)), std::move(result[1]));
        return true;
    }
    auto type = DetectReduceType(reduce.getBody());
    if (type == ReduceType::Unknown)
        throw std::runtime_error("unsupported stablehlo.reduce body/wiring");
    if (!ShapeSize(outputShape) || !reducedSize) {
        values.emplace(ToKey(op->getResult(0)), mlx::core::full(outputShape, *init, input->dtype()));
        return true;
    }
    if (input->dtype() == mlx::core::complex64) {
        if (type != ReduceType::Sum && type != ReduceType::Prod)
            throw std::runtime_error("complex reduce supports sum/product only");
        auto result = axes.empty() ? *input :
            type == ReduceType::Sum ? mlx::core::sum(*input, axes) : mlx::core::prod(*input, axes);
        values.emplace(ToKey(op->getResult(0)), type == ReduceType::Sum ?
            mlx::core::add(*init, result) : mlx::core::multiply(*init, result));
        return true;
    }
    auto source = std::string("T a = initial[0];\n") + offsets +
        "a = " + Combine(type, "a", "input[offset]") + ";\n" +
        "}\nresult[thread_position_in_grid.x] = a;\n";
    auto result = ReductionKernel(source,
        {mlx::core::reshape(*input, {-1}), mlx::core::reshape(*init, {1})},
        {"input", "initial"}, {"result"}, outputShape, {input->dtype()}, {{"T", input->dtype()}});
    values.emplace(ToKey(op->getResult(0)), std::move(result[0]));
    return true;
}

bool HandleReduceWindow(mlir::Operation* op, ValueMap& values,
                        std::vector<mlx::core::array>&, ExecContext&) {
    auto rw = CastOp<mlir::stablehlo::ReduceWindowOp>(op, "stablehlo.reduce_window");
    if (!rw) return false;
    if (rw.getInputs().size() != 1 || rw.getInitValues().size() != 1 || op->getNumResults() != 1)
        throw std::runtime_error("reduce_window requires one binary reducer");
    auto type = DetectReduceType(rw.getBody());
    if (type == ReduceType::Unknown)
        throw std::runtime_error("unsupported stablehlo.reduce_window body/wiring");
    auto* input = RequireValue(values, rw.getInputs()[0], "stablehlo.reduce_window");
    auto* init = RequireValue(values, rw.getInitValues()[0], "stablehlo.reduce_window");
    if (!input || !init) return false;
    if (input->dtype() == mlx::core::complex64)
        throw std::runtime_error("complex reduce_window is unsupported");
    auto shape = GetResultShape(op, "stablehlo.reduce_window");
    if (!shape) return false;
    ShapeSize(input->shape());
    if (!ShapeSize(*shape)) {
        values.emplace(ToKey(op->getResult(0)), mlx::core::full(*shape, *init, input->dtype()));
        return true;
    }
    int rank = input->ndim();
    auto window = rw.getWindowDimensions();
    std::vector<int64_t> stride(rank, 1), baseDil(rank, 1), winDil(rank, 1), low(rank, 0);
    if (auto attr = rw.getWindowStrides())
        std::copy(attr->begin(), attr->end(), stride.begin());
    if (auto attr = rw.getBaseDilations())
        std::copy(attr->begin(), attr->end(), baseDil.begin());
    if (auto attr = rw.getWindowDilations())
        std::copy(attr->begin(), attr->end(), winDil.begin());
    if (auto attr = rw.getPaddingAttr()) {
        auto padding = attr.getValues<int64_t>();
        for (int i = 0; i < rank; ++i)
            low[i] = padding[{static_cast<uint64_t>(i), 0}];
    }
    int64_t windowSize = 1;
    for (int64_t dim : window) {
        if (dim <= 0 || windowSize > std::numeric_limits<int64_t>::max() / dim)
            throw std::runtime_error("reduce_window window exceeds shader loop capacity");
        windowSize *= dim;
    }
    std::ostringstream code;
    code << "T a = initial[0]; ulong q = thread_position_in_grid.x;\n";
    for (int i = rank - 1; i >= 0; --i)
        code << "long o" << i << " = q % " << (*shape)[i] << "ul; q /= "
             << (*shape)[i] << "ul;\n";
    code << "for (ulong w = 0; w < " << windowSize << "ul; ++w) {\n"
         << "ulong k = w, offset = 0; bool valid = true;\n";
    int64_t inputStride = 1;
    for (int i = rank - 1; i >= 0; --i) {
        code << "long p" << i << " = o" << i << " * " << stride[i] << "l - ("
             << low[i] << "l) + long(k % " << window[i] << "ul) * " << winDil[i]
             << "l; k /= " << window[i] << "ul;\n"
             << "valid = valid && p" << i << " >= 0 && p" << i << " % " << baseDil[i]
             << "l == 0 && p" << i << " / " << baseDil[i] << "l < " << input->shape(i)
             << "l;\noffset += ulong(p" << i << " / " << baseDil[i] << "l) * "
             << inputStride << "ul;\n";
        inputStride *= input->shape(i);
    }
    code << "T b = valid ? input[offset] : initial[0];\n"
         << "a = " << Combine(type, "a", "b") << ";\n"
         << "}\nresult[thread_position_in_grid.x] = a;\n";
    // A zero-sized input is never read: every dilated/padded window lane fails
    // the bounds predicate, while still contributing the specified init value.
    auto result = ReductionKernel(code.str(),
        {mlx::core::reshape(*input, {-1}), mlx::core::reshape(*init, {1})},
        {"input", "initial"}, {"result"}, *shape, {input->dtype()}, {{"T", input->dtype()}});
    values.emplace(ToKey(op->getResult(0)), std::move(result[0]));
    return true;
}

// Handler for stablehlo.select_and_scatter (backward pass of max/min pooling)
bool HandleSelectAndScatter(mlir::Operation* op, ValueMap& values,
                            std::vector<mlx::core::array>& outputs, ExecContext& ctx) {
    auto ssOp = CastOp<mlir::stablehlo::SelectAndScatterOp>(op, "stablehlo.select_and_scatter");
    if (!ssOp)
        return false;

    auto* operand = RequireValue(values, ssOp.getOperand(), "stablehlo.select_and_scatter");
    auto* source = RequireValue(values, ssOp.getSource(), "stablehlo.select_and_scatter");
    auto* init = RequireValue(values, ssOp.getInitValue(), "stablehlo.select_and_scatter");
    if (!operand || !source || !init)
        return false;

    auto rank = static_cast<int64_t>(operand->ndim());

    auto windowDimsOpt = ssOp.getWindowDimensions();
    if (!windowDimsOpt) {
        MPS_LOG_ERROR("stablehlo.select_and_scatter: window_dimensions required\n");
        return false;
    }
    auto windowDims = *windowDimsOpt;

    std::vector<int64_t> strides(rank, 1);
    std::vector<int64_t> padLow(rank, 0);
    std::vector<int64_t> padHigh(rank, 0);

    if (auto s = ssOp.getWindowStrides()) {
        for (int64_t i = 0; i < rank; i++)
            strides[i] = (*s)[i];
    }
    if (auto p = ssOp.getPaddingAttr()) {
        auto vals = p.getValues<int64_t>();
        for (int64_t i = 0; i < rank; i++) {
            padLow[i] = vals[{(static_cast<uint64_t>(i)), 0}];
            padHigh[i] = vals[{(static_cast<uint64_t>(i)), 1}];
        }
    }

    // Detect select type: GE/GT => max, LE/LT => min.
    bool selectMax = true;
    {
        auto& body = ssOp.getSelect();
        if (body.empty()) {
            MPS_LOG_ERROR("stablehlo.select_and_scatter: empty select body\n");
            return false;
        }
        bool found = false;
        for (auto& bodyOp : body.front().getOperations()) {
            if (auto cmpOp = mlir::dyn_cast<mlir::stablehlo::CompareOp>(bodyOp)) {
                auto dir = cmpOp.getComparisonDirection();
                selectMax = (dir == mlir::stablehlo::ComparisonDirection::GE ||
                             dir == mlir::stablehlo::ComparisonDirection::GT);
                found = true;
                break;
            }
        }
        if (!found) {
            MPS_LOG_ERROR("stablehlo.select_and_scatter: no compare in select body\n");
            return false;
        }
    }

    // Detect scatter type (typically add for pool gradients).
    ScatterType scatterType = DetectScatterType(ssOp.getScatter());
    if (scatterType != ScatterType::Add) {
        MPS_LOG_ERROR("stablehlo.select_and_scatter: only add scatter supported (got %d)\n",
                      static_cast<int>(scatterType));
        return false;
    }

    // Pad operand with -inf (max) or +inf (min) so padded elements are never selected.
    mlx::core::array paddedOp = *operand;
    bool needsPad = false;
    for (int64_t i = 0; i < rank; i++) {
        if (padLow[i] != 0 || padHigh[i] != 0) {
            needsPad = true;
            break;
        }
    }
    if (needsPad) {
        float padScalar = selectMax ? -std::numeric_limits<float>::infinity()
                                    : std::numeric_limits<float>::infinity();
        auto padVal = mlx::core::full({}, padScalar, operand->dtype());
        std::vector<std::pair<int, int>> padWidth(rank, {0, 0});
        for (int64_t i = 0; i < rank; i++)
            padWidth[i] = {static_cast<int>(padLow[i]), static_cast<int>(padHigh[i])};
        paddedOp = mlx::core::pad(*operand, padWidth, padVal);
    }

    int ndim = static_cast<int>(rank);

    int64_t totalWinPositions = 1;
    for (int64_t i = 0; i < rank; i++)
        totalWinPositions *= windowDims[i];

    auto makeSliceParams = [&](int64_t flatWinIdx) {
        std::vector<int> si(ndim, 0);
        std::vector<int> ei(ndim);
        std::vector<int> st(ndim, 1);
        for (int d = 0; d < ndim; ++d)
            ei[d] = static_cast<int>(paddedOp.shape(d));

        int64_t remaining = flatWinIdx;
        for (int d = ndim - 1; d >= 0; --d) {
            int64_t wd = windowDims[d];
            int64_t offset = remaining % wd;
            remaining /= wd;
            int outSize = static_cast<int>(source->shape(d));
            int str = static_cast<int>(strides[d]);
            si[d] = static_cast<int>(offset);
            ei[d] = static_cast<int>(offset) + outSize * str;
            st[d] = str;
        }
        return std::make_tuple(mlx::core::Shape(si.begin(), si.end()),
                               mlx::core::Shape(ei.begin(), ei.end()),
                               mlx::core::Shape(st.begin(), st.end()));
    };

    // Pass 1: Compute forward pool result
    auto fwdResult = selectMax
                         ? mlx::core::full(source->shape(), -std::numeric_limits<float>::infinity(),
                                           operand->dtype())
                         : mlx::core::full(source->shape(), std::numeric_limits<float>::infinity(),
                                           operand->dtype());

    for (int64_t wi = 0; wi < totalWinPositions; ++wi) {
        auto [si, ei, st] = makeSliceParams(wi);
        auto vals = mlx::core::slice(paddedOp, si, ei, st);
        fwdResult =
            selectMax ? mlx::core::maximum(fwdResult, vals) : mlx::core::minimum(fwdResult, vals);
    }

    // Pass 2: Scatter gradients using first-occurrence mask.
    auto initVal = mlx::core::astype(*init, operand->dtype());
    auto sasResult = mlx::core::broadcast_to(initVal, paddedOp.shape());
    auto won = mlx::core::zeros(source->shape(), mlx::core::bool_);

    for (int64_t wi = 0; wi < totalWinPositions; ++wi) {
        auto [slicerStart, slicerEnd, slicerStride] = makeSliceParams(wi);
        auto inputSlice = mlx::core::slice(paddedOp, slicerStart, slicerEnd, slicerStride);
        auto isMatch = mlx::core::equal(inputSlice, fwdResult);
        auto isFirst = mlx::core::logical_and(isMatch, mlx::core::logical_not(won));
        won = mlx::core::logical_or(won, isFirst);
        auto mask = mlx::core::astype(isFirst, operand->dtype());
        auto gradContrib = mlx::core::multiply(*source, mask);
        auto curSlice = mlx::core::slice(sasResult, slicerStart, slicerEnd, slicerStride);
        sasResult = mlx::core::slice_update(sasResult, mlx::core::add(curSlice, gradContrib),
                                            slicerStart, slicerEnd, slicerStride);
    }

    // If we padded, extract the unpadded region.
    if (needsPad) {
        std::vector<int> sliceStart(ndim, 0);
        std::vector<int> sliceEnd(ndim);
        for (int d = 0; d < ndim; ++d) {
            sliceStart[d] = static_cast<int>(padLow[d]);
            sliceEnd[d] = sliceStart[d] + static_cast<int>(operand->shape(d));
        }
        sasResult =
            mlx::core::slice(sasResult, mlx::core::Shape(sliceStart.begin(), sliceStart.end()),
                             mlx::core::Shape(sliceEnd.begin(), sliceEnd.end()));
    }

    values.emplace(ToKey(op->getResult(0)), std::move(sasResult));
    return true;
}

}  // namespace

void RegisterReductionHandlers(std::unordered_map<std::string, OpHandler>& handlers) {
    handlers.insert({"stablehlo.reduce", HandleReduce});
    handlers.insert({"stablehlo.reduce_window", HandleReduceWindow});
    handlers.insert({"stablehlo.select_and_scatter", HandleSelectAndScatter});
}

}  // namespace jax_mps

