namespace mps {

namespace {

// Set of supported operation names - derived from OpRegistry plus runtime-lowered ops
const std::unordered_set<std::string>& getSupportedOps() {
    static std::unordered_set<std::string> supported = []() {
        auto ops = jax_mps::OpRegistry::GetRegisteredOps();
        // Add ops handled directly in mlx_executable.cc (not via OpRegistry).
        ops.insert("func.return");
        ops.insert("func.call");
        return ops;
    }();
    return supported;
}

// Register all dialects needed for StableHLO parsing
void registerDialects(mlir::MLIRContext& context) {
    // Our StableHLO modules are tiny; MLIR's default per-context LLVM thread
    // pool (hardware_concurrency workers) would otherwise leak ~8 worker
    // threads per compile, since JAX caches the MlxExecutable — and thus its
    // MLIRContext — for the lifetime of the process.
    context.disableMultithreading();
    mlir::DialectRegistry registry;
    registry.insert<mlir::func::FuncDialect>();
    registry.insert<mlir::stablehlo::StablehloDialect>();
    registry.insert<mlir::vhlo::VhloDialect>();
    registry.insert<mlir::chlo::ChloDialect>();
    // JAX 0.12 keeps Shardy enabled and the framework serializes mixed
    // StableHLO + sdy portable artifacts (single-device meshes, sharding
    // attributes on callbacks/constraints). Register the dialect at the exact
    // XLA-pinned revision instead of allowing unregistered dialects.
    registry.insert<mlir::sdy::SdyDialect>();
    // The func dialect's inliner interface (which makes func.call inlinable) lives
    // in a separate extension; without it MLIR's inliner cannot inline any call.
    mlir::func::registerInlinerExtension(registry);
    context.appendDialectRegistry(registry);
    context.loadAllAvailableDialects();
    // Teach the inliner that StableHLO/CHLO ops are inlinable too, so it can
    // inline func.call ops whose bodies are those ops (jnp.std/var/numpyro lower
    // their guard `where` to func.call @_where).
    registerStablehloInlinerInterfaces(context);
}

// Exact constant folding only. Integer/shape/index constant subgraphs are
// folded once at compile time (exact in two's complement); optimizeFloat=false
// keeps every floating-point operation as written. No algebraic simplification
// (x+0 -> x changes signed zeros, x*0 -> 0 drops NaN/inf) and no pattern
// fusion into approximate kernels: the program executes the arithmetic JAX
// emitted.
bool runOptimizationPasses(mlir::MLIRContext& context, mlir::ModuleOp module) {
    mlir::PassManager pm(&context);
    mlir::stablehlo::StablehloAggressiveFolderPassOptions folderOpts;
    folderOpts.optimizeFloat = false;
    pm.addNestedPass<mlir::func::FuncOp>(mlir::stablehlo::createStablehloAggressiveFolderPass(
        folderOpts, mlir::GreedyRewriteConfig()));

    if (mlir::failed(pm.run(module))) {
        MPS_LOG_ERROR("StableHLO constant folding failed\n");
        return false;
    }

    return true;
}

// Inline func.call operations with MLIR's stock inliner. Two interfaces enable
// this (both registered in registerDialects): the func dialect's inliner
// extension makes func.call inlinable, and registerStablehloInlinerInterfaces
// makes StableHLO/CHLO ops inlinable. Together they let the inliner inline the
// guard `where` that jnp.std/var/numpyro lower to a func.call @_where; non-finite
// guard constants are materialized safely (see MaybeBitcastNonFiniteFloat) so the
// inlined grads compile correctly (jax-mps#170). Any call the inliner leaves in
// place is detected in finalizeModule and routed to the eager path.
bool runInlinerPass(mlir::MLIRContext& context, mlir::ModuleOp module) {
    // The inliner only inlines (and then dead-function-eliminates) private
    // callees; jaxlib emits the helpers as public, so mark them private first.
    module.walk([&](mlir::func::FuncOp funcOp) {
        if (funcOp.getName() != "main" && funcOp.isPublic()) {
            funcOp.setPrivate();
        }
    });

    mlir::PassManager pm(&context);
    // The stock default pipeline includes a canonicalizer. Do not let it erase
    // unsupported arithmetic (or rewrite NaN/signed-zero behavior) before type
    // admission; this pass is strictly inlining and dead-callee elimination.
    pm.addPass(mlir::createInlinerPass({}, [](mlir::OpPassManager&) {}));
    // Drop now-dead private callees so the has_uninlined_call scan in
    // finalizeModule only sees func.calls that are actually reachable (a
    // func.call left in a dead function would otherwise needlessly force eager).
    pm.addPass(mlir::createSymbolDCEPass());

    if (mlir::failed(pm.run(module))) {
        MPS_LOG_DEBUG("Inliner pass failed, func.call ops will be handled at runtime\n");
    }
    return true;
}

// Find the entry function (usually "main")
mlir::func::FuncOp findEntryFunction(mlir::ModuleOp module) {
    mlir::func::FuncOp entry = nullptr;

    module.walk([&](mlir::func::FuncOp funcOp) {
        // Prefer "main", otherwise fall back to first function
        if (funcOp.getName() == "main" || !entry) {
            entry = funcOp;
        }
    });

    return entry;
}

// Check for unsupported operations and collect their names
// Walks ALL functions in the module, not just the entry function
std::vector<std::string> checkUnsupportedOps(mlir::ModuleOp module) {
    std::unordered_set<std::string> unsupported_set;
    const auto& supported = getSupportedOps();

    module.walk([&](mlir::Operation* op) {
        // Skip module and function ops themselves
        if (mlir::isa<mlir::ModuleOp>(op) || mlir::isa<mlir::func::FuncOp>(op)) {
            return;
        }
        // Module-level mesh symbols carry no computation; single-device use is
        // enforced in checkSingleDevice.
        if (mlir::isa<mlir::sdy::MeshOp>(op) && mlir::isa<mlir::ModuleOp>(op->getParentOp())) {
            return;
        }

        std::string name = op->getName().getStringRef().str();
        if (supported.find(name) == supported.end()) {
            unsupported_set.insert(name);
        }
    });

    return std::vector<std::string>(unsupported_set.begin(), unsupported_set.end());
}

// The plugin exposes exactly one device. Refuse replicated/partitioned
// programs and Shardy meshes spanning more than one device instead of running
// one shard as if it were the whole computation.
std::string checkSingleDevice(mlir::ModuleOp module) {
    for (const char* name : {"mhlo.num_partitions", "mhlo.num_replicas"}) {
        if (auto attr = module->getAttrOfType<mlir::IntegerAttr>(name)) {
            if (attr.getInt() != 1) {
                return std::string("phydrax-metal: ") + name + "=" +
                       std::to_string(attr.getInt()) +
                       " is not supported; only single-device programs are supported";
            }
        }
    }
    std::string refusal;
    module.walk([&](mlir::sdy::MeshOp mesh) {
        auto meshAttr = mesh.getMesh();
        if (meshAttr.getTotalSize() != 1 || meshAttr.getDeviceIds().size() > 1) {
            refusal = "phydrax-metal: sdy.mesh @" + mesh.getSymName().str() +
                      " spans more than one device; only single-device programs are supported";
            return mlir::WalkResult::interrupt();
        }
        return mlir::WalkResult::advance();
    });
    return refusal;
}

// Only the native IEEE float32 algorithm is implemented. TF32, split BF16,
// lower-precision accumulation, and other algorithm presets must not silently
// become an ordinary MLX contraction. Check before any folding can erase a dot.
std::string checkDotAlgorithms(mlir::ModuleOp module) {
    std::string refusal;
    module.walk([&](mlir::stablehlo::DotGeneralOp dot) {
        auto algorithm = dot->getAttrOfType<mlir::stablehlo::DotAlgorithmAttr>("algorithm");
        if (!algorithm)
            return mlir::WalkResult::advance();
        auto isF32Tensor = [](mlir::Type type) {
            auto shaped = mlir::dyn_cast<mlir::ShapedType>(type);
            return shaped && shaped.getElementType().isF32();
        };
        if (algorithm.getLhsPrecisionType().isF32() &&
            algorithm.getRhsPrecisionType().isF32() &&
            algorithm.getAccumulationType().isF32() &&
            algorithm.getLhsComponentCount() == 1 &&
            algorithm.getRhsComponentCount() == 1 &&
            algorithm.getNumPrimitiveOperations() == 1 &&
            !algorithm.getAllowImpreciseAccumulation() &&
            isF32Tensor(dot->getOperand(0).getType()) &&
            isF32Tensor(dot->getOperand(1).getType()) &&
            isF32Tensor(dot->getResult(0).getType())) {
            return mlir::WalkResult::advance();
        }
        std::string text;
        llvm::raw_string_ostream os(text);
        static_cast<mlir::Attribute>(algorithm).print(os);
        refusal = "phydrax-metal: dot_general algorithm " + text +
                  " is not supported; only F32_F32_F32 with one primitive operation, "
                  "one component per operand, and precise accumulation is supported "
                  "for float32 operands and result";
        return mlir::WalkResult::interrupt();
    });
    return refusal;
}

// Name of an element type Metal cannot represent exactly, or nullopt when the
// type is supported (f32/f16/bf16, complex<f32>, 1/8/16/32/64-bit integers,
// tokens). Metal has no 64-bit floating point, so float64/complex128 are
// refused rather than narrowed.
std::optional<std::string> unsupportedElementType(mlir::Type type) {
    if (auto tuple = mlir::dyn_cast<mlir::TupleType>(type)) {
        for (mlir::Type element : tuple.getTypes()) {
            if (auto name = unsupportedElementType(element))
                return name;
        }
        return std::nullopt;
    }
    if (auto shaped = mlir::dyn_cast<mlir::ShapedType>(type))
        type = shaped.getElementType();
    if (mlir::isa<mlir::stablehlo::TokenType>(type))
        return std::nullopt;
    if (type.isF32() || type.isF16() || type.isBF16())
        return std::nullopt;
    if (type.isF64())
        return "float64";
    if (auto complex = mlir::dyn_cast<mlir::ComplexType>(type)) {
        if (complex.getElementType().isF32())
            return std::nullopt;
        if (complex.getElementType().isF64())
            return "complex128";
    }
    if (auto integer = mlir::dyn_cast<mlir::IntegerType>(type)) {
        switch (integer.getWidth()) {
            case 1:
            case 8:
            case 16:
            case 32:
            case 64:
                return std::nullopt;
            default:
                break;
        }
    }
    std::string name;
    llvm::raw_string_ostream os(name);
    type.print(os);
    return name;
}

// Bounded host preparation of scalar CONSTANT graphs only. This is deliberately
// not a greedy rewrite/floating optimization pass: no runtime operand can be
// discarded by an algebraic identity. Unsupported/large graphs stay unchanged
// for normal type admission. In particular this can prove static solver setup
// through pure, constant-selected error guards without executing callbacks.
mlir::DenseElementsAttr evaluateScalarConstant(mlir::Value value,
                                              unsigned& budget,
                                              unsigned depth = 0) {
    auto type = mlir::dyn_cast<mlir::RankedTensorType>(value.getType());
    if (!type || type.getRank() != 0 || depth >= 64 || budget == 0)
        return {};
    --budget;
    auto* op = value.getDefiningOp();
    if (!op)
        return {};
    if (auto constant = mlir::dyn_cast<mlir::stablehlo::ConstantOp>(op))
        return mlir::dyn_cast<mlir::DenseElementsAttr>(constant.getValue());

    auto evaluate = [&](mlir::Value operand) {
        return evaluateScalarConstant(operand, budget, depth + 1);
    };
    auto integerResult = [&](const llvm::APInt& result) {
        return mlir::DenseIntElementsAttr::get(type, result);
    };
    auto floatResult = [&](const llvm::APFloat& result) {
        return mlir::DenseFPElementsAttr::get(type, result);
    };
    if (auto branch = mlir::dyn_cast<mlir::stablehlo::CaseOp>(op)) {
        auto index = evaluate(op->getOperand(0));
        if (!index || !mlir::isa<mlir::IntegerType>(index.getElementType()))
            return {};
        int64_t selected = (*index.getValues<llvm::APInt>().begin()).getSExtValue();
        auto regions = branch.getBranches();
        if (regions.empty())
            return {};
        if (selected < 0 || static_cast<uint64_t>(selected) >= regions.size())
            selected = regions.size() - 1;
        auto& region = regions[selected];
        // Only a bare return: the chosen branch cannot have hidden effects.
        if (!region.hasOneBlock() || region.front().getOperations().size() != 1)
            return {};
        auto ret = mlir::dyn_cast<mlir::stablehlo::ReturnOp>(region.front().front());
        if (!ret)
            return {};
        return evaluate(ret.getOperand(mlir::cast<mlir::OpResult>(value).getResultNumber()));
    }
    if (op->getNumOperands() == 0 || op->getNumOperands() > 3)
        return {};
    mlir::DenseElementsAttr operands[3];
    for (unsigned i = 0; i < op->getNumOperands(); ++i) {
        operands[i] = evaluate(op->getOperand(i));
        if (!operands[i])
            return {};
    }
    auto name = op->getName().getStringRef();
    auto element = operands[0].getElementType();
    auto intValue = [&](unsigned i) {
        return *operands[i].getValues<llvm::APInt>().begin();
    };
    auto floatValue = [&](unsigned i) {
        return *operands[i].getValues<llvm::APFloat>().begin();
    };
    if (name == "stablehlo.select") {
        if (!element.isInteger(1))
            return {};
        return intValue(0).isZero() ? operands[2] : operands[1];
    }
    if (auto reduce = mlir::dyn_cast<mlir::stablehlo::ReduceOp>(op)) {
        if (!element.isInteger(1) || op->getNumOperands() != 2 ||
            !reduce.getDimensions().empty() || !reduce.getBody().hasOneBlock())
            return {};
        auto& body = reduce.getBody().front();
        if (body.getOperations().size() != 2)
            return {};
        auto& combine = body.front();
        auto ret = mlir::dyn_cast<mlir::stablehlo::ReturnOp>(body.back());
        if (combine.getNumOperands() != 2 || combine.getNumResults() != 1 ||
            combine.getOperand(0) != body.getArgument(0) ||
            combine.getOperand(1) != body.getArgument(1) || !ret ||
            ret.getNumOperands() != 1 || ret.getOperand(0) != combine.getResult(0))
            return {};
        auto reducer = combine.getName().getStringRef();
        if (reducer == "stablehlo.or")
            return integerResult(intValue(0) | intValue(1));
        if (reducer == "stablehlo.and")
            return integerResult(intValue(0) & intValue(1));
        return {};
    }
    if (name == "stablehlo.convert") {
        auto targetFloat = mlir::dyn_cast<mlir::FloatType>(type.getElementType());
        auto targetInt = mlir::dyn_cast<mlir::IntegerType>(type.getElementType());
        if (targetFloat) {
            llvm::APFloat result(targetFloat.getFloatSemantics());
            llvm::APFloat::opStatus status;
            if (mlir::isa<mlir::FloatType>(element)) {
                result = floatValue(0);
                bool losesInfo;
                status = result.convert(targetFloat.getFloatSemantics(),
                                        llvm::RoundingMode::NearestTiesToEven,
                                        &losesInfo);
            } else if (auto sourceInt = mlir::dyn_cast<mlir::IntegerType>(element)) {
                status = result.convertFromAPInt(
                    intValue(0), !sourceInt.isUnsigned() && sourceInt.getWidth() != 1,
                    llvm::RoundingMode::NearestTiesToEven);
            } else {
                return {};
            }
            if ((status & llvm::APFloat::opInvalidOp) != 0)
                return {};
            return floatResult(result);
        }
        if (targetInt && mlir::isa<mlir::IntegerType>(element)) {
            auto source = mlir::cast<mlir::IntegerType>(element);
            auto bits = intValue(0);
            if (targetInt.getWidth() == 1)
                return integerResult(llvm::APInt(1, !bits.isZero()));
            return integerResult(source.isUnsigned() || source.getWidth() == 1
                                     ? bits.zextOrTrunc(targetInt.getWidth())
                                     : bits.sextOrTrunc(targetInt.getWidth()));
        }
        return {};
    }
    if (element.isInteger(1)) {
        if (name == "stablehlo.not")
            return integerResult(~intValue(0));
        if (name == "stablehlo.and")
            return integerResult(intValue(0) & intValue(1));
        if (name == "stablehlo.or")
            return integerResult(intValue(0) | intValue(1));
        if (name == "stablehlo.xor")
            return integerResult(intValue(0) ^ intValue(1));
    }
    if (!mlir::isa<mlir::FloatType>(element))
        return {};
    if (name == "stablehlo.is_finite") {
        auto number = floatValue(0);
        return integerResult(llvm::APInt(1, !number.isNaN() && !number.isInfinity()));
    }
    if (auto compare = mlir::dyn_cast<mlir::stablehlo::CompareOp>(op)) {
        if (compare.getCompareType() != mlir::stablehlo::ComparisonType::FLOAT)
            return {};
        auto order = floatValue(0).compare(floatValue(1));
        using D = mlir::stablehlo::ComparisonDirection;
        bool result;
        switch (compare.getComparisonDirection()) {
            case D::EQ: result = order == llvm::APFloat::cmpEqual; break;
            case D::NE: result = order != llvm::APFloat::cmpEqual; break;
            case D::LT: result = order == llvm::APFloat::cmpLessThan; break;
            case D::LE: result = order == llvm::APFloat::cmpLessThan ||
                                 order == llvm::APFloat::cmpEqual; break;
            case D::GT: result = order == llvm::APFloat::cmpGreaterThan; break;
            case D::GE: result = order == llvm::APFloat::cmpGreaterThan ||
                                 order == llvm::APFloat::cmpEqual; break;
            default: return {};
        }
        return integerResult(llvm::APInt(1, result));
    }
    if (op->getNumOperands() != 2)
        return {};
    auto result = floatValue(0);
    auto rhs = floatValue(1);
    llvm::APFloat::opStatus status;
    if (name == "stablehlo.add")
        status = result.add(rhs, llvm::RoundingMode::NearestTiesToEven);
    else if (name == "stablehlo.subtract")
        status = result.subtract(rhs, llvm::RoundingMode::NearestTiesToEven);
    else if (name == "stablehlo.multiply")
        status = result.multiply(rhs, llvm::RoundingMode::NearestTiesToEven);
    else if (name == "stablehlo.divide")
        status = result.divide(rhs, llvm::RoundingMode::NearestTiesToEven);
    else
        return {};
    if ((status & llvm::APFloat::opInvalidOp) != 0)
        return {};
    return floatResult(result);
}

// Remove only evaluated, now-unused wide scalar producers. Supported producers
// and region-bearing operations stay in the IR, including any effects in cases.
void eraseDeadWideScalar(mlir::Operation* op) {
    if (!op)
        return;
    // A unique worklist avoids dangling references for shared/diamond graphs.
    llvm::SmallSetVector<mlir::Operation*, 8> pending;
    pending.insert(op);
    unsigned budget = 256;
    while (!pending.empty() && budget-- != 0) {
        auto* current = pending.pop_back_val();
        if (current->getNumResults() != 1 ||
            !current->getResult(0).use_empty() || current->getNumRegions() != 0)
            continue;
        auto type = mlir::dyn_cast<mlir::RankedTensorType>(
            current->getResult(0).getType());
        if (!type || !type.getElementType().isF64())
            continue;
        auto name = current->getName().getStringRef();
        if (name != "stablehlo.constant" && name != "stablehlo.convert" &&
            name != "stablehlo.add" && name != "stablehlo.subtract" &&
            name != "stablehlo.multiply" && name != "stablehlo.divide")
            continue;
        for (auto operand : current->getOperands()) {
            if (auto* producer = operand.getDefiningOp())
                pending.insert(producer);
        }
        current->erase();
    }
}

// Normalize explicit casts to supported precision only. Dense literal casts
// retain splats; nonliteral scalar sources must be proven wholly constant by
// the bounded evaluator above. APFloat uses nearest-ties-to-even with signed
// zero/nonfinite semantics; invalid operations remain refused. Allocation
// admission precedes all evaluation, including for splat tensors.
void normalizeLiteralConversions(mlir::ModuleOp module) {
    module.walk([&](mlir::stablehlo::ConvertOp convert) {
        auto source = convert.getOperand();
        auto literal = source.getDefiningOp<mlir::stablehlo::ConstantOp>();
        mlir::DenseFPElementsAttr values;
        if (literal) {
            values = mlir::dyn_cast<mlir::DenseFPElementsAttr>(literal.getValue());
        } else if (auto type = mlir::dyn_cast<mlir::RankedTensorType>(source.getType());
                   type && type.getElementType().isF64()) {
            unsigned budget = 256;
            values = mlir::dyn_cast_or_null<mlir::DenseFPElementsAttr>(
                evaluateScalarConstant(source, budget));
        }
        auto target = mlir::dyn_cast<mlir::FloatType>(convert.getType().getElementType());
        if (!values || !values.getElementType().isF64() || !target ||
            !(target.isF32() || target.isF16() || target.isBF16()))
            return;

        bool invalid = false;
        auto narrowed = values.mapValues(target, [&](const llvm::APFloat& value) {
            llvm::APFloat result = value;
            bool losesInfo;
            auto status = result.convert(target.getFloatSemantics(),
                                         llvm::RoundingMode::NearestTiesToEven,
                                         &losesInfo);
            invalid |= (status & llvm::APFloat::opInvalidOp) != 0;
            return result.bitcastToAPInt();
        });
        if (invalid)
            return;

        mlir::OpBuilder builder(convert);
        auto replacement = builder.create<mlir::stablehlo::ConstantOp>(
            convert.getLoc(), narrowed);
        convert.getResult().replaceAllUsesWith(replacement.getResult());
        convert.erase();
        // Shared wide results remain visible to admission. Only the evaluated
        // pure wide graph is removed; no unrelated dead computation is hidden.
        eraseDeadWideScalar(source.getDefiningOp());
    });
}

// Refuse unsupported inputs, arithmetic, results, and any remaining constants.
// Only explicitly cast constants/fully proven scalar constant graphs have been
// prepared on the host. General folding must not hide runtime wide arithmetic.
std::string checkElementTypes(mlir::ModuleOp module) {
    std::string refusal;
    auto refuse = [&](mlir::Operation* op, mlir::Type type, const std::string& name,
                      const char* role) {
        std::string typeText;
        llvm::raw_string_ostream os(typeText);
        type.print(os);
        refusal = "phydrax-metal: " + name + " is not supported (" +
                  op->getName().getStringRef().str() + " " + role + " " + typeText +
                  "); Metal programs must use float32/complex64";
    };
    module.walk([&](mlir::Operation* op) {
        for (mlir::Type type : op->getResultTypes()) {
            if (auto name = unsupportedElementType(type)) {
                refuse(op, type, *name, "result");
                return mlir::WalkResult::interrupt();
            }
        }
        for (mlir::Region& region : op->getRegions()) {
            for (mlir::Block& block : region) {
                for (mlir::BlockArgument argument : block.getArguments()) {
                    if (auto name = unsupportedElementType(argument.getType())) {
                        refuse(op, argument.getType(), *name, "argument");
                        return mlir::WalkResult::interrupt();
                    }
                }
            }
        }
        if (auto func = mlir::dyn_cast<mlir::func::FuncOp>(op)) {
            for (mlir::Type type : func.getFunctionType().getResults()) {
                if (auto name = unsupportedElementType(type)) {
                    refuse(op, type, *name, "result");
                    return mlir::WalkResult::interrupt();
                }
            }
        }
        return mlir::WalkResult::advance();
    });
    return refusal;
}

// Unsupported element types are refused after constant preparation, not sized.
uint64_t elementBytes(mlir::Type type) {
    if (mlir::isa<mlir::stablehlo::TokenType>(type))
        return 0;
    if (auto complex = mlir::dyn_cast<mlir::ComplexType>(type))
        return 2 * elementBytes(complex.getElementType());
    if (!mlir::isa<mlir::IntegerType, mlir::FloatType>(type))
        return 0;
    const unsigned bits = type.getIntOrFloatBitWidth();
    return (bits + 7) / 8;
}

// Refuse a program if any statically shaped value (input, constant,
// intermediate, result) needs more bytes than one Metal buffer may hold or than
// the MLX allocator's actual memory limit, or has a dimension MLX cannot index
// (int32 shapes). Sizes use checked multiplication; nothing is truncated, and
// the check runs before constant folding or any MLX array exists.
std::string checkAllocationSizes(mlir::ModuleOp module) {
    uint64_t limit = mlx::core::get_memory_limit();
    const auto& info = mlx::core::gpu::device_info(0);
    if (auto it = info.find("max_buffer_length"); it != info.end()) {
        if (const auto* maxBuffer = std::get_if<size_t>(&it->second))
            limit = std::min<uint64_t>(limit, *maxBuffer);
    }
    std::string refusal;
    auto check = [&](mlir::Operation* op, mlir::Type type) {
        auto shaped = mlir::dyn_cast<mlir::RankedTensorType>(type);
        if (!shaped)
            return true;
        uint64_t bytes = elementBytes(shaped.getElementType());
        bool overflow = false;
        for (int64_t dim : shaped.getShape()) {
            if (mlir::ShapedType::isDynamic(dim) || dim < 0 ||
                dim > std::numeric_limits<int32_t>::max()) {
                refusal = "phydrax-metal: dimension " + std::to_string(dim) + " of " +
                          op->getName().getStringRef().str() +
                          " is not supported by Metal's static int32 shapes; not executed";
                return false;
            }
            overflow = overflow || __builtin_mul_overflow(bytes, static_cast<uint64_t>(dim), &bytes);
        }
        if (overflow || bytes > limit) {
            std::string typeText;
            llvm::raw_string_ostream os(typeText);
            type.print(os);
            refusal = "phydrax-metal: " + op->getName().getStringRef().str() + " value " +
                      typeText + " needs " + (overflow ? std::string("more than 2^64") :
                                              std::to_string(bytes)) +
                      " bytes, above the Metal allocation limit of " + std::to_string(limit) +
                      " bytes; not executed";
            return false;
        }
        return true;
    };
    module.walk([&](mlir::Operation* op) {
        for (mlir::Type type : op->getResultTypes()) {
            if (!check(op, type))
                return mlir::WalkResult::interrupt();
        }
        for (mlir::Region& region : op->getRegions()) {
            for (mlir::Block& block : region) {
                for (mlir::BlockArgument argument : block.getArguments()) {
                    if (!check(op, argument.getType()))
                        return mlir::WalkResult::interrupt();
                }
            }
        }
        return mlir::WalkResult::advance();
    });
    return refusal;
}

// Common parsing logic - takes an already-parsed module
ParsedModule finalizeModule(std::unique_ptr<mlir::MLIRContext> context,
                            mlir::OwningOpRef<mlir::ModuleOp> module) {
    ParsedModule result;

    if (!module) {
        return result;
    }

    // Preserve structural/resource evidence before any inlining or folding.
    result.refusal = checkSingleDevice(*module);
    if (result.refusal.empty()) {
        result.refusal = checkDotAlgorithms(*module);
    }
    if (!result.refusal.empty()) {
        return result;
    }
    result.refusal = checkAllocationSizes(*module);
    if (!result.refusal.empty()) {
        result.refusal_code = PJRT_Error_Code_RESOURCE_EXHAUSTED;
        return result;
    }

    // Run the inliner pass to inline all func.call operations
    if (!runInlinerPass(*context, *module)) {
        return result;
    }

    // Admit explicitly cast constants, including bounded scalar constant setup,
    // never wide runtime computation merely because its final result is narrow.
    normalizeLiteralConversions(*module);
    result.refusal = checkElementTypes(*module);
    if (!result.refusal.empty()) {
        return result;
    }

    // Exact constant folding after inlining so it sees fully-inlined IR without
    // func.call ops. Fatal on failure because a failed pass may leave the module
    // partially transformed.
    if (!runOptimizationPasses(*context, *module)) {
        return result;
    }

    // Find the entry function
    mlir::func::FuncOp entry = findEntryFunction(*module);
    if (!entry) {
        return result;
    }

    // Check for unsupported operations across ALL functions in the module
    result.unsupported_ops = checkUnsupportedOps(*module);

    // Detect any func.call that survived inlining (a multi-block callee the
    // inliner could not clone). Flag it so the executable uses the eager path as
    // a safety net rather than compile() (jax-mps#170).
    module->walk([&](mlir::func::CallOp) { result.has_uninlined_call = true; });
    if (result.has_uninlined_call) {
        MPS_LOG_WARN(
            "func.call survived inlining; forcing eager path (no compile) to "
            "avoid jax-mps#170 miscompile\n");
    }

    module->walk([&](mlir::Operation* op) {
        if (jax_mps::IsHostCallback(op)) {
            result.has_host_callbacks = true;
            return mlir::WalkResult::interrupt();
        }
        return mlir::WalkResult::advance();
    });
    if (result.has_host_callbacks && result.has_uninlined_call) {
        result.refusal =
            "phydrax-metal: host callbacks inside a non-inlinable function call are not "
            "supported";
        return result;
    }

    // Transfer ownership
    result.context = std::move(context);
    result.module = std::move(module);
    result.entry_func = entry;

    return result;
}

}  // namespace

const DialectVersions& GetDialectVersions() {
    static const DialectVersions versions = [] {
        const auto current = mlir::vhlo::Version::getCurrentVersion();
        const auto minimum = mlir::vhlo::Version::getMinimumVersion();
        const auto sdy = mlir::sdy::SdyDialectVersion::getCurrentVersion();
        return DialectVersions{
            {current.getMajor(), current.getMinor(), current.getPatch()},
            {minimum.getMajor(), minimum.getMinor(), minimum.getPatch()},
            {sdy.getMajor(), sdy.getMinor(), sdy.getPatch()},
        };
    }();
    return versions;
}

ParsedModule parseStableHLOBytecode(const char* data, size_t size) {
    auto context = std::make_unique<mlir::MLIRContext>();
    registerDialects(*context);

    // Create memory buffer from data
    auto buffer = llvm::MemoryBuffer::getMemBuffer(llvm::StringRef(data, size),
                                                   /*BufferName=*/"stablehlo_bytecode",
                                                   /*RequiresNullTerminator=*/false);

    // Try to deserialize as portable artifact first (handles VHLO versioning)
    mlir::OwningOpRef<mlir::ModuleOp> moduleOp =
        mlir::stablehlo::deserializePortableArtifact(buffer->getBuffer(), context.get());

    if (!moduleOp) {
        // Fall back to regular bytecode reading
        llvm::SourceMgr sourceMgr;
        sourceMgr.AddNewSourceBuffer(std::move(buffer), llvm::SMLoc());

        moduleOp = mlir::parseSourceFile<mlir::ModuleOp>(sourceMgr, context.get());
    }

    return finalizeModule(std::move(context), std::move(moduleOp));
}

ParsedModule parseStableHLOText(const std::string& text) {
    auto context = std::make_unique<mlir::MLIRContext>();
    registerDialects(*context);

    // Parse text format
    mlir::OwningOpRef<mlir::ModuleOp> moduleOp =
        mlir::parseSourceString<mlir::ModuleOp>(text, context.get());

    return finalizeModule(std::move(context), std::move(moduleOp));
}

std::string bytecodeToText(const char* data, size_t size) {
    mlir::MLIRContext context;
    registerDialects(context);

    // Create memory buffer
    auto buffer =
        llvm::MemoryBuffer::getMemBuffer(llvm::StringRef(data, size), "stablehlo_bytecode", false);

    // Deserialize
    mlir::OwningOpRef<mlir::ModuleOp> moduleOp =
        mlir::stablehlo::deserializePortableArtifact(buffer->getBuffer(), &context);

    if (!moduleOp) {
        // Try regular parsing
        llvm::SourceMgr sourceMgr;
        auto bufferCopy = llvm::MemoryBuffer::getMemBuffer(llvm::StringRef(data, size),
                                                           "stablehlo_bytecode", false);
        sourceMgr.AddNewSourceBuffer(std::move(bufferCopy), llvm::SMLoc());
        moduleOp = mlir::parseSourceFile<mlir::ModuleOp>(sourceMgr, &context);
    }

    if (!moduleOp) {
        return "";
    }

    // Print to string
    std::string result;
    llvm::raw_string_ostream os(result);
    moduleOp->print(os);
    return result;
}

}  // namespace mps

