#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <cstdio>

extern "C" int phydrax_capture_start(const char* path) {
    @autoreleasepool {
        MTLCaptureDescriptor* descriptor = [MTLCaptureDescriptor new];
        descriptor.captureObject = MTLCreateSystemDefaultDevice();
        descriptor.destination = MTLCaptureDestinationGPUTraceDocument;
        descriptor.outputURL = [NSURL fileURLWithPath:[NSString stringWithUTF8String:path]];
        NSError* error = nil;
        if (![[MTLCaptureManager sharedCaptureManager] startCaptureWithDescriptor:descriptor error:&error]) {
            std::fprintf(stderr, "Metal capture failed: %s\n", error.localizedDescription.UTF8String);
            return 1;
        }
        return 0;
    }
}

extern "C" void phydrax_capture_stop() {
    [[MTLCaptureManager sharedCaptureManager] stopCapture];
}

