import json
from typing import Any

import phydrax
import jax
import jax.numpy as jnp
import numpy as np
from jax import lax
from jax.experimental import io_callback

if jax.default_backend() != 'mps' or not phydrax.config.x64_enabled():
    raise RuntimeError('Smoke requires explicit MPS with x64 enabled.')

values = np.full(1_000_001, np.float32(1e-8), dtype=np.float32)
values[0] = np.float32(1)
total = jax.jit(lambda x: jnp.sum(x, dtype=jnp.float32))(jax.device_put(values))
error = abs(np.asarray(total).item() - values.sum(dtype=np.float64))
if error > 2e-6:
    raise RuntimeError(f'Parallel sum error {error} exceeds 2e-6.')

@jax.jit
def gather(source: jax.Array, indices: jax.Array) -> jax.Array:
    return lax.map(lambda index: source[index], indices)

source = np.arange(12, dtype=np.float32).reshape(4, 3)
indices = np.asarray([3, 1, 0, 2, 3, 2, 1, 0] * 8, dtype=np.int64)
mapped = gather(jax.device_put(source), jax.device_put(indices))
np.testing.assert_array_equal(np.asarray(mapped), source[indices])

@jax.jit
def scatter_gradient(a: jax.Array, i: jax.Array, u: jax.Array) -> tuple[jax.Array, jax.Array]:
    dimensions = lax.ScatterDimensionNumbers(update_window_dims=(0,), inserted_window_dims=(), scatter_dims_to_operand_dims=(0,))
    def loss(x: jax.Array, y: jax.Array) -> jax.Array:
        return jnp.sum(lax.scatter_add(x, i, y, dimensions, mode='drop', unique_indices=True))
    return jax.grad(loss, argnums=(0, 1))(a, u)

for dtype in (np.int64, np.uint64):
    da, du = scatter_gradient(jax.device_put(np.arange(6, dtype=np.float32)), jax.device_put(np.asarray([2**32], dtype=dtype)), jax.device_put(np.ones(3, dtype=np.float32)))
    np.testing.assert_array_equal(np.asarray(da), np.ones(6, dtype=np.float32))
    np.testing.assert_array_equal(np.asarray(du), np.zeros(3, dtype=np.float32))

calls: list[int] = []
def callback(value: Any) -> np.ndarray:
    calls.append(int(value))
    return np.asarray(value + np.int64(7), dtype=np.int64)

@jax.jit
def ordered(start: jax.Array, selected: jax.Array) -> jax.Array:
    def step(index: jax.Array, carry: jax.Array) -> jax.Array:
        return lax.cond(selected, lambda value: io_callback(callback, jax.ShapeDtypeStruct((), np.int64), value, ordered=True), lambda value: value + np.int64(1), carry)
    return lax.fori_loop(0, 4, step, start)

for selected in (False, True):
    calls.clear()
    result = ordered(jax.device_put(np.int64(2)), jax.device_put(np.bool_(selected)))
    if np.asarray(result).item() != (30 if selected else 6) or calls != ([2, 9, 16, 23] if selected else []):
        raise RuntimeError('Selected ordered callback/token contract failed.')

print(json.dumps({'successful': True, 'sum_error': error, 'sum': np.asarray(total).item(), 'device': str(total.devices()), 'runtime': jax.devices()[0].client.platform_version, 'mapped_rows': mapped.shape[0], 'wide_index_derivatives': True, 'ordered_case_tokens': True}))
